INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hakushun/ai-dev-starter/refactor-react', 'refactor-react', 'hakushun', 'ai-dev-starter', 'community', 'refactor-react hakushun ai-dev-starter community refactor-react is a skill that helps developers efficiently refactor React components, ensuring updated tests and Storybook stories. It benefits React developers working with TypeScript and Storybook. Refactor-react 是一个用于优化 React 代码的工具，帮助开发者更新测试和 Storybook。 React コードのリファクタリングを支援するツールである refactor-react。 리액트 코드를 최적화하는 데 도움을 주는 refactor-react 도구입니다. El refactorizado de React implica actualizar tests y Storybook para asegurar la calidad del código. Aprende a hacerlo de manera efectiva. Le refactoring de React consiste à mettre à jour les tests et Storybook pour assurer la qualité du code. Découvrez comment le faire de manière efficace. Das Refactoring von React beinhaltet die Aktualisierung von Tests und Storybook, um die Qualität des Codes zu gewährleisten. Erfahren Sie, wie Sie es effektiv tun. O refactor-react é uma ferramenta para refatorar componentes React, incluindo testes e Storybook refactor-react - это инструмент для рефакторинга компонентов React, включая тесты и Storybook refactor-react هو أداة لتحديث مكونات React، بما في ذلك الاختبارات و Storybook how to use refactor-react refactor-react setup guide refactor-react vs react-testing-library refactor-react install what is refactor-react refactor-react alternative refactor-react tutorial refactor-react storybook integration refactor-react typescript support Refactor React React 代码优化 测试更新 Storybook 更新 pnpm run test:run pnpm run typecheck React 组件优化 AI 工具 代码重构 Updates corresponding `*.test.tsx` files after refactoring React components Modifies `*.stories.tsx` files to reflect changes in component props and structure Runs `pnpm run test:run` and `pnpm run typecheck` to ensure code integrity Verifies Storybook stories for display issues after refactoring Ensures test assertions and queries are updated to maintain test integrity refactor-react is a technical skill that automates the refactoring process of React components, focusing on updating corresponding tests and Storybook stories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DataCovey/nornweave/commit-push', 'community', 'DataCovey', 'nornweave', 'DataCovey/nornweave', 'commit-push', 0, 0, 20, '2026-03-08T01:57:15.444Z', '2026-03-08T02:09:59.139Z', '1b82155a0d3fc1f9bd24c1ff00934d0dfa5315ae1fcdfc4083b64ce5c9ecee8b', '{"id":"DataCovey/nornweave/commit-push","name":"commit-push","description":{"en":"The commit-push skill turns email providers into Inbox-as-a-Service for AI Agents, utilizing Conventional Commits for standardized commits and pushes.","zh":"Commit-Push是一个开源的自托管API，能够将标准邮件提供商转为Inbox-as-a-Service，支持AI Agents的集成","ja":"Commit-Pushは、標準メールプロバイダーをInbox-as-a-Serviceに変換するオープンソースのセルフホストAPIです。AIエージェントの統合をサポートします","ko":"Commit-Push는 표준 이메일 제공업체를 Inbox-as-a-Service로 변환하는 오픈소스의 자체 호스팅 API로서 AI 에이전트의 통합을 지원","es":"Commit-push es una API de código abierto que convierte proveedores de correo electrónico estándar en un servicio de bandeja de entrada para Agentes de IA","fr":"Commit-push est une API open-source qui transforme les fournisseurs de messagerie électronique standard en un service de boîte de réception pour les Agents IA","de":"Commit-push ist eine Open-Source-API, die Standard-E-Mail-Anbieter in einen Posteingangsdienst für KI-Agents umwandelt","pt":"O commit-push é uma API de código aberto que transforma provedores de e-mail padrão em ''Inbox-as-a-Service'' para ferramentas de IA.","ru":"Commit-push - это открытая API, которая превращает стандартных провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов.","ar":"commit-push هو واجهة برمجة تطبيقات مفتوحة المصدر تحول مزودي البريد الإلكتروني المعيار إلى ''Inbox-as-a-Service'' لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"commit-push: Conventional Commits Setup Guide | AI Agent ...","zh":"Commit-Push Setup Guide: 将标准邮件提供商转为Inbox-as-a-Service","ja":"Commit-Push のベストプラクティス: AIエージェントのためのInbox-as-a-Service","ko":"Commit-Push 설정 가이드: 표준 이메일 제공업체를 Inbox-as-a-Service로 변환","es":"Guía de configuración de commit-push para Agentes de IA","fr":"Guide de mise en place de commit-push pour les Agents IA","de":"Einrichtungsleitfaden für commit-push für KI-Agents","pt":"Commit-Push: Guia de Configuração para Ferramentas de IA","ru":"Commit-Push: Настройка для ИИ Агентов","ar":"Commit-Push: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to integrate commit-push with Mailgun, SES, or SendGrid for AI Agents. Learn to automate commits and pushes with best practices.","zh":"使用Commit-Push将Mailgun、SES、SendGrid等标准邮件提供商转为Inbox-as-a-Service，实现AI Agents的无缝集成","ja":"Commit-Pushを使用して、Mailgun、SES、SendGridなどの標準メールプロバイダーをInbox-as-a-Serviceに変換し、AIエージェントのシームレスな統合を実現","ko":"Commit-Push를 사용하여 Mailgun, SES, SendGrid 등의 표준 이메일 제공업체를 Inbox-as-a-Service로 변환하여 AI 에이전트의 무결점 통합을 실현","es":"Aprende a utilizar commit-push para integrar tus proveedores de correo electrónico con Agentes de IA","fr":"Découvrez comment utiliser commit-push pour intégrer vos fournisseurs de messagerie électronique avec les Agents IA","de":"Erfahren Sie, wie Sie commit-push verwenden, um Ihre E-Mail-Anbieter mit KI-Agents zu integrieren","pt":"Aprenda a configurar o commit-push para transformar provedores de e-mail em ''Inbox-as-a-Service'' para ferramentas de IA","ru":"Узнайте, как настроить commit-push для превращения провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов","ar":"تعرف على كيفية ضبط commit-push لتحويل مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' لأدوات الذكاء الاصطناعي"},"definition":{"en":"commit-push is an open-source API that enables AI Agents to leverage standard email providers as Inbox-as-a-Service.","zh":"Commit-Push是一个开源API，用于将标准邮件提供商转为Inbox-as-a-Service，支持AI Agents","ja":"Commit-Pushは、標準メールプロバイダーをInbox-as-a-Serviceに変換するオープンソースAPIです","ko":"Commit-Push는 표준 이메일 제공업체를 Inbox-as-a-Service로 변환하는 오픈소스 API","es":"Commit-push es una API que permite a los Agentes de IA interactuar con proveedores de correo electrónico","fr":"Commit-push est une API qui permet aux Agents IA d''interagir avec les fournisseurs de messagerie électronique","de":"Commit-push ist eine API, die es KI-Agents ermöglicht, mit E-Mail-Anbietern zu interagieren","pt":"O commit-push é uma API que permite transformar provedores de e-mail em ''Inbox-as-a-Service'' para ferramentas de IA.","ru":"Commit-push - это API, которая позволяет превратить провайдеров электронной почты в ''Inbox-as-a-Service'' для ИИ Агентов.","ar":"commit-push هو واجهة برمجة تطبيقات تمكن من تحويل مزودي البريد الإلكتروني إلى ''Inbox-as-a-Service'' لأدوات الذكاء الاصطناعي."},"features":{"en":["Utilizes Conventional Commits for standardized commit messages","Supports Mailgun, SES, and SendGrid email providers","Automates commits and pushes to the current branch","Follows best practices for commit and push operations","Enables AI Agents to use Inbox-as-a-Service functionality"],"zh":["支持Mailgun、SES、SendGrid等标准邮件提供商","将标准邮件提供商转为Inbox-as-a-Service","支持AI Agents的集成","采用Conventional Commits的最佳实践","开源自托管API"],"ja":["Mailgun、SES、SendGridなどの標準メールプロバイダーのサポート","標準メールプロバイダーをInbox-as-a-Serviceに変換","AIエージェントの統合サポート","Conventional Commitsのベストプラクティスを採用","オープンソースのセルフホストAPI"],"ko":["Mailgun, SES, SendGrid 등의 표준 이메일 제공업체 지원","표준 이메일 제공업체를 Inbox-as-a-Service로 변환","AI 에이전트의 통합 지원","Conventional Commits의 최선의 관행을採用","오픈소스의 자체 호스팅 API"],"es":["Integración con proveedores de correo electrónico como Mailgun, SES y SendGrid","Soporte para commits y push de cambios en la rama actual","Seguimiento de las mejores prácticas de Conventional Commits","Compatibilidad con Agentes de IA para un servicio de bandeja de entrada","Código abierto y autohospedado para una mayor flexibilidad"],"fr":["Intégration avec des fournisseurs de messagerie électronique tels que Mailgun, SES et SendGrid","Prise en charge des commits et push de modifications sur la branche actuelle","Suivi des meilleures pratiques de Conventional Commits","Compatibilité avec les Agents IA pour un service de boîte de réception","Code open-source et auto-hébergé pour une plus grande flexibilité"],"de":["Integration mit E-Mail-Anbietern wie Mailgun, SES und SendGrid","Unterstützung für Commits und Push von Änderungen im aktuellen Branch","Verfolgung der besten Praktiken von Conventional Commits","Kompatibilität mit KI-Agents für einen Posteingangsdienst","Open-Source-Code und Self-Hosting für eine größere Flexibilität"],"pt":["Transforma provedores de e-mail padrão em ''Inbox-as-a-Service''","Suporta Mailgun, SES e SendGrid","Segue as melhores práticas de Conventional Commits","Permite commit e push de alterações em uma sessão de chat","É uma API de código aberto e auto-hospedada"],"ru":["Превращает стандартных провайдеров электронной почты в ''Inbox-as-a-Service''","Поддерживает Mailgun, SES и SendGrid","Следует лучшим практикам Conventional Commits","Позволяет совершать commit и push изменений в сессии чата","Является открытой и自охостной API"],"ar":["تحول مزودي البريد الإلكتروني المعيار إلى ''Inbox-as-a-Service''","يدعم Mailgun و SES و SendGrid","يتبع أفضل الممارسات ل-Conventional Commits","يسمح بالالتزام والدفع بالتغييرات في جلسة محادثة","هي واجهة برمجة تطبيقات مفتوحة المصدر ومضيفة ذاتيًا"]},"keywords":{"en":["how to use commit-push","commit-push setup guide","commit-push alternative","what is commit-push","commit-push vs Mailgun","commit-push install for AI Agents","Conventional Commits tutorial","Inbox-as-a-Service for AI Agents"],"zh":["Commit-Push","Inbox-as-a-Service","AI Agents","Mailgun","SES","SendGrid","Conventional Commits","开源API","自托管API"],"ja":["Commit-Push","Inbox-as-a-Service","AIエージェント","Mailgun","SES","SendGrid","Conventional Commits","オープンソースAPI","セルフホストAPI"],"ko":["Commit-Push","Inbox-as-a-Service","AI 에이전트","Mailgun","SES","SendGrid","Conventional Commits","오픈소스 API","자체 호스팅 API"],"es":["commit-push","Agentes de IA","integración de correo electrónico","Conventional Commits","Mailgun","SES","SendGrid","API de código abierto","autohospedado"],"fr":["commit-push","Agents IA","intégration de messagerie électronique","Conventional Commits","Mailgun","SES","SendGrid","API open-source","auto-hébergé"],"de":["commit-push","KI-Agents","E-Mail-Integration","Conventional Commits","Mailgun","SES","SendGrid","Open-Source-API","Self-Hosting"],"pt":["commit-push","ferramentas de IA","Inbox-as-a-Service","Mailgun","SES","SendGrid","Conventional Commits","API de código aberto","auto-hospedada"],"ru":["commit-push","ИИ Агенты","Inbox-as-a-Service","Mailgun","SES","SendGrid","Conventional Commits","открытая API","自охостная"],"ar":["commit-push","أدوات الذكاء الاصطناعي","Inbox-as-a-Service","Mailgun","SES","SendGrid","Conventional Commits","واجهة برمجة تطبيقات مفتوحة المصدر","مضيفة ذاتيًا"]}},"owner":"DataCovey","repo":"nornweave","repoPath":"DataCovey/nornweave","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.444Z","topics":[],"category":"community","skillMd":{"name":"commit-push","description":"Commit and push the changes made on this chat session to the current branch. Use best practices from Conventional Commits.","bodyPreview":"Commit and push the changes made on this chat session to the current branch. Use best practices from Conventional Commits.","body":"Commit and push the changes made on this chat session to the current branch. Use best practices from Conventional Commits.\n"},"lastSynced":"2026-03-08T02:09:59.139Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing standardized commit and push capabilities using Conventional Commits.","zh":"适合需要使用 Conventional Commits 标准化提交和推送功能的版本控制代理。","ja":"Conventional Commits を使用して標準化されたコミットとプッシュ機能を必要とするバージョン管理エージェントに適しています。","ko":"Conventional Commits를 사용하여 표준화된 커밋 및 푸시 기능을 필요한 버전 관리 에이전트에 적합합니다.","es":"Ideal para agentes de control de versiones que necesitan capacidades de compromiso y empuje estandarizadas utilizando Conventional Commits.","fr":"Idéal pour les agents de contrôle de version nécessitant des capacités de validation et de publication standardisées en utilisant Conventional Commits.","de":"Ideal für Version Control Agents, die standardisierte Commit- und Push-Funktionen unter Verwendung von Conventional Commits benötigen.","pt":"Ideal para Agentes de Controle de Versão que necessitam de capacidades de compromisso e envio padronizadas usando Conventional Commits.","ru":"Идеально для агентов контроля версий, требующих стандартизированных возможностей фиксации и отправки с использованием Conventional Commits.","ar":"مثالي لعمليات مراقبة الإصدار التي تحتاج إلى قدرات الالتزام والإرسال الموحدة باستخدام Conventional Commits."},"recommendation":{"en":"Empowers agents to utilize Conventional Commits for standardized commits and pushes, enabling seamless integration with Inbox-as-a-Service for AI Agents, and leveraging protocols for efficient change management.","zh":"赋予代理使用 Conventional Commits 进行标准化提交和推送的能力，实现与 AI 代理的 Inbox-as-a-Service 无缝集成，并利用协议进行高效的变更管理。","ja":"エージェントに Conventional Commits を使用して標準化されたコミットとプッシュを実行する能力を与え、AI エージェントの Inbox-as-a-Service とシームレスに統合し、变更管理の効率化のためのプロトコルを利用できるようにします。","ko":"에이전트에 Conventional Commits를 사용하여 표준화된 커밋 및 푸시를 수행할 수 있는 능력을 부여하여 AI 에이전트의 Inbox-as-a-Service와의無縫統合을 구현하고, 변경 관리를 위한 프로토콜을 활용할 수 있습니다.","es":"Habilita a los agentes a utilizar Conventional Commits para compromisos y empujes estandarizados, lo que permite una integración sin problemas con Inbox-as-a-Service para agentes de inteligencia artificial y aprovecha los protocolos para una gestión de cambios eficiente.","fr":"Permet aux agents d''utiliser Conventional Commits pour des validations et des publications standardisées, ce qui permet une intégration transparente avec Inbox-as-a-Service pour les agents d''intelligence artificielle et tire parti des protocoles pour une gestion des changements efficace.","de":"Ermächtigt Agenten, Conventional Commits für standardisierte Commits und Push-Vorgänge zu nutzen, wodurch eine nahtlose Integration mit Inbox-as-a-Service für KI-Agents und eine effiziente Änderungsverwaltung durch Protokolle ermöglicht wird.","pt":"Habilita os agentes a utilizarem Conventional Commits para compromissos e envios padronizados, permitindo uma integração perfeita com Inbox-as-a-Service para Agentes de IA e aproveitando protocolos para gerenciamento eficiente de alterações.","ru":"Наделяет агентов возможностью использовать Conventional Commits для стандартизированных фиксаций и отправок, обеспечивая бесшовную интеграцию с Inbox-as-a-Service для агентов ИИ и использует протоколы для эффективного управления изменениями.","ar":"تمكين الوكيل من استخدام Conventional Commits للالتزامات والإرسالات الموحدة، وتمكين التكامل السلس مع Inbox-as-a-Service لعمليات 智慧 الاصطناعي، وتحقيق بروتوكولات لادارة التغييرات بكفاءة."},"useCases":{"en":["Automating commit and push operations for chat session changes","Standardizing commit messages using Conventional Commits","Streamlining branch updates with efficient push protocols"],"zh":["自动执行聊天会话更改的提交和推送操作","使用 Conventional Commits 标准化提交消息","使用高效的推送协议简化分支更新"],"ja":["チャットセッションの変更のコミットとプッシュ操作を自動化する","Conventional Commits を使用してコミットメッセージを標準化する","効率的なプッシュプロトコルを使用してブランチの更新を簡素化する"],"ko":["채팅 세션 변경에 대한 커밋 및 푸시 동작 자동화","Conventional Commits를 사용하여 커밋 메시지 표준화","효율적인 푸시 프로토콜을 사용하여 브랜치 업데이트를 간소화"],"es":["Automatizar operaciones de compromiso y empuje para cambios de sesión de chat","Estandarizar mensajes de compromiso utilizando Conventional Commits","Optimizar actualizaciones de ramas con protocolos de empuje eficientes"],"fr":["Automatiser les opérations de validation et de publication pour les modifications de session de chat","Standardiser les messages de validation en utilisant Conventional Commits","Optimiser les mises à jour de branches avec des protocoles de publication efficaces"],"de":["Automatisieren von Commit- und Push-Operationen für Chat-Sitzungsänderungen","Standardisieren von Commit-Nachrichten unter Verwendung von Conventional Commits","Optimieren von Branch-Updates mit effizienten Push-Protokollen"],"pt":["Automatizar operações de compromisso e envio para alterações de sessão de bate-papo","Padronizar mensagens de compromisso usando Conventional Commits","Otimizar atualizações de branch com protocolos de envio eficientes"],"ru":["Автоматизация операций фиксации и отправки для изменений сеанса чата","Стандартизация сообщений фиксации с использованием Conventional Commits","Оптимизация обновлений веток с эффективными протоколами отправки"],"ar":["أتمتة عمليات الالتزام والإرسال لتغييرات جلسة الدردشة","توحيد رسائل الالتزام باستخدام Conventional Commits","تحسين تحديثات الفروع ببروتوكولات إرسال فعالة"]},"limitations":{"en":["Requires Conventional Commits compatibility","Limited to email providers supporting Inbox-as-a-Service"],"zh":["需要 Conventional Commits 兼容性","仅限支持 Inbox-as-a-Service 的电子邮件提供商"],"ja":["Conventional Commits の互換性が必要","Inbox-as-a-Service をサポートするメールプロバイダーに限定される"],"ko":["Conventional Commits 호환성 필요","Inbox-as-a-Service를 지원하는 이메일 제공업체로 제한"],"es":["Requiere compatibilidad con Conventional Commits","Limitado a proveedores de correo electrónico que admiten Inbox-as-a-Service"],"fr":["Nécessite une compatibilité avec Conventional Commits","Limité aux fournisseurs de messagerie électronique prenant en charge Inbox-as-a-Service"],"de":["Benötigt Kompatibilität mit Conventional Commits","Begrenzt auf E-Mail-Anbieter, die Inbox-as-a-Service unterstützen"],"pt":["Exige compatibilidade com Conventional Commits","Limitado a provedores de e-mail que suportam Inbox-as-a-Service"],"ru":["Требует совместимости с Conventional Commits","Ограничен провайдерами электронной почты, поддерживающими Inbox-as-a-Service"],"ar":["يتطلب توافقًا مع Conventional Commits","محدود بمزودي البريد الإلكتروني الذين يدعمون Inbox-as-a-Service"]},"version":4},"contentHash":"1b82155a0d3fc1f9bd24c1ff00934d0dfa5315ae1fcdfc4083b64ce5c9ecee8b","qualityScore":20}');
