INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shibasab/todoapp/nfr-add-idea', 'nfr-add-idea', 'shibasab', 'todoapp', 'community', 'nfr-add-idea shibasab todoapp community The nfr-add-idea skill provides specific functionalities for AI agents, as outlined in the SKILL.md file. It benefits developers working with AI agents by offering detailed operational guidelines. nfr-add-idea 技术用于 AI 代理开发，提供具体的手顺和更新方法 nfr-add-idea は AIエージェント開発のためのスキルで、具体的な手順と更新方法を提供します nfr-add-idea는 AI 도구와의 통합을 위한 개발자 가이드로 구체적인 개발 방법을 제공합니다 nfr-add-idea es una habilidad que permite agregar ideas a tus Agentes de IA. Consulta el archivo SKILL.md para obtener más información nfr-add-idea est une compétence qui permet d''ajouter des idées à vos Outils d''IA. Consultez le fichier SKILL.md pour obtenir plus d''informations nfr-add-idea ist eine Fähigkeit, die es ermöglicht, Ideen zu Ihren KI-Agenten hinzuzufügen. Siehe die Datei SKILL.md für weitere Informationen O nfr-add-idea é uma skill de AI que permite adicionar ideias de forma eficiente. Saiba mais sobre como configurá-lo. nfr-add-idea - это навык ИИ, позволяющий добавлять идеи эффективно. Узнайте больше о том, как настроить его. nfr-add-idea هي مهارة ذكاء اصطناعي تتيح إضافة أفكار بفعالية. تعرف على المزيد حول كيفية إعدادها. how to use nfr-add-idea nfr-add-idea setup guide what is nfr-add-idea nfr-add-idea alternative nfr-add-idea vs other AI skills nfr-add-idea install for AI agents nfr-add-idea SKILL.md file nfr-add-idea for developers nfr-add-idea AI agent integration nfr-add-idea AI 代理开发 SKILL.md 运用方针 开发环境 AI 工具 开发者指南 References the SKILL.md file for operational guidelines Follows specific handovers and updates as per the SKILL.md content Utilizes the .agents/skills/nfr-add-idea directory structure Operates based on the contents of the SKILL.md file Provides detailed operational guidelines for developers Updates according to the referenced SKILL.md file nfr-add-idea is a skill for AI agents that refers to the SKILL.md file for operational guidelines and updates');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ZStoneDPM/monorepo-template-expo-nexjs/create-brief', 'community', 'ZStoneDPM', 'monorepo-template-expo-nexjs', 'ZStoneDPM/monorepo-template-expo-nexjs', 'create-brief', 0, 0, 20, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:00.816Z', 'a6db2086bf637fc81626311d15d66e36228d06dbb67a791c5d1df4d2226e4eba', '{"id":"ZStoneDPM/monorepo-template-expo-nexjs/create-brief","name":"create-brief","description":{"en":"The create-brief skill generates a product brief based on user-provided descriptions, targeting Expo and Next.js monorepo templates. It benefits developers by providing a solid context for product development.","zh":"Create-Brief技能用于创建Monorepo模板，以便于Expo和NextJS的集成。它提供了项目概述、目标受众、主要功能和高级技术架构","ja":"Create-Briefスキルは、ExpoとNextJSをブリッジするためのモノレポテンプレートを作成するために使用されます。プロジェクトの概要、ターゲットオーディエンス、主な機能、ハイレベルなテクノロジー・アーキテクチャが含まれます","ko":"Create-Brief 기능은 Expo와 NextJS를 연결하기 위한 모노리포 템플릿을 생성하는 데 사용됩니다. 프로젝트 개요, 대상 사용자, 주요 기능 및 고급 기술 아키텍처를 제공합니다","es":"Create-brief es una herramienta para crear un producto breve y conciso para proyectos de monorepo con Expo y NextJS.","fr":"Create-brief est un outil pour créer un produit bref et concis pour les projets de monorepo avec Expo et NextJS.","de":"Create-brief ist ein Werkzeug zum Erstellen eines kurzen und präzisen Produkts für Monorepo-Projekte mit Expo und NextJS.","pt":"O Create-Brief é um template de monorepo para facilitar a integração de Expo e NextJS, permitindo a criação de briefs de produto concisos.","ru":"Create-Brief - это шаблон монорепозитория для легкой интеграции Expo и NextJS, позволяющий создавать краткие продукт-брифы от ИИ Агентов.","ar":"Create-Brief هو قالب مونوريبو لدمج Expo و NextJS بسهولة، مما يسمح بإنشاء ملخصات منتج موجزة"},"seo":{"title":{"en":"create-brief: Monorepo Template Setup Guide | AI Agent Skill","zh":"Create-Brief Setup Guide: 基于Expo和NextJS的Monorepo模板","ja":"Create-Brief セットアップガイド: ExpoとNextJSのモノレポテンプレート","ko":"Create-Brief 설정 가이드: Expo와 NextJS를 위한 모노리포 템플릿","es":"Guía de configuración de create-brief para monorepo de Ex...","fr":"Guide de mise en place de create-brief pour monorepo Expo...","de":"Einrichtungsleitfaden für create-brief in Expo- und NextJ...","pt":"Guia de Configuração do Create-Brief: Monorepo para Expo ...","ru":"Настройка Create-Brief: Шаблон Монорепозитория для Expo и...","ar":"دليل إعداد Create-Brief: قالب مونوريبو ل Expo و NextJS"},"description":{"en":"Discover how to bridge Expo and Next.js with create-brief. Learn to capture business and functional requirements for your product and get started with our co...","zh":"了解Create-Brief技能，使用Expo和NextJS创建Monorepo模板，实现业务和功能需求","ja":"Create-Briefスキルについて学び、ExpoとNextJSでモノレポテンプレートを作成し、ビジネスと機能要件を実現","ko":"Create-Brief 기능에 대해 알아보고 Expo와 NextJS를 사용하여 모노리포 템플릿을 생성하여 비즈니스 및 기능 요구 사항을 충족","es":"Aprende a configurar create-brief para tu proyecto de monorepo con Expo y NextJS. Descubre las mejores prácticas para crear un producto breve y eficaz.","fr":"Découvrez comment configurer create-brief pour votre projet de monorepo avec Expo et NextJS. Apprenez les meilleures pratiques pour créer un produit bref et ...","de":"Erfahren Sie, wie Sie create-brief für Ihr Monorepo-Projekt mit Expo und NextJS konfigurieren. Entdecken Sie die besten Praktiken für die Erstellung eines ku...","pt":"Aprenda a criar um brief de produto com o create-brief, um template de monorepo para integração fácil de Expo e NextJS.","ru":"Узнайте, как создать продукт-бриф с помощью Create-Brief, шаблона монорепозитория для легкой интеграции Expo и NextJS от ИИ Агентов.","ar":"تعلم كيفية إنشاء ملخص منتج مع Create-Brief، قالب مونوريبو لدمج Expo و NextJS بسهولة"},"definition":{"en":"create-brief is a base monorepo template for easy bridging of Expo and Next.js, used for capturing business and functional requirements of a product.","zh":"Create-Brief是用于创建Monorepo模板的技能，用于Expo和NextJS的集成","ja":"Create-Briefは、ExpoとNextJSのブリッジを作成するためのモノレポテンプレートを生成するスキルです","ko":"Create-Brief는 Expo와 NextJS를 연결하기 위한 모노리포 템플릿을 생성하는 기능입니다","es":"Create-brief es una herramienta de creación de productos breves para monorepo","fr":"Create-brief est un outil de création de produits brefs pour monorepo","de":"Create-brief ist ein Werkzeug zur Erstellung von Kurzprodukten für Monorepo","pt":"O Create-Brief é um template de monorepo que facilita a criação de briefs de produto para projetos que utilizam Expo e NextJS.","ru":"Create-Brief - это шаблон монорепозитория, который облегчает создание продукт-брифов для проектов, использующих Expo и NextJS от ИИ Агентов.","ar":"Create-Brief هو قالب مونوريبو يسهل إنشاء ملخصات منتج لمشاريع تستخدم Expo و NextJS"},"features":{"en":["Generates product brief based on user-provided descriptions","Targets Expo and Next.js monorepo templates for easy bridging","Captures business and functional requirements of a product","Provides solid context for others working on the product","Writes document into docs/PRODUCT_BRI for easy reference"],"zh":["基于Expo和NextJS的Monorepo模板","项目概述和描述","目标受众和主要功能","高级技术架构","快速创建产品简介"],"ja":["ExpoとNextJSのモノレポテンプレート","プロジェクトの概要と説明","ターゲットオーディエンスと主な機能","ハイレベルなテクノロジー・アーキテクチャ","製品ブリーフの迅速な作成"],"ko":["Expo와 NextJS를 위한 모노리포 템플릿","프로젝트 개요 및 설명","대상 사용자 및 주요 기능","고급 기술 아키텍처","제품 브리핑의 빠른 생성"],"es":["Plantilla de monorepo base para Expo y NextJS","Creación de un producto breve y conciso","Descripción del proyecto y del público objetivo","Beneficios y características principales","Arquitectura técnica de alto nivel"],"fr":["Modèle de monorepo de base pour Expo et NextJS","Création d''un produit bref et concis","Description du projet et du public cible","Avantages et fonctionnalités principales","Architecture technique de haut niveau"],"de":["Basis-Monorepo-Vorlage für Expo und NextJS","Erstellung eines kurzen und präzisen Produkts","Projektbeschreibung und Zielgruppe","Hauptvorteile und -funktionen","Technische Architektur auf hohem Niveau"],"pt":["Template de monorepo para Expo e NextJS","Criação de briefs de produto concisos","Integração fácil de Expo e NextJS","Arquitetura de alto nível para projetos","Documentação em docs/PRODUCT_BRI"],"ru":["Шаблон монорепозитория для Expo и NextJS","Создание кратких продукт-брифов","Легкая интеграция Expo и NextJS","Высокоуровневая архитектура для проектов","Документация в docs/PRODUCT_BRI от ИИ Агентов"],"ar":["قالب مونوريبو ل Expo و NextJS","إنشاء ملخصات منتج موجزة","دمج Expo و NextJS بسهولة","هندسة معمارية عالية المستوى لمشاريع","توثيق في docs/PRODUCT_BRI"]},"keywords":{"en":["how to use create-brief","create-brief monorepo template","Expo and Next.js integration","product brief generation","create-brief setup guide","create-brief alternative","create-brief vs other templates"],"zh":["Create-Brief","Expo","NextJS","Monorepo","项目简介","产品简介","AIエージェント","技术架构"],"ja":["Create-Brief","Expo","NextJS","モノレポ","プロジェクトブリーフ","製品ブリーフ","AIエージェント","テクノロジー・アーキテクチャ"],"ko":["Create-Brief","Expo","NextJS","모노리포","프로젝트 브리핑","제품 브리핑","AI 에이전트","기술 아키텍처"],"es":["create-brief","monorepo","Expo","NextJS","producto breve","creación de productos","desarrollo de software","herramientas de desarrollo"],"fr":["create-brief","monorepo","Expo","NextJS","produit bref","création de produits","développement de logiciels","outils de développement"],"de":["create-brief","Monorepo","Expo","NextJS","Kurzprodukt","Produktentwicklung","Softwareentwicklung","Entwicklungstools"],"pt":["create-brief","monorepo","Expo","NextJS","brief de produto","integração de tecnologias","desenvolvimento de software","template de monorepo","arquitetura de software"],"ru":["create-brief","монорепозиторий","Expo","NextJS","продукт-бриф","интеграция технологий","разработка программного обеспечения","шаблон монорепозитория","архитектура программного обеспечения от ИИ Агентов"],"ar":["create-brief","مونوريبو","Expo","NextJS","ملخص منتج","دمج تكنولوجيا","تطوير برمجيات","قالب مونوريبو","هندسة برمجيات"]}},"owner":"ZStoneDPM","repo":"monorepo-template-expo-nexjs","repoPath":"ZStoneDPM/monorepo-template-expo-nexjs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.484Z","topics":[],"category":"community","skillMd":{"name":"create-brief","description":"Create a product brief based on user description","bodyPreview":"Please create a product brief based on the description that the user provides. Your goal is to capture the business and functional requirements of the product and to provide solid context for others working on the product. You should include:\n\nProject overview / description\nTarget audience\nPrimary benefits / features\nHigh-level tech/architecture used\nKeep the brief very concise and to the point just to give enough context to understand the bigger picture. Write the document into docs/PRODUCT_BRI","body":"Please create a product brief based on the description that the user provides. Your goal is to capture the business and functional requirements of the product and to provide solid context for others working on the product. You should include:\n\nProject overview / description\nTarget audience\nPrimary benefits / features\nHigh-level tech/architecture used\nKeep the brief very concise and to the point just to give enough context to understand the bigger picture. Write the document into docs/PRODUCT_BRIEF.md (unless a different file name is specified)\n"},"lastSynced":"2026-03-08T02:10:00.816Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing concise product brief generation for Expo and Next.js monorepo templates.","zh":"非常适合需要为 Expo 和 Next.js monorepo 模板生成简洁产品简介的开发代理。","ja":"Expo と Next.js monorepo テンプレートのための簡潔な製品の概要を生成する必要がある開発エージェントに最適です。","ko":"Expo 및 Next.js monorepo 템플릿을 위한 간결한 제품 요약을 생성해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una generación concisa de descripciones de productos para plantillas de monorepo de Expo y Next.js.","fr":"Parfait pour les agents de développement ayant besoin d''une génération concise de descriptions de produits pour les modèles de monorepo Expo et Next.js.","de":"Perfekt für Entwicklungsmittel, die eine präzise Erstellung von Produktbeschreibungen für Expo- und Next.js-Monorepo-Vorlagen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de geração concisa de brief de produto para modelos de monorepo do Expo e Next.js.","ru":"Идеально подходит для агентов разработки, которым требуется краткая генерация описания продукта для шаблонов monorepo Expo и Next.js.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توليد مختصر لملخص المنتج لأنماط مونوربو اكسبو و نكست دوت جس."},"recommendation":{"en":"Empowers agents to capture business and functional requirements using high-level tech and architecture descriptions, including project overviews, target audiences, and primary benefits, all within a concise product brief document stored in the docs/PRODUCT_BRIEF directory.","zh":"赋予代理捕获业务和功能需求的能力，使用高级技术和架构描述，包括项目概述、目标受众和主要优点，所有这些都在 docs/PRODUCT_BRIEF 目录中存储的简洁产品简介文档中。","ja":"エージェントが、高レベルの技術とアーキテクチャの説明を使用してビジネス要件と機能要件を把握する能力を与えます。プロジェクトの概要、ターゲットオーディエンス、主な利点などを含む、docs/PRODUCT_BRIEF ディレクトリに保存された簡潔な製品の概要文書。","ko":"에이전트가 높은 수준의 기술 및 아키텍처 설명을 사용하여 비즈니스 및 기능 요구 사항을 캡처할 수 있는 능력을 부여합니다. 프로젝트 개요, 대상 аудитор리 및 주요 이점 등을 포함하여 docs/PRODUCT_BRIEF 디렉토리에 저장된 간결한 제품 요약 문서.","es":"Habilita a los agentes a capturar requisitos comerciales y funcionales utilizando descripciones técnicas y arquitectónicas de alto nivel, incluyendo descripciones generales del proyecto, audiencias objetivo y beneficios principales, todos dentro de un documento de descripción de producto conciso almacenado en el directorio docs/PRODUCT_BRIEF.","fr":"Permet aux agents de capturer les exigences commerciales et fonctionnelles en utilisant des descriptions techniques et architecturales de haut niveau, y compris les descriptions générales du projet, les publics cibles et les avantages principaux, le tout dans un document de description de produit concis stocké dans le répertoire docs/PRODUCT_BRIEF.","de":"Ermöglicht es Agenten, Geschäftsanforderungen und funktionale Anforderungen unter Verwendung von hochrangigen technischen und Architekturbeschreibungen zu erfassen, einschließlich Projektdescriptions, Zielgruppen und primäre Vorteile, alle innerhalb eines präzisen Produktbeschreibungsdokuments, das im Verzeichnis docs/PRODUCT_BRIEF gespeichert ist.","pt":"Permite que os agentes capturem requisitos de negócios e funcionais usando descrições de tecnologia e arquitetura de alto nível, incluindo visões gerais de projetos, públicos-alvo e benefícios principais, tudo dentro de um documento de brief de produto conciso armazenado no diretório docs/PRODUCT_BRIEF.","ru":"Позволяет агентам捕урить бизнес- и функциональные требования с помощью высокоуровневых технических и архитектурных описаний, включая обзоры проектов, целевые аудитории и основные преимущества, все в кратком документе описания продукта, хранящемся в каталоге docs/PRODUCT_BRIEF.","ar":"يمكن للوكيل التقاط متطلبات الأعمال والوظيفية باستخدام وصفات تقنية وهندسية عالية المستوى، بما في ذلك لمحة عامة عن المشاريع، والجمهور المستهدف، والفوائد الرئيسية، كل ذلك داخل وثيقة ملخص المنتج الموجزة المخزنة في الدليل docs/PRODUCT_BRIEF."},"useCases":{"en":["Generating product briefs for new Expo projects","Creating concise project descriptions for Next.js monorepo templates","Capturing target audience and primary benefits for development teams"],"zh":["为新的 Expo 项目生成产品简介","为 Next.js monorepo 模板创建简洁的项目描述","捕获开发团队的目标受众和主要优点"],"ja":["新しい Expo プロジェクトのための製品の概要を生成する","Next.js monorepo テンプレートのための簡潔なプロジェクトの説明を作成する","開発チームのターゲットオーディエンスと主な利点を把握する"],"ko":["新的 Expo 프로젝트를 위한 제품 요약을 생성하는 것","Next.js monorepo 템플릿을 위한 간결한 프로젝트 설명을 만드는 것","개발 팀의 대상 受众 및 주요 이점을 캡처하는 것"],"es":["Generación de descripciones de productos para nuevos proyectos Expo","Creación de descripciones de proyectos concisas para plantillas de monorepo de Next.js","Captura de la audiencia objetivo y los beneficios principales para los equipos de desarrollo"],"fr":["Génération de descriptions de produits pour les nouveaux projets Expo","Création de descriptions de projets concises pour les modèles de monorepo Next.js","Capture de la audience cible et des avantages principaux pour les équipes de développement"],"de":["Erstellung von Produktbeschreibungen für neue Expo-Projekte","Erstellung von präzisen Projektdescriptions für Next.js-Monorepo-Vorlagen","Erfassung der Zielgruppe und der primären Vorteile für Entwicklungsteams"],"pt":["Geração de briefs de produto para novos projetos Expo","Criação de descrições de projeto concisas para modelos de monorepo Next.js","Captura de público-alvo e benefícios principais para equipes de desenvolvimento"],"ru":["Генерация описаний продукта для новых проектов Expo","Создание кратких описаний проектов для шаблонов monorepo Next.js","Захват целевой аудитории и основных преимуществ для команд разработки"],"ar":["توليد ملخصات المنتج لمشاريع اكسبو الجديدة","إنشاء وصفات مشروع مختصرة لأنماط مونوربو نكست دوت جس","التقاط الجمهور المستهدف والفوائد الرئيسية لفريق التطوير"]},"limitations":{"en":["Requires user-provided product descriptions","Limited to Expo and Next.js monorepo templates","Output is a text-based product brief document"],"zh":["需要用户提供的产品描述","仅限于 Expo 和 Next.js monorepo 模板","输出是一个基于文本的产品简介文档"],"ja":["ユーザー提供の製品の説明が必要","Expo と Next.js monorepo テンプレートのみ","出力はテキストベースの製品の概要文書"],"ko":["사용자 제공 제품 설명이 필요함","Expo 및 Next.js monorepo 템플릿에만 限","출력은 텍스트 기반 제품 요약 문서"],"es":["Requiere descripciones de productos proporcionadas por el usuario","Limitado a plantillas de monorepo de Expo y Next.js","La salida es un documento de descripción de producto basado en texto"],"fr":["Nécessite des descriptions de produits fournies par l''utilisateur","Limité aux modèles de monorepo Expo et Next.js","La sortie est un document de description de produit basé sur du texte"],"de":["Benötigt vom Benutzer bereitgestellte Produktbeschreibungen","Begrenzt auf Expo- und Next.js-Monorepo-Vorlagen","Die Ausgabe ist ein textbasiertes Produktbeschreibungsdokument"],"pt":["Requer descrições de produto fornecidas pelo usuário","Limitado a modelos de monorepo do Expo e Next.js","A saída é um documento de brief de produto baseado em texto"],"ru":["Требует описаний продукта, предоставляемых пользователем","Ограничен шаблонами monorepo Expo и Next.js","Выходные данные представляют собой текстовый документ описания продукта"],"ar":["يتطلب وصفات المنتج المقدمة من قبل المستخدم","محدود لأنماط مونوربو اكسبو و نكست دوت جس","الخرج هو وثيقة ملخص المنتج القائمة على النص"]},"version":4},"contentHash":"a6db2086bf637fc81626311d15d66e36228d06dbb67a791c5d1df4d2226e4eba","qualityScore":20}');
