INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brainsum/brainsum-starterkit/increase-package-version', 'increase-package-version', 'brainsum', 'brainsum-starterkit', 'community', 'increase-package-version brainsum brainsum-starterkit community The increase-package-version skill automates package version updates for Drupal 8-10 starter themes, benefiting developers by streamlining version management. It updates package.json, brainsum_starterkit.info.yml, and brainsum_starterkit.starterkit.yml files. increase-package-version 是一个用于更新包版本号的 AIエージェント，支持 package.json 和 README.md 文件 increase-package-version はパッケージバージョンを更新する AIエージェントです。package.json と README.md をサポートしています increase-package-version 는 패키지 버전을 업데이트 하는 AI 도구입니다. package.json 및 README.md 파일을 지원합니다 La herramienta de AI Agent ''increase-package-version'' actualiza la versión del paquete en Drupal 8-10, modificando archivos como package.json y brainsum_starterkit.info.yml L''outil d''AI Agent ''increase-package-version'' met à jour la version du paquet dans Drupal 8-10, en modifiant des fichiers tels que package.json et brainsum_starterkit.info.yml Das AI-Tool ''increase-package-version'' aktualisiert die Paketversion in Drupal 8-10, indem es Dateien wie package.json und brainsum_starterkit.info.yml ändert O increase-package-version é uma ferramenta que atualiza a versão do pacote em arquivos como package.json e brainsum_starterkit.info.yml ИИ Агент increase-package-version обновляет версию пакета в файлах package.json, brainsum_starterkit.info.yml и других أداة ذكية increase-package-version تحديث إصدار الحزمة في ملفات مثل package.json و brainsum_starterkit.info.yml how to use increase-package-version increase-package-version setup guide automated package versioning increase-package-version alternative update package.json version Drupal 8-10 starter theme versioning increase-package-version install version management for developers increase-package-version AIエージェント 包版本号更新 package.json README.md 自动更新版本号 手动设置版本号 Retrieves current version numbers from package.json files Updates version numbers in package.json, brainsum_starterkit.info.yml, and brainsum_starterkit.starterkit.yml files Extracts last updated dates from README.md files Updates README.md files with new version information Supports automated versioning for Drupal 8-10 starter themes Modifies brainsum_starterkit.info.yml and brainsum_starterkit.starterkit.yml files for consistent versioning increase-package-version is a skill that automates the process of updating package version numbers in various files, including package.json and YAML files, for efficient version management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AlbanoArranz/Traductor-Documentacion-Tecnica/idear-diseno', 'community', 'AlbanoArranz', 'Traductor-Documentacion-Tecnica', 'AlbanoArranz/Traductor-Documentacion-Tecnica', 'idear-diseno', 0, 0, 20, '2026-03-08T01:57:15.522Z', '2026-03-08T02:10:49.113Z', '41d5e48cb40674191948ba3d6982d696afbcf0ce5b03eeda798035e408b08aab', '{"id":"AlbanoArranz/Traductor-Documentacion-Tecnica/idear-diseno","name":"idear-diseno","description":{"en":"idear-diseno is a skill that enables the conversion of ideas into validated designs through collaborative dialogue, benefiting developers and project managers. It streamlines the design process by revising project context and understanding ideas through targeted questioning.","zh":"Idear Diseño skill通过对话式协作，帮助开发者将想法转化为有效设计和规范，提高开发效率","ja":"Idear Diseñoスキルは、開発者がアイデアを有効な設計と仕様に変換するのに役立ちます","ko":"Idear Diseño 스킬은 개발자가 아이디어를 유효한 디자인과 사양으로 변환하는 것을 도와줍니다","es":"Idear-Diseno es una habilidad que permite convertir ideas en diseños validados a través de diálogo colaborativo, revisando el contexto del proyecto y entendiendo la idea con preguntas","fr":"Idear-Diseno est une compétence qui permet de convertir des idées en conceptions validées via un dialogue collaboratif, en révisant le contexte du projet et en compréhendant l''idée avec des questions","de":"Idear-Diseno ist eine Fähigkeit, die es ermöglicht, Ideen in validierte Entwürfe durch kollaborativen Dialog umzuwandeln, indem der Projektcontext überprüft und die Idee mit Fragen verstanden wird","pt":"O Idear-Diseno é uma habilidade que permite converter ideias em designs validados através de diálogo colaborativo, revisando o contexto do projeto e entendendo as ideias com perguntas","ru":"ИИ Агент Idear-Diseno - это навык, который позволяет преобразовать идеи в действенные дизайны посредством сотрудничества, проверки контекста и понимания идей","ar":"Idear-Diseno هو مهارة تسمح بتحويل الأفكار إلى تصاميم صالحة من خلال حوار تعاوني، مع مراجعة سياق المشروع وفهم الأفكار"},"seo":{"title":{"en":"idear-diseno: Collaborative Design Setup Guide | AI Agent...","zh":"Idear Diseño Setup Guide: AI智能工具协作设计","ja":"Idear Diseñoベストプラクティス: AIエージェントを使用した設計","ko":"Idear Diseño 구축 가이드: AI 에이전트를 활용한 협업 디자인","es":"Guía de configuración de Idear-Diseno para desarrolladores","fr":"Configurer Idear-Diseno pour les développeurs : Meilleure...","de":"Einrichten von Idear-Diseno: Leitfaden für Entwickler","pt":"Guia de Configuração do Idear-Diseno: Desenvolvimento Col...","ru":"Настройка ИИ Агентов: Idear-Diseno для сотрудничества в р...","ar":"دليل إعداد Idear-Diseno: تصميم وتطوير تعاوني"},"description":{"en":"Unlock efficient project design with idear-diseno. Discover how to convert ideas into validated designs through collaborative dialogue and get started today!","zh":"了解Idear Diseño skill如何通过对话式协作将想法转化为有效设计和规范，提高开发效率","ja":"Idear Diseñoスキルを使用して、アイデアを有効な設計と仕様に変換する方法を学びましょう","ko":"Idear Diseño 스킬을 통해 대화형 협력을 통해 아이디어를 유효한 디자인과 사양으로 변환하는 방법을 알아보세요","es":"Aprende a configurar Idear-Diseno para mejorar tu flujo de trabajo en el desarrollo de software con diálogo colaborativo","fr":"Découvrez comment configurer Idear-Diseno pour améliorer votre flux de travail en développement logiciel avec dialogue collaboratif","de":"Erfahren Sie, wie Sie Idear-Diseno einrichten, um Ihren Arbeitsablauf in der Softwareentwicklung mit kollaborativem Dialog zu verbessern","pt":"Aprenda a configurar o Idear-Diseno para desenvolvimento colaborativo de design, com revisão de contexto e entendimento de ideias","ru":"Узнайте, как настроить ИИ Агент Idear-Diseno для совместной разработки дизайна, с проверкой контекста и пониманием идей","ar":"تعرف على كيفية إعداد Idear-Diseno لتصميم وتطوير تعاوني، مع مراجعة السياق وفهم الأفكار"},"definition":{"en":"idear-diseno is a collaborative design skill that facilitates the conversion of ideas into validated designs and specifications through a dialogue-driven approach.","zh":"Idear Diseño是AI智能工具的一种，用于协助设计和规范的生成","ja":"Idear Diseñoは、設計と仕様の生成を支援するAIエージェントの一種です","ko":"Idear Diseño는 디자인과 사양의 생성을 지원하는 AI 에이전트의 한 종류입니다","es":"Idear-Diseno es una habilidad de diseño que utiliza diálogo colaborativo para validar ideas y crear especificaciones","fr":"Idear-Diseno est une compétence de conception qui utilise un dialogue collaboratif pour valider les idées et créer des spécifications","de":"Idear-Diseno ist eine Designfähigkeit, die kollaborativen Dialog verwendet, um Ideen zu validieren und Spezifikationen zu erstellen","pt":"O que é Idear-Diseno? É uma habilidade de design que converte ideias em especificações validadas","ru":"Что такое ИИ Агент Idear-Diseno? Это навык дизайна, который преобразует идеи в проверенные спецификации","ar":"ما هو Idear-Diseno؟ هو مهارة تصميم تحول الأفكار إلى مواصفات صالحة"},"features":{"en":["Revises project context by examining key files and conventions","Understands ideas through a series of targeted questions, one per message","Proposes design solutions based on collaborative dialogue","Validates designs and specifications through iterative feedback","Addresses ambiguity and missing requirements in project design","Facilitates changes in project behavior or architecture"],"zh":["项目背景审查","通过对话理解想法","提出设计建议","支持设计和规范的生成","提高开发效率","支持多种开发场景"],"ja":["プロジェクト背景の確認","対話を通じたアイデアの理解","設計提案","設計と仕様の生成を支援","開発効率の向上","多種多様な開発シナリオをサポート"],"ko":["프로젝트 배경 검토","대화를 통해 아이디어 이해","디자인 제안","디자인과 사양의 생성을 지원","개발 효율성 향상","다양한 개발 시나리오 지원"],"es":["Revisión de contexto del proyecto","Diálogo colaborativo para entender la idea","Propuesta de diseño y especificación validados","Flujo de trabajo personalizable","Integración con archivos clave y convenciones"],"fr":["Révision du contexte du projet","Dialogue collaboratif pour comprendre l''idée","Proposition de conception et de spécifications validées","Flux de travail personnalisable","Intégration avec des fichiers clés et des conventions"],"de":["Überprüfung des Projektcontext","Kollaborativer Dialog zum Verstehen der Idee","Vorschlag für validierte Entwürfe und Spezifikationen","Anpassbarer Arbeitsablauf","Integration mit Schlüsseldateien und Konventionen"],"pt":["Revisão de contexto do projeto","Entendimento de ideias com perguntas","Proposta de designs validados","Desenvolvimento colaborativo","Revisão de arquivos chave e convencões","Entendimento de invariantes"],"ru":["Проверка контекста проекта","Понимание идей с вопросами","Предложение проверенных дизайнов","Совместная разработка","Проверка ключевых файлов и соглашений","Понимание инвариантов"],"ar":["مراجعة سياق المشروع","فهم الأفكار بالأسئلة","اقتراح تصاميم صالحة","التطوير التعاوني","مراجعة الملفات الرئيسية والاتفاقيات","فهم الثوابت"]},"keywords":{"en":["how to use idear-diseno","idear-diseno setup guide","collaborative design tools","idear-diseno vs traditional design methods","idear-diseno install","what is idear-diseno","idear-diseno alternative","idear-diseno for AI agents","collaborative dialogue in design","validated design specifications"],"zh":["AI智能工具","Idear Diseño","协作设计","设计和规范生成","开发效率","项目背景审查","对话式协作","设计建议","开发场景"],"ja":["AIエージェント","Idear Diseño","設計と仕様","開発効率","プロジェクト背景","対話を通じた設計","設計提案","開発シナリオ"],"ko":["AI 에이전트","Idear Diseño","협업 디자인","디자인과 사양 생성","개발 효율성","프로젝트 배경","대화형 협업","디자인 제안","개발 시나리오"],"es":["idear diseno","diseño de software","diálogo colaborativo","desarrollo de software","flujo de trabajo","integración de archivos","convenciones de proyecto","herramientas de diseño","AI Agentes"],"fr":["idear diseno","conception de logiciel","dialogue collaboratif","développement de logiciel","flux de travail","intégration de fichiers","conventions de projet","outils de conception","Agents IA"],"de":["idear diseno","Software-Design","kollaborativer Dialog","Software-Entwicklung","Arbeitsablauf","Integration von Dateien","Projekt-Konventionen","Design-Tools","KI-Agenten"],"pt":["idear diseno","desenvolvimento colaborativo","design validado","revisão de contexto","entendimento de ideias","proposta de design","desenvolvimento de software","ferramentas de design","ai agents","desenvolvedores"],"ru":["ИИ Агенты","Идеар Дизайн","Совместная разработка","Проверенный дизайн","Проверка контекста","Понимание идей","Предложение дизайна","Разработка программного обеспечения","Инструменты дизайна","ИИ Агент Idear-Diseno","Разработчики"],"ar":["أدوات الذكاء الاصطناعي","ايديار ديزاين","التطوير التعاوني","تصميم صالحة","مراجعة السياق","فهم الأفكار","اقتراح تصميم","تطوير البرمجيات","أدوات التصميم","ايديار ديزاين","المطورون"]}},"owner":"AlbanoArranz","repo":"Traductor-Documentacion-Tecnica","repoPath":"AlbanoArranz/Traductor-Documentacion-Tecnica","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.522Z","topics":[],"category":"community","skillMd":{"name":"idear-diseno","description":"Refina ideas en un diseño validado antes de tocar código. Úsese cuando el usuario pida crear features, modificar comportamiento, diseñar una solución o explorar alternativas.","bodyPreview":"# Idear y diseñar\n\n## Overview\nConvertir una idea en un diseño y especificación validados a través de diálogo colaborativo.\n\n## Cuándo usar esta skill\n- Cuando el usuario diga \"vamos a construir\" o pida una feature nueva.\n- Cuando el usuario pida cambiar comportamiento o arquitectura.\n- Cuando falten requisitos o haya ambigüedad.\n\n## Flujo de trabajo\n- [ ] Revisar contexto del proyecto (archivos clave, convenciones, invariantes).\n- [ ] Entender la idea con preguntas: 1 por mensaje.\n- [ ] Propone","body":"# Idear y diseñar\n\n## Overview\nConvertir una idea en un diseño y especificación validados a través de diálogo colaborativo.\n\n## Cuándo usar esta skill\n- Cuando el usuario diga \"vamos a construir\" o pida una feature nueva.\n- Cuando el usuario pida cambiar comportamiento o arquitectura.\n- Cuando falten requisitos o haya ambigüedad.\n\n## Flujo de trabajo\n- [ ] Revisar contexto del proyecto (archivos clave, convenciones, invariantes).\n- [ ] Entender la idea con preguntas: 1 por mensaje.\n- [ ] Proponer 2-3 enfoques con trade-offs.\n- [ ] Presentar el diseño en secciones cortas y validar cada sección.\n- [ ] Guardar el diseño validado en `docs/plans/YYYY-MM-DD-<topic>-design.md`.\n- [ ] Cerrar con decisiones + riesgos + próximos pasos.\n\n## Instrucciones\n### Planificar\n- Antes de preguntar, obtener contexto mínimo del proyecto:\n  - Revisar `AGENTS.md` si existe.\n  - Identificar entrypoints y archivos autoritativos.\n  - Revisar el estado actual (archivos relevantes y, si aplica, commits recientes).\n\n### Validar\n- Hacer preguntas **una por una** (máximo 1 por mensaje).\n- Preferir preguntas de opción múltiple cuando sea posible.\n- Si un tema necesita más detalle, dividirlo en varias preguntas (una por mensaje).\n- Confirmar propósito, restricciones y criterio de éxito.\n\n### Ejecutar\n- Explorar 2-3 alternativas con trade-offs:\n  - Recomendación primero.\n  - Trade-offs claros.\n- Presentar el diseño en secciones de 200-300 palabras.\n  - Tras cada sección: preguntar \"¿esto va bien hasta aquí?\".\n- Cobertura mínima del diseño:\n  - Arquitectura\n  - Componentes\n  - Flujo de datos\n  - Manejo de errores\n  - Testing/validación\n\n### Después del diseño\n- Escribir el diseño validado en `docs/plans/YYYY-MM-DD-<topic>-design.md`.\n- Si el nombre `<topic>` no está claro, pedirlo explícitamente al usuario.\n- (Opcional) Si el repo usa git y el usuario lo desea, hacer commit del documento de diseño.\n\n## Principios\n- **Una pregunta por mensaje**.\n- **Múltiple choice** cuando sea posible.\n- **YAGNI**: eliminar funcionalidades innecesarias del diseño.\n- **Validación incremental**: no avanzar sin validar cada sección.\n- **Flexibilidad**: si algo no cuadra, volver atrás y aclarar.\n\n## Restricciones\n- No tocar código hasta que el diseño esté validado explícitamente.\n- No inventar requisitos: si falta información, preguntar.\n- Mantener el diseño YAGNI (mínimo viable).\n\n## Recursos\n- Plantilla de diseño: `resources/design_template.md`\n- Checklist: `resources/checklist.md`\n- Test plan: `test_plan.md`\n\n## Ejemplos\n- Ver `examples/example_conversation.md`\n"},"lastSynced":"2026-03-08T02:10:49.113Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing collaborative design validation through targeted dialogue","zh":"适合需要通过有针对性的对话进行协作设计验证的开发代理","ja":"開発エージェントがターゲットを絞った対話を通じて共同設計の検証を行う必要がある場合に最適","ko":"타겟 대화를 통해 협력 설계 검증이 필요한 개발 에이전트에 적합","es":"Perfecto para Agentes de Desarrollo que necesitan una validación de diseño colaborativa a través de un diálogo dirigido","fr":"Parfait pour les agents de développement ayant besoin d''une validation de conception collaborative via un dialogue ciblé","de":"Perfekt für Entwicklungssagenten, die eine kollaborative Designvalidierung durch gezieltes Dialog benötigen","pt":"Perfeito para Agentes de Desenvolvimento que precisam de validação de design colaborativa por meio de diálogo direcionado","ru":"Идеально для агентов разработки, которым требуется совместная проверка дизайна посредством целевого диалога","ar":"مثالي لعمليات التطوير التي تحتاج إلى تحقق التصميم التعاوني من خلال الحوار المستهدف"},"recommendation":{"en":"Empowers agents to streamline design processes using contextual project revision and iterative questioning, facilitating the conversion of ideas into validated designs through collaborative dialogue, leveraging protocols such as targeted questioning and project context analysis","zh":"赋予代理人使用上下文项目修订和迭代问题的设计流程，促进通过协作对话将想法转化为经过验证的设计，利用诸如目标问题和项目上下文分析等协议","ja":"エージェントがプロジェクトの修正とイテレーションの質問を使用して設計プロセスを合理化できるようにし、ターゲットを絞った質問やプロジェクトコンテキスト分析などのプロトコルを利用して、アイデアを共同の対話を通じて検証された設計に変換できるようにする","ko":"에이전트가 프로젝트 수정과 반복적인 질문을 사용하여 디자인 프로세스를 최적화 할 수 있도록 하여 아이디어를 협력 대화를 통해 검증된 디자인으로 변환 할 수 있도록하며, 목표 질문 및 프로젝트 컨텍스트 분석과 같은 프로토콜을 활용","es":"Habilita a los agentes a optimizar los procesos de diseño utilizando la revisión contextual del proyecto y la pregunta iterativa, facilitando la conversión de ideas en diseños validados a través del diálogo colaborativo, aprovechando protocolos como la pregunta dirigida y el análisis de contexto del proyecto","fr":"Permet aux agents de rationaliser les processus de conception en utilisant la révision contextuelle du projet et la question itérative, facilitant la conversion des idées en conceptions validées via le dialogue collaboratif, en exploitant des protocoles tels que la question ciblée et l''analyse de contexte du projet","de":"Ermächtigt die Agenten, die Entwicklungsprozesse mithilfe der kontextuellen Projektrevision und der iterativen Fragestellung zu optimieren, wodurch die Umwandlung von Ideen in validierte Entwürfe durch kollaborativen Dialog erleichtert wird, indem Protokolle wie gezielte Fragestellung und Projektkontextanalyse genutzt werden","pt":"Habilita os agentes a agilizar os processos de design usando revisão contextual do projeto e questionamento iterativo, facilitando a conversão de ideias em designs validados por meio de diálogo colaborativo, aproveitando protocolos como questionamento direcionado e análise de contexto do projeto","ru":"Наделяет агентов возможностью оптимизировать процессы проектирования с помощью контекстной обратной связи проекта и итеративного вопросования, облегчая преобразование идей в проверенные конструкции посредством совместного диалога, используя протоколы, такие как целевое вопросование и анализ контекста проекта","ar":"تمكين الوكلاء من تسريع عمليات التصميم باستخدام المراجعة السياقية للمشروع والاستفهام التكراري، وتسهيل تحويل الأفكار إلى تصاميم محققة من خلال الحوار التعاوني، واستخدام بروتوكولات مثل الاستفهام المستهدف وتحليل سياق المشروع"},"useCases":{"en":["Automating design validation for new feature requests","Generating project specifications through collaborative dialogue","Debugging ambiguous project requirements"],"zh":["自动化新功能请求的设计验证","通过协作对话生成项目规格","调试模糊的项目需求"],"ja":["新しい機能リクエストの設計検証の自動化","共同の対話を通じてプロジェクト仕様を生成する","曖昧なプロジェクト要件のデバッグ"],"ko":["새로운 기능 요청에 대한 설계 검증 자동화","협력 대화를 통해 프로젝트 사양 생성","모호한 프로젝트 요구사항 디버깅"],"es":["Automatización de la validación de diseño para nuevas solicitudes de características","Generación de especificaciones de proyecto a través de diálogo colaborativo","Depuración de requisitos de proyecto ambiguos"],"fr":["Automatisation de la validation de conception pour les nouvelles demandes de fonctionnalités","Génération de spécifications de projet via un dialogue collaboratif","Débogage des exigences de projet ambiguës"],"de":["Automatisierung der Designvalidierung für neue Funktionsanforderungen","Erzeugung von Projektspezifikationen durch kollaborativen Dialog","Fehlerbehebung bei mehrdeutigen Projektanforderungen"],"pt":["Automating design validation for new feature requests","Gerando especificações do projeto por meio de diálogo colaborativo","Depurando requisitos de projeto ambíguos"],"ru":["Автоматизация проверки дизайна для новых запросов на функции","Генерация спецификаций проекта посредством совместного диалога","Отладка неоднозначных требований проекта"],"ar":["تأتمة التحقق من التصميم لطلبات الميزات الجديدة","генерация مواصفات المشروع من خلال الحوار التعاوني","تصحيح متطلبات المشروع الغامضة"]},"limitations":{"en":["Requires project context information","Limited to design validation and specification generation"],"zh":["需要项目上下文信息","仅限于设计验证和规格生成"],"ja":["プロジェクトコンテキスト情報が必要","設計検証と仕様生成のみに限定"],"ko":["프로젝트 컨텍스트 정보 필요","디자인 검증 및 사양 생성만 제한"],"es":["Requiere información de contexto del proyecto","Limitado a la validación de diseño y generación de especificaciones"],"fr":["Nécessite des informations de contexte du projet","Limité à la validation de conception et à la génération de spécifications"],"de":["Benötigt Projektkontextinformationen","Begrenzt auf Designvalidierung und Spezifikationsgenerierung"],"pt":["Requer informações de contexto do projeto","Limitado à validação de design e geração de especificações"],"ru":["Требует информации о контексте проекта","Ограничен проверкой конструкции и генерацией спецификаций"],"ar":["يتطلب معلومات سياق المشروع","محدود بالتحقق من التصميم وتوليد المواصفات"]},"version":4},"contentHash":"41d5e48cb40674191948ba3d6982d696afbcf0ce5b03eeda798035e408b08aab","qualityScore":20}');
