INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AlbanoArranz/Traductor-Documentacion-Tecnica/idear-diseno', 'idear-diseno', 'AlbanoArranz', 'Traductor-Documentacion-Tecnica', 'community', 'idear-diseno AlbanoArranz Traductor-Documentacion-Tecnica community idear-diseno is a skill that enables the conversion of ideas into validated designs through collaborative dialogue, benefiting developers and project managers. It streamlines the design process by revising project context and understanding ideas through targeted questioning. Idear Diseño skill通过对话式协作，帮助开发者将想法转化为有效设计和规范，提高开发效率 Idear Diseñoスキルは、開発者がアイデアを有効な設計と仕様に変換するのに役立ちます Idear Diseño 스킬은 개발자가 아이디어를 유효한 디자인과 사양으로 변환하는 것을 도와줍니다 Idear-Diseno es una habilidad que permite convertir ideas en diseños validados a través de diálogo colaborativo, revisando el contexto del proyecto y entendiendo la idea con preguntas Idear-Diseno est une compétence qui permet de convertir des idées en conceptions validées via un dialogue collaboratif, en révisant le contexte du projet et en compréhendant l''idée avec des questions Idear-Diseno ist eine Fähigkeit, die es ermöglicht, Ideen in validierte Entwürfe durch kollaborativen Dialog umzuwandeln, indem der Projektcontext überprüft und die Idee mit Fragen verstanden wird O Idear-Diseno é uma habilidade que permite converter ideias em designs validados através de diálogo colaborativo, revisando o contexto do projeto e entendendo as ideias com perguntas ИИ Агент Idear-Diseno - это навык, который позволяет преобразовать идеи в действенные дизайны посредством сотрудничества, проверки контекста и понимания идей Idear-Diseno هو مهارة تسمح بتحويل الأفكار إلى تصاميم صالحة من خلال حوار تعاوني، مع مراجعة سياق المشروع وفهم الأفكار how to use idear-diseno idear-diseno setup guide collaborative design tools idear-diseno vs traditional design methods idear-diseno install what is idear-diseno idear-diseno alternative idear-diseno for AI agents collaborative dialogue in design validated design specifications AI智能工具 Idear Diseño 协作设计 设计和规范生成 开发效率 项目背景审查 对话式协作 设计建议 开发场景 Revises project context by examining key files and conventions Understands ideas through a series of targeted questions, one per message Proposes design solutions based on collaborative dialogue Validates designs and specifications through iterative feedback Addresses ambiguity and missing requirements in project design Facilitates changes in project behavior or architecture idear-diseno is a collaborative design skill that facilitates the conversion of ideas into validated designs and specifications through a dialogue-driven approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jwnichols3/bmad-kiro-agents/edit-prd', 'community', 'jwnichols3', 'bmad-kiro-agents', 'jwnichols3/bmad-kiro-agents', 'edit-prd', 0, 0, 20, '2026-03-08T01:57:15.542Z', '2026-03-08T02:11:16.734Z', '30f67043bc55ab777e14a5df14fc0373dac97f4cfb3c81c5daac64fcdee1d9a4', '{"id":"jwnichols3/bmad-kiro-agents/edit-prd","name":"edit-prd","description":{"en":"The edit-prd skill enables AI agents to autonomously execute epic workflows for editing and updating PRD documents using the BMAD Method, benefiting Kiro CLI users.","zh":"edit-prd 是一个用于 Kiro CLI 的自动化史诗执行流水线，能够编辑和更新现有的 PRD 文档","ja":"edit-prd は Kiro CLI 用の自動化エピック実行パイプラインであり、既存の PRD ドキュメントを編集および更新できます","ko":"edit-prd는 Kiro CLI용 자율적 에픽 실행 파이프라인으로 기존 PRD 문서를 편집 및 업데이트할 수 있습니다","es":"El agente edit-prd permite la edición y actualización autónoma de PRD utilizando el framework BMAD Method para Kiro CLI","fr":"L''agent edit-prd permet l''édition et la mise à jour autonome de PRD en utilisant le framework BMAD Method pour Kiro CLI","de":"Der edit-prd-Agent ermöglicht die autonome Bearbeitung und Aktualisierung von PRD mithilfe des BMAD Method-Frameworks für Kiro CLI","pt":"O edit-prd é um agente da metodologia BMAD para Kiro CLI que automatiza a edição e atualização de PRD existentes","ru":"ИИ Агент edit-prd - это автономный агент методологии BMAD для Kiro CLI, который автоматизирует редактирование и обновление существующих PRD","ar":"وكيل edit-prd هو عميل методولوجيا BMAD ل Kiro CLI الذي ي автомة تحرير و تحديث PRD الحالي"},"seo":{"title":{"en":"edit-prd: Autonomous Epic Execution Pipeline Setup Guide ...","zh":"edit-prd Setup Guide: 自动化史诗执行流水线","ja":"edit-prd のベストプラクティス: AIエージェントによる Kiro CLI パイプライン","ko":"edit-prd 설정 가이드: 자율적 에픽 실행 파이프라인","es":"Guía de Edición de PRD con Agentes de BMAD Method","fr":"Configurer l''édition de PRD avec les Agents BMAD Method","de":"Einrichten der PRD-Bearbeitung mit BMAD Method Agents","pt":"Guia de Configuração do edit-prd: Automação de Pipeline d...","ru":"Настройка ИИ Агентов edit-prd: Автономная Система Выполне...","ar":"دليل إعداد edit-prd: трубة تنفيذ إيبك ذاتية التشغيل"},"description":{"en":"Discover how edit-prd streamlines PRD editing with the BMAD Method. Learn to implement autonomous workflows and optimize your development pipeline today!","zh":"了解 edit-prd 技术，自动化 Kiro CLI 流水线，提升开发效率","ja":"edit-prd を使用して Kiro CLI パイプラインを自動化し、開発効率を向上させます","ko":"edit-prd 기능을 사용하여 Kiro CLI 파이프라인을 자동화하고 개발 효율성을 높여보세요","es":"Aprende a editar y actualizar PRD de manera autónoma con los agentes de BMAD Method para Kiro CLI","fr":"Découvrez comment éditer et mettre à jour des PRD de manière autonome avec les agents BMAD Method pour Kiro CLI","de":"Erfahren Sie, wie Sie PRD autonom bearbeiten und aktualisieren können, mit den BMAD Method-Agents für Kiro CLI","pt":"Aprenda a configurar o edit-prd para automação de pipeline de execução epica com a metodologia BMAD e melhores práticas","ru":"Узнайте, как настроить ИИ Агенты edit-prd для автономной системы выполнения эпик с помощью методологии BMAD и лучших практик","ar":"تعرف على كيفية إعداد edit-prd لتشغيل трубة التنفيذ الإيبك الذاتي مع منهجية BMAD وأفضل الممارسات"},"definition":{"en":"edit-prd is a skill for AI agents that facilitates the editing and updating of existing PRD documents using a standardized methodology and best practices.","zh":"edit-prd 是一个自动化工具，用于编辑和更新 PRD 文档","ja":"edit-prd は PRD ドキュメントを編集および更新するための自動化ツールです","ko":"edit-prd는 PRD 문서를 편집 및 업데이트하는 자동화 도구입니다","es":"El agente edit-prd es una herramienta de AI que edita y actualiza PRD de manera autónoma","fr":"L''agent edit-prd est un outil d''IA qui édite et met à jour des PRD de manière autonome","de":"Der edit-prd-Agent ist ein AI-Tool, das PRD autonom bearbeitet und aktualisiert","pt":"O que é edit-prd? É um agente que edita e atualiza PRD existentes com metodologia BMAD e melhores práticas","ru":"Что такое ИИ Агент edit-prd? Это агент, который редактирует и обновляет существующие PRD с помощью методологии BMAD и лучших практик","ar":"ما هو edit-prd؟ هو عميل يحرر و يحدث PRD الحالي باستخدام منهجية BMAD وأفضل الممارسات"},"features":{"en":["Loads current PRD documents from `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md`","Applies requested changes while maintaining consistency and tracking updates","Follows editing methodology and best practices for PRD documents","Saves updated PRD documents with change tracking","Utilizes the BMAD Method for autonomous epic execution pipeline"],"zh":["自动加载当前 PRD 文档","编辑方法论和最佳实践","应用请求的更改同时保持一致性","保存更新的 PRD 文档同时记录更改","支持 Kiro CLI 流水线"],"ja":["現在の PRD ドキュメントを自動で読み込み","編集方法論とベストプラクティス","要求された変更を適用しながら一貫性を維持","更新された PRD ドキュメントを保存しながら変更を追跡","Kiro CLI パイプラインをサポート"],"ko":["현재 PRD 문서를 자동으로 로드","편집 방법론 및 최고의 관행","요청된 변경 사항을 적용하면서 일관성을 유지","업데이트된 PRD 문서를 저장하면서 변경 사항을 추적","Kiro CLI 파이프라인 지원"],"es":["Edición de PRD utilizando el framework BMAD Method","Carga de documentos PRD actuales","Aplicación de cambios solicitados mientras se mantiene la consistencia","Guardado de PRD actualizados con seguimiento de cambios","Integración con Kiro CLI"],"fr":["Édition de PRD en utilisant le framework BMAD Method","Chargement de documents PRD actuels","Application des changements demandés tout en maintenant la cohérence","Enregistrement de PRD mis à jour avec suivi des changements","Intégration avec Kiro CLI"],"de":["Bearbeitung von PRD mithilfe des BMAD Method-Frameworks","Laden von aktuellen PRD-Dokumenten","Anwendung von angeforderten Änderungen während der Aufrechterhaltung der Konsistenz","Speichern von aktualisierten PRD mit Änderungsverfolgung","Integration mit Kiro CLI"],"pt":["Leitura do arquivo workflow-edit-prd.md","Carregamento do documento PRD atual","Aplicação da metodologia BMAD e melhores práticas","Realização de alterações solicitadas com manutenção da consistência","Salvamento do PRD atualizado com rastreamento de alterações"],"ru":["Чтение файла workflow-edit-prd.md","Загрузка текущего документа PRD","Применение методологии BMAD и лучших практик","Выполнение запрошенных изменений с поддержанием согласованности","Сохранение обновленного PRD с отслеживанием изменений"],"ar":["قراءة ملف workflow-edit-prd.md","تحميل المستند PRD الحالي","تطبيق منهجية BMAD وأفضل الممارسات","تنفيذ التغييرات المطلوبة مع الحفاظ على الاتساق","حفظ PRD المحدث مع تتبع التغييرات"]},"keywords":{"en":["how to use edit-prd","edit-prd setup guide","BMAD Method tutorial","Kiro CLI workflow automation","autonomous epic execution pipeline","PRD document editing best practices","edit-prd vs manual PRD editing","edit-prd install for AI agents"],"zh":["edit-prd","Kiro CLI","自动化流水线","PRD 文档编辑","AI工具","开发效率","自动化史诗执行"],"ja":["edit-prd","Kiro CLI","自動化パイプライン","PRD ドキュメント編集","AIエージェント","開発効率","自動化エピック実行"],"ko":["edit-prd","Kiro CLI","자동화 파이프라인","PRD 문서 편집","AI 도구","개발 효율성","자율적 에픽 실행"],"es":["agentes de AI","herramientas de AI","BMAD Method","Kiro CLI","edición de PRD","actualización de PRD","autonomía en la edición de PRD","frameworks de desarrollo de software"],"fr":["agents d''IA","outils d''IA","BMAD Method","Kiro CLI","édition de PRD","mise à jour de PRD","autonomie dans l''édition de PRD","frameworks de développement de logiciels"],"de":["AI-Agents","AI-Tools","BMAD Method","Kiro CLI","Bearbeitung von PRD","Aktualisierung von PRD","Autonomie bei der Bearbeitung von PRD","Software-Entwicklungsframeworks"],"pt":["edit-prd","BMAD Method","Kiro CLI","automação de pipeline","execução epica","PRD","melhores práticas","metodologia BMAD"],"ru":["ИИ Агент edit-prd","Методология BMAD","Kiro CLI","автономная система выполнения","эпик","PRD","лучшие практики","методология BMAD"],"ar":["عميل edit-prd","منهجية BMAD","Kiro CLI","نظام تنفيذ ذاتي","إيبك","PRD","أفضل الممارسات","منهجية BMAD"]}},"owner":"jwnichols3","repo":"bmad-kiro-agents","repoPath":"jwnichols3/bmad-kiro-agents","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.542Z","topics":[],"category":"community","skillMd":{"name":"edit-prd","description":">-","bodyPreview":"# Edit PRD Workflow\n\nEdit and update existing PRD:\n\n1. Read `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md`\n2. Load current PRD document\n3. Follow editing methodology and best practices\n4. Apply requested changes while maintaining consistency\n5. Save updated PRD with change tracking","body":"# Edit PRD Workflow\n\nEdit and update existing PRD:\n\n1. Read `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md`\n2. Load current PRD document\n3. Follow editing methodology and best practices\n4. Apply requested changes while maintaining consistency\n5. Save updated PRD with change tracking"},"lastSynced":"2026-03-08T02:11:16.734Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing autonomous PRD editing capabilities using the BMAD Method","zh":"非常适合需要使用BMAD方法进行自主PRD编辑功能的技术写作代理","ja":"BMADメソッドを使用した自主的なPRD編集機能を必要とするテクニカルライティングエージェントに最適","ko":"BMAD 방법을 사용하여 자율적인 PRD 편집 기능이 필요한 기술 작성 에이전트에 적합","es":"Perfecto para Agentes de Escritura Técnica que necesitan capacidades de edición de PRD autónomas utilizando el método BMAD","fr":"Parfait pour les agents de rédaction technique ayant besoin de capacités d''édition de PRD autonomes utilisant la méthode BMAD","de":"Perfekt für technische Schreibagenten, die autarke PRD-Bearbeitungsfähigkeiten mit der BMAD-Methode benötigen","pt":"Perfeito para Agentes de Redação Técnica que necessitam de capacidades de edição de PRD autônoma usando o Método BMAD","ru":"Идеально для технических агентов писателей, которым необходимы автономные возможности редактирования PRD с использованием метода BMAD","ar":"مثالي لعمليات الكتابة الفنية التي تحتاج إلى تحرير مستندات PRD ذاتية التشغيل باستخدام طريقة BMAD"},"recommendation":{"en":"Empowers agents to execute epic workflows for editing and updating PRD documents, applying best practices and maintaining consistency while tracking changes, utilizing Markdown files and following the BMAD methodology","zh":"赋予代理执行编辑和更新PRD文档的史诗工作流程的能力，应用最佳实践和保持一致性，同时跟踪更改，利用Markdown文件并遵循BMAD方法论","ja":"エージェントに、編集および更新PRDドキュメントのためのエピックなワークフローを実行する能力を与え、ベストプラクティスを適用し、一貫性を維持しながら変更を追跡し、Markdownファイルを使用し、BMADの方法論に従う","ko":"에이전트가 PRD 문서의 편집 및 업데이트를 위한 에픽한 워크플로우를 실행할 수 있는 능력을 부여하여, 최고의 관행을 적용하고 일관성을 유지하면서 변경 사항을 추적하고, Markdown 파일을 사용하고, BMAD 방법론을 따름","es":"Habilita a los agentes a ejecutar flujos de trabajo épico para la edición y actualización de documentos PRD, aplicando las mejores prácticas y manteniendo la consistencia mientras se realizan seguimientos de cambios, utilizando archivos Markdown y siguiendo la metodología BMAD","fr":"Permet aux agents d''exécuter des flux de travail épique pour l''édition et la mise à jour des documents PRD, en appliquant les meilleures pratiques et en maintenant la cohérence tout en suivant les modifications, en utilisant des fichiers Markdown et en suivant la méthodologie BMAD","de":"Ermächtigt Agenten, epische Workflows für die Bearbeitung und Aktualisierung von PRD-Dokumenten auszuführen, wobei beste Praktiken angewendet und Konsistenz gewährleistet wird, während Änderungen nachverfolgt werden, unter Verwendung von Markdown-Dateien und unter Befolgung der BMAD-Methodik","pt":"Habilita os agentes a executar fluxos de trabalho épico para edição e atualização de documentos PRD, aplicando as melhores práticas e mantendo a consistência enquanto rastreia alterações, utilizando arquivos Markdown e seguindo a metodologia BMAD","ru":"Наделяет агентов возможностью выполнять эпические рабочие процессы для редактирования и обновления документов PRD, применяя лучшие практики и поддерживая согласованность при отслеживании изменений, используя файлы Markdown и следуя методологии BMAD","ar":"تمكن الوكلاء من تنفيذ سير عمل ملحمة لتحرير وتنقيح مستندات PRD، وتطبيق أفضل الممارسات والحفاظ على الاتساق أثناء تتبع التغييرات، واستخدام ملفات Markdown واتباع منهجية BMAD"},"useCases":{"en":["Automating PRD updates with change tracking","Generating consistent PRD documents using the BMAD Method","Editing existing PRD documents while maintaining consistency"],"zh":["使用更改跟踪自动更新PRD","使用BMAD方法生成一致的PRD文档","编辑现有的PRD文档同时保持一致性"],"ja":["変更追跡を使用してPRDを自動更新","BMAD方法を使用して一貫性のあるPRDドキュメントを生成","一貫性を維持しながら既存のPRDドキュメントを編集"],"ko":["변경 추적을 사용하여 PRD 자동 업데이트","BMAD 방법을 사용하여 일관된 PRD 문서 생성","일관성을 유지하면서 기존 PRD 문서 편집"],"es":["Automatización de actualizaciones de PRD con seguimiento de cambios","Generación de documentos PRD coherentes utilizando el método BMAD","Edición de documentos PRD existentes manteniendo la consistencia"],"fr":["Automatisation des mises à jour de PRD avec suivi des modifications","Génération de documents PRD cohérents en utilisant la méthode BMAD","Édition de documents PRD existants en maintenant la cohérence"],"de":["Automatisierung von PRD-Aktualisierungen mit Änderungsnachverfolgung","Erzeugung konsistenter PRD-Dokumente unter Verwendung der BMAD-Methode","Bearbeitung bestehender PRD-Dokumente unter Beibehaltung der Konsistenz"],"pt":["Automatizar atualizações de PRD com rastreamento de alterações","Gerar documentos PRD consistentes usando o Método BMAD","Editar documentos PRD existentes mantendo a consistência"],"ru":["Автоматизировать обновления PRD с отслеживанием изменений","Генерировать согласованные документы PRD с использованием метода BMAD","Редактировать существующие документы PRD, сохраняя согласованность"],"ar":["توفير تحديثات PRD آليًا مع تتبع التغييرات","جعل مستندات PRD متسقة باستخدام طريقة BMAD","تحرير مستندات PRD الحالية مع الحفاظ على الاتساق"]},"limitations":{"en":["Requires access to _bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md","Limited to editing existing PRD documents"],"zh":["需要访问_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md","仅限编辑现有的PRD文档"],"ja":["_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.mdへのアクセスが必要","既存のPRDドキュメントの編集のみ"],"ko":["_bmad/bmm/workflows/2-plan-workflows/create-