INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jwnichols3/bmad-kiro-agents/edit-prd', 'edit-prd', 'jwnichols3', 'bmad-kiro-agents', 'community', 'edit-prd jwnichols3 bmad-kiro-agents community The edit-prd skill enables AI agents to autonomously execute epic workflows for editing and updating PRD documents using the BMAD Method, benefiting Kiro CLI users. edit-prd 是一个用于 Kiro CLI 的自动化史诗执行流水线，能够编辑和更新现有的 PRD 文档 edit-prd は Kiro CLI 用の自動化エピック実行パイプラインであり、既存の PRD ドキュメントを編集および更新できます edit-prd는 Kiro CLI용 자율적 에픽 실행 파이프라인으로 기존 PRD 문서를 편집 및 업데이트할 수 있습니다 El agente edit-prd permite la edición y actualización autónoma de PRD utilizando el framework BMAD Method para Kiro CLI L''agent edit-prd permet l''édition et la mise à jour autonome de PRD en utilisant le framework BMAD Method pour Kiro CLI Der edit-prd-Agent ermöglicht die autonome Bearbeitung und Aktualisierung von PRD mithilfe des BMAD Method-Frameworks für Kiro CLI O edit-prd é um agente da metodologia BMAD para Kiro CLI que automatiza a edição e atualização de PRD existentes ИИ Агент edit-prd - это автономный агент методологии BMAD для Kiro CLI, который автоматизирует редактирование и обновление существующих PRD وكيل edit-prd هو عميل методولوجيا BMAD ل Kiro CLI الذي ي автомة تحرير و تحديث PRD الحالي how to use edit-prd edit-prd setup guide BMAD Method tutorial Kiro CLI workflow automation autonomous epic execution pipeline PRD document editing best practices edit-prd vs manual PRD editing edit-prd install for AI agents edit-prd Kiro CLI 自动化流水线 PRD 文档编辑 AI工具 开发效率 自动化史诗执行 Loads current PRD documents from `_bmad/bmm/workflows/2-plan-workflows/create-prd/workflow-edit-prd.md` Applies requested changes while maintaining consistency and tracking updates Follows editing methodology and best practices for PRD documents Saves updated PRD documents with change tracking Utilizes the BMAD Method for autonomous epic execution pipeline edit-prd is a skill for AI agents that facilitates the editing and updating of existing PRD documents using a standardized methodology and best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TSGCFO/LogiBill/project-context', 'community', 'TSGCFO', 'LogiBill', 'TSGCFO/LogiBill', 'project-context', 0, 0, 20, '2026-03-08T01:57:15.545Z', '2026-03-08T02:11:20.517Z', '597e039ce9b59ec8619b571f75d8d35c3a7074a228233174fa6416cd6de86813', '{"id":"TSGCFO/LogiBill/project-context","name":"project-context","description":{"en":"The project-context skill helps developers summarize project goals, core constraints, and relevant dependencies, making it easier to manage and reuse project information.","zh":"项目上下文是指项目的目标、核心约束和相关依存关系。它帮助开发者理解项目的架构决策和共享约定","ja":"プロジェクトコンテキストは、プロジェクトの目標、核心的な制約、関連する依存関係を指します。開発者がプロジェクトのアーキテクチャ決定と共有約定を理解するのに役立ちます","ko":"프로젝트 컨텍스트는 프로젝트의 목표, 핵심 제약 조건, 관련 의존성을指します. 개발자가 프로젝트의 아키텍처 결정과 공유 규칙을 이해하는 데 도움이 됩니다","es":"project-context resume los objetivos del proyecto, las restricciones y las dependencias. Ideal para desarrolladores que necesitan validar decisiones de arquitectura.","fr":"project-context résume les objectifs du projet, les contraintes et les dépendances. Idéal pour les développeurs qui doivent valider les décisions d''architecture.","de":"project-context fasst die Projektziele, Einschränkungen und Abhängigkeiten zusammen. Ideal für Entwickler, die Architekturentscheidungen validieren müssen.","pt":"O project-context resume os objetivos do projeto, restrições principais e dependências relevantes. Fornece uma visão geral concisa para futuras tarefas.","ru":"Project-context суммирует цели проекта, основные ограничения и актуальные зависимости. Предоставляет краткий обзор для будущих задач.","ar":"يوجز project-context أهداف المشروع والقيود الأساسية والاعتماديات ذات الصلة. يوفر نظرة عامة مضغوطة لل任务ات المستقبلية."},"seo":{"title":{"en":"project-context: Project Summary Setup Guide | AI Agent S...","zh":"项目上下文设置指南 - 项目目标和约束总结","ja":"プロジェクトコンテキストのベストプラクティス - アーキテクチャ決定と依存関係","ko":"프로젝트 컨텍스트 설정 가이드 - 프로젝트 목표와 핵심 제약 조건","es":"Guía de configuración de project-context para desarrollad...","fr":"Meilleures pratiques pour project-context dans le dévelop...","de":"Einrichtungsleitfaden für project-context in der Software...","pt":"Guia de Configuração do project-context: Melhores Prática...","ru":"Настройка ИИ Агентов project-context: Руководство для Раз...","ar":"دليل إعداد project-context: أفضل الممارسات لمنصة الإي الأجنت"},"description":{"en":"Discover how project-context helps you summarize project goals, constraints, and dependencies. Learn how to reuse summaries in future tasks and improve your ...","zh":"了解项目上下文的重要性，并学习如何总结项目目标、核心约束和相关依存关系","ja":"プロジェクトコンテキストの重要性を理解し、プロジェクトの目標、核心的な制約、関連する依存関係を要約する方法を学びます","ko":"프로젝트 컨텍스트의 중요성을 이해하고 프로젝트 목표, 핵심 제약 조건, 관련 의존성을 요약하는 방법을 배우세요","es":"Aprende a resumir objetivos de proyecto, restricciones y dependencias con project-context. Herramientas de inteligencia artificial para desarrolladores.","fr":"Découvrez comment résumer les objectifs de projet, les contraintes et les dépendances avec project-context. Outils d''agents IA pour les développeurs.","de":"Erfahren Sie, wie Sie Projektziele, Einschränkungen und Abhängigkeiten mit project-context zusammenfassen. KI-Tools für Entwickler.","pt":"Aprenda a configurar o project-context para melhorar a eficiência do seu projeto. Descubra as melhores práticas e dicas para desenvolvedores.","ru":"Узнайте, как настроить project-context для повышения эффективности вашего проекта. Изучите лучшие практики и советы для разработчиков.","ar":"تعلم كيفية إعداد project-context لتحسين كفاءة مشروعك. اكتشف أفضل الممارسات والنصائح للمطورين."},"definition":{"en":"project-context is a skill that summarizes project goals, core constraints, and relevant dependencies, enabling concise and reusable project summaries","zh":"项目上下文是指项目的目标、核心约束和相关依存关系的总结","ja":"プロジェクトコンテキストは、プロジェクトの目標、核心的な制約、関連する依存関係の要約です","ko":"프로젝트 컨텍스트는 프로젝트의 목표, 핵심 제약 조건, 관련 의존성의 요약입니다","es":"project-context es una herramienta de inteligencia artificial que resume los objetivos y restricciones de un proyecto.","fr":"project-context est un outil d''agent IA qui résume les objectifs et les contraintes d''un projet.","de":"project-context ist ein KI-Tool, das die Projektziele und Einschränkungen zusammenfasst.","pt":"Project-context é uma habilidade que resume os objetivos e restrições de um projeto.","ru":"Project-context - это навык, который суммирует цели и ограничения проекта.","ar":"project-context هو مهارة توجز أهداف ومحددات المشروع."},"features":{"en":["Summarizes project goals and core constraints","Identifies relevant dependencies and architecture decisions","Calls out shared conventions and validation steps","Generates concise and reusable project summaries","Enables easy reuse of summaries in future tasks","Supports project management and workflow optimization"],"zh":["项目目标和核心约束的总结","相关依存关系和架构决策的识别","共享约定和验证步骤的定义","项目上下文的重用和共享","支持多种项目管理工具和平台"],"ja":["プロジェクトの目標と核心的な制約の要約","関連する依存関係とアーキテクチャ決定の識別","共有約定と検証ステップの定義","プロジェクトコンテキストの再利用と共有","複数のプロジェクト管理ツールとプラットフォームのサポート"],"ko":["프로젝트 목표와 핵심 제약 조건의 요약","관련 의존성과 아키텍처 결정의 식별","공유 규칙과 검증 단계의 정의","프로젝트 컨텍스트의 재사용과 공유","다양한 프로젝트 관리 도구와 플랫폼의 지원"],"es":["Resumen de objetivos de proyecto","Identificación de restricciones y dependencias","Validación de decisiones de arquitectura","Convenciones compartidas","Pasos de validación"],"fr":["Résumé des objectifs de projet","Identification des contraintes et des dépendances","Validation des décisions d''architecture","Conventions partagées","Étapes de validation"],"de":["Zusammenfassung der Projektziele","Identifizierung von Einschränkungen und Abhängigkeiten","Validierung von Architekturentscheidungen","Gemeinsame Konventionen","Validierungsschritte"],"pt":["Resumo conciso dos objetivos do projeto","Identificação das principais restrições e dependências","Arquitetura de decisões e convenções compartilhadas","Validação de etapas e reutilização em futuras tarefas"],"ru":["Краткий обзор целей проекта","Определение основных ограничений и зависимостей","Архитектурные решения и общие соглашения","Валидация шагов и повторное использование в будущих задачах"],"ar":["نظرة عامة مضغوطة لأهداف المشروع","تحديد القيود والاعتماديات الأساسية","قرارات هندسية وتوافق مشترك","تحقق خطوات وإعادة استخدام في مهام مستقبلية"]},"keywords":{"en":["how to use project-context","what is project-context","project-context alternative","project-context vs project management tools","project-context install","project-context setup guide","project-context for AI agents","project-context for developers","project summary template","project management workflow optimization"],"zh":["项目上下文","AIエージェント","项目管理","架构决策","共享约定","验证步骤","项目目标","核心约束","相关依存关系"],"ja":["プロジェクトコンテキスト","AIエージェント","プロジェクト管理","アーキテクチャ決定","共有約定","検証ステップ","プロジェクトの目標","核心的な制約","関連する依存関係"],"ko":["프로젝트 컨텍스트","AI 툴","프로젝트 관리","아키텍처 결정","공유 규칙","검증 단계","프로젝트 목표","핵심 제약 조건","관련 의존성"],"es":["project-context","herramientas de inteligencia artificial","desarrollo de software","objetivos de proyecto","restricciones y dependencias","validación de decisiones de arquitectura","convenciones compartidas"],"fr":["project-context","outils d''agents IA","développement de logiciels","objectifs de projet","contraintes et dépendances","validation des décisions d''architecture","conventions partagées"],"de":["project-context","KI-Tools","Softwareentwicklung","Projektziele","Einschränkungen und Abhängigkeiten","Validierung von Architekturentscheidungen","gemeinsame Konventionen"],"pt":["project-context","configuração de projeto","melhores práticas para desenvolvedores","resumo de objetivos","restrições e dependências","arquitetura de decisões","validação de etapas"],"ru":["project-context","настройка проекта","лучшие практики для разработчиков","суммирование целей","ограничения и зависимости","архитектурные решения","валидация шагов"],"ar":["project-context","إعداد مشروع","أفضل الممارسات للمطورين","نظرة عامة لأهداف","محددات واعتماديات","قرارات هندسية","تحقق خطوات"]}},"owner":"TSGCFO","repo":"LogiBill","repoPath":"TSGCFO/LogiBill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.545Z","topics":[],"category":"community","skillMd":{"name":"project-context","description":"Summarize the project context and key constraints","bodyPreview":"Summarize the project goals, core constraints, and relevant dependencies.\nCall out any architecture decisions, shared conventions, and validation steps.\nKeep the summary concise and ready to reuse in future tasks.","body":"Summarize the project goals, core constraints, and relevant dependencies.\nCall out any architecture decisions, shared conventions, and validation steps.\nKeep the summary concise and ready to reuse in future tasks.\n"},"lastSynced":"2026-03-08T02:11:20.517Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring efficient project information management and concise goal summarization.","zh":"适合需要高效项目信息管理和简洁目标摘要的开发者代理。","ja":"開発者エージェントが効率的なプロジェクト情報管理と簡潔な目標の要約を必要とする場合に最適です。","ko":"개발자 에이전트가 효율적인 프로젝트 정보 관리와 간결한 목표 요약을 필요로 할 때 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren una gestión de información de proyecto eficiente y una resumen de objetivos conciso.","fr":"Idéal pour les Agents de Développeur nécessitant une gestion d''informations de projet efficace et une synthèse d''objectifs concise.","de":"Ideal für Developer-Agents, die eine effiziente Projektinformationenverwaltung und eine präzise Zielzusammenfassung erfordern.","pt":"Ideal para Agentes de Desenvolvedores que exigem gerenciamento eficiente de informações de projeto e resumo conciso de metas.","ru":"Идеально подходит для агентов-разработчиков, требующих эффективного управления информацией о проекте и краткого изложения целей.","ar":"مثالي لعميل المطور الذي يتطلب إدارة فعالة لمعلومات المشروع وتلخيص غاية موجز."},"recommendation":{"en":"Empowers agents to summarize project goals, core constraints, and relevant dependencies, utilizing validation steps and architecture decisions to streamline project management, and potentially integrating with protocols like Agile or Scrum, and file formats such as JSON or YAML.","zh":"赋予代理人总结项目目标、核心约束和相关依赖的能力，利用验证步骤和架构决策来简化项目管理，并可能与Agile或Scrum等协议以及JSON或YAML等文件格式集成。","ja":"エージェントにプロジェクトの目標、コア制約、関連する依存関係を要約する能力を与え、検証ステップとアーキテクチャの決定を使用してプロジェクト管理を合理化し、AgileまたはScrumなどのプロトコルおよびJSONまたはYAMLなどのファイル形式と統合することが可能です。","ko":"에이전트가 프로젝트 목표, 핵심 제약 및 관련 의존성을 요약할 수 있는 기능을 제공하여, 검증 단계 및 아키텍처 결정 등을 사용하여 프로젝트 관리를 간소화하며, Agile 또는 Scrum과 같은 프로토콜 및 JSON 또는 YAML과 같은 파일 형식과 통합할 수 있습니다.","es":"Habilita a los agentes a resumir los objetivos del proyecto, las restricciones principales y las dependencias relevantes, utilizando pasos de validación y decisiones de arquitectura para optimizar la gestión de proyectos, y potencialmente integrarse con protocolos como Agile o Scrum, y formatos de archivo como JSON o YAML.","fr":"Permet aux agents de résumer les objectifs du projet, les contraintes principales et les dépendances pertinentes, en utilisant des étapes de validation et des décisions d''architecture pour rationaliser la gestion de projet, et potentiellement intégrer des protocoles tels que Agile ou Scrum, et des formats de fichiers tels que JSON ou YAML.","de":"Ermächtigt die Agenten, die Projektziele, die Kernbeschränkungen und die relevanten Abhängigkeiten zusammenzufassen, indem Validierungsschritte und Architekturentscheidungen zur Optimierung des Projektmanagements verwendet werden, und potenziell in Protokolle wie Agile oder Scrum und Dateiformate wie JSON oder YAML integriert werden.","pt":"Habilita os agentes a resumir metas do projeto, restrições centrais e dependências relevantes, utilizando etapas de validação e decisões de arquitetura para otimizar a gestão de projetos, e potencialmente integrar-se com protocolos como Agile ou Scrum, e formatos de arquivo como JSON ou YAML.","ru":"Позволяет агентам кратко изложить цели проекта, основные ограничения и актуальные зависимости, используя шаги проверки и архитектурные решения для оптимизации управления проектами, и потенциально интегрируясь с протоколами типа Agile или Scrum, и форматами файлов, такими как JSON или YAML.","ar":"تمكّن الوكيل من تلخيص أهداف المشروع والقيود الأساسية والاعتماديات ذات الصلة، باستخدام خطوات التحقق و قرارات الهندسة المعمارية لتحسين إدارة المشروع، وربما التكامل مع بروتوكولات مثل Agile أو Scrum، وشكلات الملفات مثل JSON أو YAML."},"useCases":{"en":["Summarizing project objectives for team onboarding","Identifying core constraints for project planning","Validating dependencies for efficient project reuse"],"zh":["为团队入职总结项目目标","为项目规划确定核心约束","为高效项目重用验证依赖"],"ja":["チームのオンボーディングのためにプロジェクトの目的を要約する","プロジェクト計画のためにコア制約を特定する","効率的なプロジェクトの再利用のために依存関係を検証する"],"ko":["팀 온보딩을 위한 프로젝트 목표 요약","프로젝트 계획을 위한 핵심 제약 확인","효율적인 프로젝트 재사용을 위한 의존성 검증"],"es":["Resumir los objetivos del proyecto para la incorporación del equipo","Identificar las restricciones principales para la planificación del proyecto","Validar las dependencias para una reutilización de proyecto eficiente"],"fr":["Résumer les objectifs du projet pour l''intégration de l''équipe","Identifier les contraintes principales pour la planification du projet","Valider les dépendances pour une réutilisation de projet efficace"],"de":["Zusammenfassung der Projektziele für das Team-Onboarding","Identifizierung der Kernbeschränkungen für die Projektplanung","Validierung der Abhängigkeiten für eine effiziente Projektwiederverwendung"],"pt":["Resumir objetivos do projeto para integração da equipe","Identificar restrições centrais para planejamento do projeto","Validar dependências para reutilização eficiente do projeto"],"ru":["Кратко изложить цели проекта для ввода команды в курс дела","Определить основные ограничения для планирования проекта","Проверить зависимости для эффективного повторного использования проекта"],"ar":["تلخيص أهداف المشروع لتوجيه الفريق","تحديد القيود الأساسية لتخطيط المشروع","التحقق من الاعتماديات لإعادة استخدام المشروع بشكل فعال"]},"limitations":{"en":["Requires comprehensive project information","Limited to project-level analysis"],"zh":["需要全面的项目信息","仅限于项目级分析"],"ja":["包括的なプロジェクト情報が必要","プロジェクトレベルの分析のみ"],"ko":["포괄적인 프로젝트 정보가 필요","프로젝트 수준의 분석만 가능"],"es":["Requiere información de proyecto comprehensiva","Limitado al análisis a nivel de proyecto"],"fr":["Nécessite des informations de projet complètes","Limité à l''analyse au niveau du projet"],"de":["Erfordert umfassende Projektinformationen","Begrenzt auf die Analyse auf Projektebene"],"pt":["Exige informações abrangentes do projeto","Limitado à análise em nível de projeto"],"ru":["Требует всесторонней информации о проекте","Ограничен анализом на уровне проекта"],"ar":["يتطلب معلومات شاملة عن المشروع","محدود بالتحليل على مستوى المشروع"]},"version":4},"contentHash":"597e039ce9b59ec8619b571f75d8d35c3a7074a228233174fa6416cd6de86813","qualityScore":20}');
