INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TSGCFO/LogiBill/project-context', 'project-context', 'TSGCFO', 'LogiBill', 'community', 'project-context TSGCFO LogiBill community The project-context skill helps developers summarize project goals, core constraints, and relevant dependencies, making it easier to manage and reuse project information. 项目上下文是指项目的目标、核心约束和相关依存关系。它帮助开发者理解项目的架构决策和共享约定 プロジェクトコンテキストは、プロジェクトの目標、核心的な制約、関連する依存関係を指します。開発者がプロジェクトのアーキテクチャ決定と共有約定を理解するのに役立ちます 프로젝트 컨텍스트는 프로젝트의 목표, 핵심 제약 조건, 관련 의존성을指します. 개발자가 프로젝트의 아키텍처 결정과 공유 규칙을 이해하는 데 도움이 됩니다 project-context resume los objetivos del proyecto, las restricciones y las dependencias. Ideal para desarrolladores que necesitan validar decisiones de arquitectura. project-context résume les objectifs du projet, les contraintes et les dépendances. Idéal pour les développeurs qui doivent valider les décisions d''architecture. project-context fasst die Projektziele, Einschränkungen und Abhängigkeiten zusammen. Ideal für Entwickler, die Architekturentscheidungen validieren müssen. O project-context resume os objetivos do projeto, restrições principais e dependências relevantes. Fornece uma visão geral concisa para futuras tarefas. Project-context суммирует цели проекта, основные ограничения и актуальные зависимости. Предоставляет краткий обзор для будущих задач. يوجز project-context أهداف المشروع والقيود الأساسية والاعتماديات ذات الصلة. يوفر نظرة عامة مضغوطة لل任务ات المستقبلية. how to use project-context what is project-context project-context alternative project-context vs project management tools project-context install project-context setup guide project-context for AI agents project-context for developers project summary template project management workflow optimization 项目上下文 AIエージェント 项目管理 架构决策 共享约定 验证步骤 项目目标 核心约束 相关依存关系 Summarizes project goals and core constraints Identifies relevant dependencies and architecture decisions Calls out shared conventions and validation steps Generates concise and reusable project summaries Enables easy reuse of summaries in future tasks Supports project management and workflow optimization project-context is a skill that summarizes project goals, core constraints, and relevant dependencies, enabling concise and reusable project summaries');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NoCodeify/aeo/playbook', 'community', 'NoCodeify', 'aeo', 'NoCodeify/aeo', 'playbook', 0, 0, 20, '2026-03-08T01:57:15.552Z', '2026-03-08T02:11:32.228Z', '44dc51f4bbbdaf0d0a3f2bc61e487dda4f803f8be67ad5c0fa388f3f8a64bc79', '{"id":"NoCodeify/aeo/playbook","name":"playbook","description":{"en":"The playbook skill generates a prioritized, week-by-week implementation plan from completed AEO audits, benefiting developers working with AI agents like ChatGPT and Gemini.","zh":"Playbook 是一个 AEO 协议工具包，用于将完成的 AEO 审计转换为优先级的、周-by-周的实施计划，支持 MCP 服务器和 ChatGPT、Gemini、Google 审计","ja":"Playbook は、完了した AEO オーディットを優先順位の付いた、週ごとの実装計画に変換する AEO プロトコルツールキットであり、MCP サーバーと ChatGPT、Gemini、Google オーディットをサポートします","ko":"Playbook는 완료된 AEO 감사를 우선 순위가 있는 주간별 구현 계획으로 변환하는 AEO 프로토콜 툴킷이며 MCP 서버 및 ChatGPT, Gemini, Google 감사를 지원합니다","es":"El playbook es un kit de herramientas para convertir la auditoría AEO en un plan de implementación priorizado","fr":"Le playbook est un kit d''outils pour convertir l''audit AEO en un plan d''implémentation prioritaire","de":"Das playbook ist ein Toolkit, um die AEO-Audit in einen priorisierten Implementierungsplan umzuwandeln","pt":"O playbook para AEO é uma ferramenta que converte auditorias em planos de ação personalizados, incluindo suporte a ChatGPT, Gemini e Google.","ru":"Playbook для AEO — это инструмент, который преобразует аудиты в индивидуальные планы действий, включая поддержку ChatGPT, Gemini и Google.","ar":"كتاب اللعب لبروتوكول AEO هو أداة تحول عمليات التدقيق إلى خطط عمل مخصصة، بما في ذلك دعم ChatGPT و Gemini و Google."},"seo":{"title":{"en":"Playbook: AEO Protocol Setup Guide for AI Agents","zh":"Playbook 设置指南：AEO 协议工具包和 MCP 服务器优化","ja":"Playbook セットアップガイド：AEO プロトコルツールキットと MCP サーバー最適化","ko":"Playbook 설정 가이드: AEO 프로토콜 툴킷 및 MCP 서버 최적화","es":"Guía de configuración de playbook para AEO","fr":"Guide de mise en œuvre de playbook pour AEO","de":"Einrichtungsleitfaden für playbook mit AEO","pt":"Guia de Configuração do Playbook para AEO","ru":"ИИ Агенты: Руководство по Настройке Playbook для AEO","ar":"دليل إعداد كتاب اللعب لبروتوكول AEO"},"description":{"en":"Unlock the full potential of ChatGPT, Gemini, and Google audits with our playbook skill - get started now and optimize your AEO protocol implementation!","zh":"了解如何使用 Playbook 实现 AEO 审计和 MCP 服务器优化，提高 ChatGPT、Gemini 和 Google 的性能","ja":"Playbook を使用して AEO オーディットと MCP サーバー最適化を実現し、ChatGPT、Gemini、Google の性能を向上させる方法を学びます","ko":"Playbook를 사용하여 AEO 감사 및 MCP 서버 최적화를 구현하고 ChatGPT, Gemini, Google의 성능을 향상시키는 방법을 알아보세요","es":"Convierta la auditoría AEO en un plan de implementación prioritario con el kit de herramientas del protocolo AEO","fr":"Convertissez l''audit AEO en un plan d''implémentation prioritaire avec le kit d''outils du protocole AEO","de":"Wandeln Sie die AEO-Audit in einen priorisierten Implementierungsplan mit dem AEO-Protokoll-Toolkit um","pt":"Aprenda a criar um plano de ação personalizado com o playbook para AEO, incluindo auditorias para ChatGPT, Gemini e Google","ru":"Создайте индивидуальный план действий с помощью playbook для AEO, включая аудиты для ChatGPT, Gemini и Google","ar":"تعلم كيفية إنشاء خطة عمل مخصصة بكتاب اللعب لبروتوكول AEO، بما في ذلك عمليات التدقيق ل ChatGPT و Gemini و Google"},"definition":{"en":"Playbook is a toolkit for converting AEO audits into actionable implementation plans, utilizing MCP servers for seamless integration.","zh":"Playbook 是一个用于将 AEO 审计转换为实施计划的工具，优化 MCP 服务器和 AI 工具的性能","ja":"Playbook は、AEO オーディットを実装計画に変換し、MCP サーバーと AI ツールの性能を最適化するツールです","ko":"Playbook는 AEO 감사를 구현 계획으로 변환하고 MCP 서버 및 AI 툴의 성능을 최적화하는 도구입니다","es":"Un playbook es un plan de implementación priorizado para la auditoría AEO","fr":"Un playbook est un plan d''implémentation prioritaire pour l''audit AEO","de":"Ein playbook ist ein priorisierter Implementierungsplan für die AEO-Audit","pt":"O que é playbook 