INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NoCodeify/aeo/playbook', 'playbook', 'NoCodeify', 'aeo', 'community', 'playbook NoCodeify aeo community The playbook skill generates a prioritized, week-by-week implementation plan from completed AEO audits, benefiting developers working with AI agents like ChatGPT and Gemini. Playbook 是一个 AEO 协议工具包，用于将完成的 AEO 审计转换为优先级的、周-by-周的实施计划，支持 MCP 服务器和 ChatGPT、Gemini、Google 审计 Playbook は、完了した AEO オーディットを優先順位の付いた、週ごとの実装計画に変換する AEO プロトコルツールキットであり、MCP サーバーと ChatGPT、Gemini、Google オーディットをサポートします Playbook는 완료된 AEO 감사를 우선 순위가 있는 주간별 구현 계획으로 변환하는 AEO 프로토콜 툴킷이며 MCP 서버 및 ChatGPT, Gemini, Google 감사를 지원합니다 El playbook es un kit de herramientas para convertir la auditoría AEO en un plan de implementación priorizado Le playbook est un kit d''outils pour convertir l''audit AEO en un plan d''implémentation prioritaire Das playbook ist ein Toolkit, um die AEO-Audit in einen priorisierten Implementierungsplan umzuwandeln O playbook para AEO é uma ferramenta que converte auditorias em planos de ação personalizados, incluindo suporte a ChatGPT, Gemini e Google. Playbook для AEO — это инструмент, который преобразует аудиты в индивидуальные планы действий, включая поддержку ChatGPT, Gemini и Google. كتاب اللعب لبروتوكول AEO هو أداة تحول عمليات التدقيق إلى خطط عمل مخصصة، بما في ذلك دعم ChatGPT و Gemini و Google. how to use playbook for AEO protocol playbook alternative for AI agents playbook setup guide for ChatGPT playbook vs AEO protocol tools what is playbook in AI development playbook install for Gemini audits playbook for Google audits optimization AEO 协议工具包 MCP 服务器优化 ChatGPT Gemini Google AI 工具 AEO 审计 实施计划 优化工具 Converts AEO audit files into prioritized implementation playbooks Supports MCP servers for ChatGPT, Gemini, and Google audits Generates week-by-week implementation plans for optimized AEO protocol setup Utilizes $ARGUMENTS for flexible audit file processing Enables seamless integration with AI agents for improved AEO protocol implementation Playbook is a toolkit for converting AEO audits into actionable implementation plans, utilizing MCP servers for seamless integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MarjanDB/brrr-generator/infoproviders-lookup-data', 'community', 'MarjanDB', 'brrr-generator', 'MarjanDB/brrr-generator', 'infoproviders-lookup-data', 0, 0, 20, '2026-03-08T01:57:15.507Z', '2026-03-08T02:11:38.938Z', '8208cc17f7fc5962f2adce7cff90decf6a291fe75c888705a7f26893ef57d702', '{"id":"MarjanDB/brrr-generator/infoproviders-lookup-data","name":"infoproviders-lookup-data","description":{"en":"The infoproviders-lookup-data skill generates tax reports for brokerage accounts, utilizing lookup data for company and country information. It benefits developers and users who need to comply with tax authority regulations.","zh":"infoproviders-lookup-data是一个用于生成税务报告的AI工具，支持CompanyLookupProvider和CountryLookupProvider","ja":"infoproviders-lookup-dataは、税務報告を生成するためのAIエージェントです。CompanyLookupProviderとCountryLookupProviderを使用します","ko":"infoproviders-lookup-data는 税務報告를 생성하는 AI 도구입니다. CompanyLookupProvider와 CountryLookupProvider를 지원합니다","es":"infoproviders-lookup-data es una habilidad de AI Agent que permite generar informes de impuestos para la autoridad fiscal de tu país. Utiliza proveedores de búsqueda de empresas y países para resolver ISIN y códigos de país.","fr":"infoproviders-lookup-data est une compétence d''AI Agent qui permet de générer des rapports de taxes pour l''autorité fiscale de votre pays. Elle utilise des fournisseurs de recherche d''entreprises et de pays pour résoudre les ISIN et les codes de pays.","de":"infoproviders-lookup-data ist eine Fähigkeit von Ii Agenten, die die Erstellung von Steuererklärungen für die Finanzbehörde Ihres Landes ermöglicht. Sie verwendet Anbieter von Unternehmens- und Ländersuche, um ISIN und Ländercodes aufzulösen.","pt":"O InfoProviders e lookup de dados permite gerar relatórios de impostos de corretagem para a autoridade fiscal do seu país, utilizando tecnologias como CompanyLookupProvider e CountryLookupProvider.","ru":"Используя InfoProviders и lookup данных, вы можете сгенерировать налоговые отчеты брокерского счета для налогового органа вашей страны, используя технологии như CompanyLookupProvider и CountryLookupProvider.","ar":"باستخدام InfoProviders وبيانات البحث، يمكنك إنشاء تقارير ضريبية لحساب الوساطة لسلطة الضرائب في بلدك، باستخدام تقنيات مثل CompanyLookupProvider وCountryLookupProvider."},"seo":{"title":{"en":"infoproviders-lookup-data: Tax Report Generation Setup Gu...","zh":"infoproviders-lookup-data 技术指南 - AIエージェント解决方案","ja":"infoproviders-lookup-data Setup Guide - AIエージェントを使用した税務報告","ko":"infoproviders-lookup-data 설정 가이드 - AI 도구를 사용한 税務報告","es":"Guía de configuración de infoproviders-lookup-data para i...","fr":"Configurer les données de recherche d''InfoProviders pour ...","de":"Einrichtungsführung für infoproviders-lookup-data zur Ste...","pt":"Guia de Configuração para InfoProviders e Lookup de Dados","ru":"Настройка ИИ Агентов: Руководство по InfoProviders и look...","ar":"دليل إعداد InfoProviders وبيانات البحث"},"description":{"en":"Discover how to generate tax reports for your country''s Tax Authority with infoproviders-lookup-data. Learn how to utilize CompanyLookupProvider and CountryL...","zh":"了解infoproviders-lookup-data的技术细节，包括CompanyLookupProvider和CountryLookupProvider的使用","ja":"infoproviders-lookup-dataの技術的な概要を学び、税務報告の自動化を実現する","ko":"infoproviders-lookup-data의 기술적인 세부 사항을 확인하고 税務報告를 자동화하는 방법을 배우십시오","es":"Aprende a generar informes de impuestos para la autoridad fiscal de tu país con infoproviders-lookup-data, una habilidad de AI Agent","fr":"Découvrez comment générer des rapports de taxes pour l''autorité fiscale de votre pays avec infoproviders-lookup-data, un outil d''AI","de":"Erfahren Sie, wie Sie Steuererklärungen für die Finanzbehörde Ihres Landes mit infoproviders-lookup-data, einem Tool von Ii Agenten, erstellen","pt":"Aprenda a configurar InfoProviders e lookup de dados para gerar relatórios de impostos de corretagem para a autoridade fiscal do seu país","ru":"Узнайте, как настроить InfoProviders и lookup данных для генерации налоговых отчетов брокерского счета для налогового органа вашей страны с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد InfoProviders وبيانات البحث لإنشاء تقارير ضريبية لحساب الوساطة لسلطة الضرائب في بلدك"},"definition":{"en":"infoproviders-lookup-data is a skill that provides lookup data for generating tax reports, using JSON files and online lookups to resolve company and country information.","zh":"infoproviders-lookup-data是一个用于税务报告的数据查找和提供的AI工具","ja":"infoproviders-lookup-dataは、税務報告のためのデータ検索と提供を実現するAIエージェントです","ko":"infoproviders-lookup-data는 税務報告를 위한 데이터 검색과 제공을 thực現하는 AI 도구입니다","es":"infoproviders-lookup-data es una habilidad de AI Agent que proporciona datos de búsqueda para informes de impuestos","fr":"infoproviders-lookup-data est une compétence d''AI Agent qui fournit des données de recherche pour les rapports de taxes","de":"infoproviders-lookup-data ist eine Fähigkeit von Ii Agenten, die Suchdaten für Steuererklärungen bereitstellt","pt":"O InfoProviders e lookup de dados é uma tecnologia que permite resolver informações de empresas e países para gerar relatórios de impostos","ru":"ИИ Агенты InfoProviders и lookup данных - это технология, которая позволяет решать информацию о компаниях и странах для генерации налоговых отчетов","ar":"InfoProviders وبيانات البحث هي تقنية تتيح حل المعلومات عن الشركات والبلدان لإنشاء تقارير ضريبية"},"features":{"en":["Utilizes CompanyLookupProvider to resolve ISIN to company info","Employs CountryLookupProvider to resolve country name to 2-letter code and treaty info","Falls back to missingCompaniesLookup.json and missingISINLookup.json for missing data","Supports online lookup for company and country information","Uses JSON lookup files for data storage and retrieval","Resolves country-specific treaty formats for tax reporting"],"zh":["使用CompanyLookupProvider解析ISIN到公司信息","使用CountryLookupProvider解析国家名称到2字母代码和税务条约信息","支持在线查找和本地查找","使用missingCompaniesLookup.json和missingISINLookup.json作为后备查找"],"ja":["CompanyLookupProviderを使用してISINを会社情報に解析","CountryLookupProviderを使用して国名を2字母コードと税務条約情報に解析","オンライン検索とローカル検索の両方をサポート","missingCompaniesLookup.jsonとmissingISINLookup.jsonを後備検索として使用"],"ko":["CompanyLookupProvider를 사용하여 ISIN을 회사 정보로 解析","CountryLookupProvider를 사용하여 국가 이름을 2자리 코드와 税務條約 정보로 解析","온라인 검색과 로컬 검색을 모두 지원","missingCompaniesLookup.json과 missingISINLookup.json을 後備 検索로 使用"],"es":["Resolución de ISIN a información de empresa mediante CompanyLookupProvider","Resolución de nombre de país a código de 2 letras y información de tratado mediante CountryLookupProvider","Uso de archivos JSON de búsqueda para datos de empresas y países","Compatibilidad con la búsqueda en línea y archivos de búsqueda de respaldo","Generación de informes de impuestos para la autoridad fiscal de tu país","Integración con herramientas de AI Agent para la automatización de procesos"],"fr":["Résolution de l''ISIN en informations d''entreprise via CompanyLookupProvider","Résolution du nom de pays en code à 2 lettres et informations de traité via CountryLookupProvider","Utilisation de fichiers JSON de recherche pour les données d''entreprises et de pays","Compatibilité avec la recherche en ligne et les fichiers de recherche de secours","Génération de rapports de taxes pour l''autorité fiscale de votre pays","Intégration avec des outils d''AI pour l''automatisation des processus"],"de":["Auflösung von ISIN in Unternehmensinformationen über CompanyLookupProvider","Auflösung von Ländernamen in 2-Buchstaben-Codes und Vertragsinformationen über CountryLookupProvider","Verwendung von JSON-Suchdateien für Unternehmens- und Länderdaten","Kompatibilität mit Online-Suche und Backup-Suchdateien","Erstellung von Steuererklärungen für die Finanzbehörde Ihres Landes","Integration mit Ii-Tools für die Automatisierung von Prozessen"],"pt":["Resolução de informações de empresas utilizando CompanyLookupProvider","Resolução de informações de países utilizando CountryLookupProvider","Utilização de arquivos JSON para lookup de dados","Suporte a treaty format para uso em relatórios de impostos","Integração com tecnologias de lookup de dados online"],"ru":["Решение информации о компаниях с помощью CompanyLookupProvider","Решение информации о странах с помощью CountryLookupProvider","Использование файлов JSON для lookup данных","Поддержка treaty format для использования в налоговых отчетах","Интеграция с технологиями онлайн-lookup данных"],"ar":["حل المعلومات عن الشركات باستخدام CompanyLookupProvider","حل المعلومات عن البلدان باستخدام CountryLookupProvider","استخدام ملفات JSON للبحث عن البيانات","دعم صيغة المعاهدة للاستخدام في التقارير الضريبية","التكامل مع تقنيات البحث عن البيانات عبر الإنترنت"]},"keywords":{"en":["how to use infoproviders-lookup-data","infoproviders-lookup-data setup guide","infoproviders-lookup-data alternative","infoproviders-lookup-data vs tax reporting software","what is infoproviders-lookup-data","infoproviders-lookup-data install","generating tax reports with infoproviders-lookup-data","company lookup provider","country lookup provider","json lookup files for tax reporting"],"zh":["infoproviders-lookup-data","AIエージェント","税務报告","CompanyLookupProvider","CountryLookupProvider","数据查找","税务条约"],"ja":["infoproviders-lookup-data","AIエージェント","税務報告","CompanyLookupProvider","CountryLookupProvider","データ検索","税務条約"],"ko":["infoproviders-lookup-data","AI 도구","税務報告","CompanyLookupProvider","CountryLookupProvider","데이터 검색","税務條約"],"es":["infoproviders-lookup-data","AI Agent","informes de impuestos","autoridad fiscal","ISIN","código de país","CompanyLookupProvider","CountryLookupProvider","JSON","búsqueda en línea"],"fr":["infoproviders-lookup-data","AI","rapports de taxes","autorité fiscale","ISIN","code de pays","CompanyLookupProvider","CountryLookupProvider","JSON","recherche en ligne"],"de":["infoproviders-lookup-data","Ii Agenten","Steuererklärungen","Finanzbehörde","ISIN","Ländercode","CompanyLookupProvider","CountryLookupProvider","JSON","Online-Suche"],"pt":["InfoProviders","lookup de dados","relatórios de impostos","CompanyLookupProvider","CountryLookupProvider","treaty format","arquivos JSON","tecnologias de lookup de dados online"],"ru":["ИИ Агенты","InfoProviders","lookup данных","налоговые отчеты","CompanyLookupProvider","CountryLookupProvider","treaty format","файлы JSON","технологии онлайн-lookup данных"],"ar":["InfoProviders","بيانات البحث","تقارير ضريبية","CompanyLookupProvider","CountryLookupProvider","صيغة المعاهدة","ملفات JSON","تقنيات البحث عن البيانات عبر الإنترنت"]}},"owner":"MarjanDB","repo":"brrr-generator","repoPath":"MarjanDB/brrr-generator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"infoproviders-lookup-data","description":"When and how to edit InfoProviders lookup JSONs (company, country, treaty, ISIN). Use when fixing Failed processing stock lot, wrong country or company data, or adding fallbacks for unresolved identifiers.","bodyPreview":"# InfoProviders and lookup data\n\nGeneric guidance for `src/InfoProviders/` and the JSON lookup files. Country-specific use (e.g. treaty format) may be documented in a tax-authority skill.\n\n## Where lookups are used\n\n- **CompanyLookupProvider** – Resolves ISIN to company info (name, address, country). Tries online lookup first; falls back to **missingCompaniesLookup.json** and **missingISINLookup.json**.\n- **CountryLookupProvider** – Resolves country name to 2-letter code and treaty info. Uses **","body":"# InfoProviders and lookup data\n\nGeneric guidance for `src/InfoProviders/` and the JSON lookup files. Country-specific use (e.g. treaty format) may be documented in a tax-authority skill.\n\n## Where lookups are used\n\n- **CompanyLookupProvider** – Resolves ISIN to company info (name, address, country). Tries online lookup first; falls back to **missingCompaniesLookup.json** and **missingISINLookup.json**.\n- **CountryLookupProvider** – Resolves country name to 2-letter code and treaty info. Uses **internationalTreaties.json** and **specialCountryMappings.json**.\n\nTax authority report generation and staging processors use these when annotating events (e.g. company domicile, treaty relief).\n\n## When to edit which file\n\n| Symptom                                                      | Likely fix                                                                                                                                                                                                                                             |\n| ------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| **\"Failed processing stock lot\"** or \"Failed lookup of ISIN\" | Lot or event has an identifier (ISIN/ticker) the pipeline can’t resolve. Add or correct an entry in **missingISINLookup.json** (ISIN → ticker for online lookup) or **missingCompaniesLookup.json** (ISIN → full company object for offline fallback). |\n| Wrong or missing **company** name/address                    | Add or update entry in **missingCompaniesLookup.json** for that identifier (e.g. ISIN).                                                                                                                                                                |\n| Online lookup fails for a known ISIN/ticker                  | Add **missingISINLookup.json** entry: key = ISIN, value = ticker symbol used by the lookup service (e.g. for yfinance).                                                                                                                                |\n| Wrong **country** code or unknown country name               | Add or update **specialCountryMappings.json**: key = country name as in broker/data, value = 2-letter ISO code.                                                                                                                                        |\n| **Treaty** reference (e.g. tax relief) for a country         | Add or update **internationalTreaties.json** under the structure used by CountryLookupProvider (e.g. treaties by country code). Exact key/value format is defined by the tax authority; see country-specific skill if applicable.                      |\n\n## File formats (generic)\n\n- **missingISINLookup.json** – Object: identifier (e.g. ISIN) → string (e.g. ticker). Used when resolution by identifier fails so the provider can try again with the mapped value.\n- **missingCompaniesLookup.json** – Object: identifier (e.g. ISIN) → company object. Company object typically has fields such as shortName, longName, address1, address2, city, zip, country (and optionally state). Used when no online company data is available.\n- **specialCountryMappings.json** – Object: country name (as in data) → 2-letter country code. Overrides default country resolution.\n- **internationalTreaties.json** – Nested structure (e.g. treaties.taxRelief) keyed by country code; values are treaty references. Structure and semantics depend on the tax authority; see country skill for details.\n\nAll paths are under `src/InfoProviders/`. After editing, re-run the pipeline; no separate reload step is required.\n"},"lastSynced":"2026-03-08T02:11:38.938Z","agentAnalysis":{"suitability":{"en":"Ideal for Financial Analysis Agents requiring precise company and country information for tax compliance","zh":"适合需要准确公司和国家信息以用于税务合规的金融分析代理","ja":"税務遵守のために正確な会社および国情報を必要とする金融分析エージェントに適しています","ko":"세무 준수를 위해 정확한 회사 및 국가 정보를 필요로 하는 금융 분석 에이전트에게 적합합니다","es":"Ideal para agentes de análisis financiero que requieren información precisa de empresas y países para el cumplimiento fiscal","fr":"Idéal pour les agents d''analyse financière nécessitant des informations précises sur les entreprises et les pays pour la conformité fiscale","de":"Ideal für Finanzanalyse-Agents, die präzise Unternehmens- und Länderinformationen für die Steuereinhaltung benötigen","pt":"Ideal para Agentes de Análise Financeira que exigem informações precisas de empresa e país para conformidade fiscal","ru":"Идеально для финансовых аналитических агентов, требующих точной информации о компании и стране для налогового соблюдения","ar":"مثالي لعمليات تحليل المالية التي تتطلب معلومات دقيقة للشركة والبلد لامتثال الضريبي"},"recommendation":{"en":"Empowers agents to generate accurate tax reports for brokerage accounts by utilizing lookup data for company and country information, leveraging JSON lookup files and online lookup capabilities for ISIN and country codes","zh":"通过利用公司和国家信息的查找数据，利用JSON查找文件和ISIN及国家代码的在线查找功能，赋予代理生成准确的税务报告的能力，用于经纪账户","ja":"JSONのルックアップファイルおよびISINと国コードのオンラインルックアップ機能を利用して、会社および国情報のルックアップデータを活用し、ブローカー口座のための正確な税務報告書を生成するエージェントの能力を提供します","ko":"JSON 조회 파일 및 ISIN 및 국가 코드의 온라인 조회 기능을 활용하여 회사 및 국가 정보의 조회 데이터를 사용하여,ブローカー 계좌를 위한 정확한 세무 보고서를 생성할 수 있는 에이전트의 능력을 제공합니다","es":"Habilita a los agentes a generar informes fiscales precisos para cuentas de corretaje utilizando datos de búsqueda para información de empresas y países, aprovechando archivos de búsqueda JSON y capacidades de búsqueda en línea para ISIN y códigos de país","fr":"Permet aux agents de générer des rapports fiscaux précis pour les comptes de courtage en utilisant des données de recherche pour les informations sur les entreprises et les pays, en exploitant les fichiers de recherche JSON et les capacités de recherche en ligne pour les codes ISIN et les codes de pays","de":"Ermöglicht es den Agents, genaue Steuerberichte für Brokerage-Konten zu generieren, indem sie Lookup-Daten für Unternehmens- und Länderinformationen nutzen, JSON-Lookup-Dateien und Online-Lookup-Funktionen für ISIN und Ländercodes nutzend","pt":"Habilita agentes a gerar relatórios fiscais precisos para contas de corretagem, utilizando dados de pesquisa para informações de empresa e país, aproveitando arquivos de pesquisa JSON e capacidades de pesquisa online para códigos ISIN e país","ru":"Наделяет агентов возможностью генерировать точные налоговые отчеты для брокерских счетов, используя данные поиска для информации о компании и стране, используя файлы JSON поиска и онлайн-возможности поиска для кодов ISIN и страны","ar":"تمكين الوكيل من إنشاء تقارير ضريبية دقيقة لحسابات الوساطة من خلال استخدام بيانات البحث لمعلومات الشركة والبلد، واستخدام ملفات البحث JSON والقدرات البحثية عبر الإنترنت للرموز ISIN وأكواد البلد"},"useCases":{"en":["Resolving ISIN to company info for tax reporting","Generating country-specific treaty formats for brokerage accounts","Automating tax report generation with accurate company and country data"],"zh":["解决ISIN到公司信息的税务报告问题","为经纪账户生成国家特定的税务协定格式","使用准确的公司和国家数据自动化税务报告的生成"],"ja":["税務報告のためにISINを会社情報に解決する","ブローカー口座のための国別の税務条約形式を生成する","正確な会社および国データを使用して税務報告書の自動生成を実現する"],"ko":["세무 보고서를 위한 ISIN을 회사 정보로 해결하는こと","ブローカー 계좌를 위한 국가별 세무 조약 형식을 생성하는こと","정확한 회사 및 국가 데이터를 사용하여 세무 보고서의 자동 생성을 실현하는こと"],"es":["Resolver ISIN para obtener información de la empresa para la presentación de informes fiscales","Generar formatos de tratados específicos del país para cuentas de corretaje","Automatizar la generación de informes fiscales con datos precisos de empresas y países"],"fr":["Résoudre ISIN pour obtenir des informations sur l''entreprise pour la déclaration fiscale","Générer des formats de traités spécifiques au pays pour les comptes de courtage","Automatiser la génération de rapports fiscaux avec des données précises sur les entreprises et les pays"],"de":["ISIN in Unternehmensinformationen für Steuererklärungen auflösen","Länder-spezifische Vertragsformate für Brokerage-Konten generieren","Steuererklärungserstellung mit genauen Unternehmens- und Länderdaten automatisieren"],"pt":["Resolver ISIN para informações da empresa para relatórios fiscais","Gerar formatos de tratado específicos do país para contas de corretagem","Automatizar a geração de relatórios fiscais com dados precisos da empresa e do país"],"ru":["Решить ISIN для информации о компании для налогового отчета","Сгенерировать форматы договоров, специфичные для страны, для брокерских счетов","Автоматизировать генерацию налоговых отчетов с точными данными о компании и стране"],"ar":["حل ISIN لمعلومات الشركة لتقرير الضريبي","إصدار تنسيقات معاهدة محددة للبلد لحسابات الوساطة","آليّة إنشاء تقارير ضريبية بدقة باستخدام بيانات الشركة والبلد"]},"limitations":{"en":["Requires access to online lookup services or JSON lookup files","Country-specific use may require additional tax-authority skills"],"zh":["需要访问在线查找服务或JSON查找文件","国家特定的使用可能需要额外的税务权限技能"],"ja":["オンラインルックアップサービスまたはJSONルックアップファイルへのアクセスが必要","国別の使用には追加の税務権限スキルが必要になる可能性がある"],"ko":["온라인 조회 서비스 또는 JSON 조회 파일에 대한 액세스가 필요","국가별 사용에는 추가적인 세무 권한 기술이 필요할 수 있음"],"es":["Requiere acceso a servicios de búsqueda en línea o archivos de búsqueda JSON","El uso específico del país puede requerir habilidades adicionales de autoridad fiscal"],"fr":["Nécessite un accès aux services de recherche en ligne ou aux fichiers de recherche JSON","L''utilisation spécifique au pays peut nécessiter des compétences supplémentaires en matière d''autorité fiscale"],"de":["Erfordert Zugriff auf Online-Suchdienste oder JSON-Suchdateien","Länder-spezifische Nutzung kann zusätzliche Steuerbehördenfähigkeiten erfordern"],"pt":["Exige acesso a serviços de pesquisa online ou arquivos de pesquisa JSON","Uso específico do país pode exigir habilidades adicionais de autoridade fiscal"],"ru":["Требует доступа к онлайн-сервисам поиска или файлам JSON поиска","Страно-специфическое использование может требовать дополнительных навыков налоговых органов"],"ar":["يتطلب الوصول إلى خدمات البحث عبر الإنترنت أو ملفات البحث JSON","استخدام معين للبلد قد يتطلب مهارات إضافية للسلطات الضريبية"]},"version":4},"contentHash":"8208cc17f7fc5962f2adce7cff90decf6a291fe7