INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sneat-co/sneat-apps/nx-plugins', 'nx-plugins', 'sneat-co', 'sneat-apps', 'community', 'nx-plugins sneat-co sneat-apps community The nx-plugins skill allows developers to manage plugins using commands like `pnpm nx list` and `pnpm nx add`. It benefits developers working with Nx projects. nx-plugins 提供了方便的插件安装和管理，使用 pnpm nx list 和 pnpm nx add 命令 nx-plugins は、pnpm nx list と pnpm nx add コマンドを使用してプラグインをインストールおよび管理します nx-plugins는 pnpm nx list와 pnpm nx add 명령을 사용하여 플러그인을 설치하고 관리합니다 nx-plugins es una herramienta para gestionar plugins en proyectos nx. Puedes instalar plugins con pnpm nx add nx-plugins est un outil pour gérer les plugins dans les projets nx. Vous pouvez installer des plugins avec pnpm nx add nx-plugins ist ein Tool zum Verwalten von Plugins in nx-Projekten. Sie können Plugins mit pnpm nx add installieren O nx-plugins é uma ferramenta para gerenciar plugins nx. Use `pnpm nx list` para listar plugins e `pnpm nx add` para instalá-los nx-plugins - это инструмент для управления плагинами nx. Используйте `pnpm nx list` для списка плагинов и `pnpm nx add` для их установки nx-plugins هو أداة لإدارة البرامج المساعدة nx. استخدم `pnpm nx list` للقائمة البرامج المساعدة و `pnpm nx add` لتثبيتها how to use nx-plugins nx-plugins setup guide nx-plugins install what is nx-plugins nx-plugins alternative nx-plugins vs other plugin managers nx-plugins 安装 nx-plugins 使用 插件管理 pnpm nx list pnpm nx add React 插件 CLI 管理 Lists available plugins using `pnpm nx list` command Installs plugins using `pnpm nx add` command Supports plugin installation with specific examples like `@nx/react` Enables easy management of plugins in Nx projects Utilizes pnpm for package management nx-plugins is a skill for managing plugins in Nx projects, enabling developers to easily find and install new plugins.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shiguruikai/cam-head-tracker/doc-reviewer', 'community', 'shiguruikai', 'cam-head-tracker', 'shiguruikai/cam-head-tracker', 'doc-reviewer', 0, 0, 20, '2026-03-08T01:57:15.566Z', '2026-03-08T02:11:42.148Z', 'cf42d754a05642ebc411bc1d31f0ea1fa679b2aabe384248c2835ec561971711', '{"id":"shiguruikai/cam-head-tracker/doc-reviewer","name":"doc-reviewer","description":{"en":"The doc-reviewer skill provides thorough document reviews for developers, utilizing commands like git status and gh pr view to ensure accurate and detailed analysis.","zh":"doc-reviewer是一款基于UDP的姿势数据发送工具，支持opentrack集成，用于提高开发效率","ja":"doc-reviewerはUDPベースの姿勢データ送信ツールで、opentrackとの統合をサポートし、開発効率を向上させるために使用されます","ko":"doc-reviewer는 UDP 기반의 姿勢 데이터 전송 도구로, opentrack와의 통합을 지원하여 개발 효율을 높이는 데 사용됩니다","es":"Doc-reviewer es una herramienta de revisión de documentos que utiliza tecnologías como git y gh para analizar cambios en el código y proporcionar una revisión detallada","fr":"Doc-reviewer est un outil d''analyse de documents qui utilise des technologies comme git et gh pour examiner les modifications du code et fournir une révision détaillée","de":"Doc-reviewer ist ein Dokumentenprüfungstool, das Technologien wie git und gh verwendet, um Änderungen im Code zu analysieren und eine detaillierte Überprüfung bereitzustellen","pt":"O Doc-Reviewer é uma ferramenta de revisão de documentos que ajuda a melhorar a qualidade do código, utilizando técnicas de análise de código e revisão de documentos","ru":"Doc-Reviewer - это инструмент для обзора документов, который помогает улучшить качество кода, используя методы анализа кода и обзора документов","ar":"Doc-Reviewer هي أداة مراجعة الوثائق التي تساعد على تحسين جودة الكود، باستخدام تقنيات تحليل الكود ومراجعة الوثائق"},"seo":{"title":{"en":"doc-reviewer: Setup Guide for AI Agents | Camera-Based He...","zh":"doc-reviewer Setup Guide: 使用UDP发送姿势数据","ja":"doc-reviewer セットアップガイド: 姿勢データをopentrackにUDPで送信","ko":"doc-reviewer 설정 가이드: UDP를 사용한 姿勢 데이터 전송","es":"Guía de configuración de doc-reviewer: Análisis de docume...","fr":"Guide de configuration de doc-reviewer: Analyse de docume...","de":"Konfigurationsleitfaden für doc-reviewer: Tiefere Dokumen...","pt":"Guia de Configuração do Doc-Reviewer: Ferramenta de Revis...","ru":"Настройка Doc-Reviewer: Инструмент для Тщательного Обзора...","ar":"دليل إعداد Doc-Reviewer: أداة مراجعة الوثائق"},"description":{"en":"Discover how to leverage doc-reviewer for efficient code reviews. Learn to integrate with opentrack via UDP and streamline your development workflow today!","zh":"了解doc-reviewer的功能和技术细节，包括UDP数据发送和opentrack集成，提高开发效率","ja":"doc-reviewerの機能と技術的詳細を学び、UDPデータ送信とopentrackとの統合を活用して開発効率を向上させる","ko":"doc-reviewer의 기능과 기술적 세부 사항을 알아보고, UDP 데이터 전송 및 opentrack 통합을 통해 개발 효율을 높이세요","es":"Aprende a configurar y utilizar doc-reviewer para análisis de documentos detallados y revisión de código con tecnologías como git y gh","fr":"Découvrez comment configurer et utiliser doc-reviewer pour analyser en profondeur les documents et examiner le code avec des technologies comme git et gh","de":"Erfahren Sie, wie Sie doc-reviewer konfigurieren und verwenden, um detaillierte Dokumentenanalysen und Code-Reviews mit Technologien wie git und gh durchzufü...","pt":"Aprenda a configurar e usar o Doc-Reviewer, uma ferramenta de revisão de documentos baseada em AI que ajuda a melhorar a qualidade do código","ru":"Узнайте, как настроить и использовать Doc-Reviewer, инструмент для обзора документов на основе ИИ, который помогает улучшить качество кода","ar":"تعرف على كيفية إعداد و استخدام Doc-Reviewer، أداة مراجعة الوثائق التي تعتمد على الذكاء الاصطناعي لمساعدة في تحسين جودة الكود"},"definition":{"en":"doc-reviewer is a camera-based head tracking application that sends posture data to opentrack via UDP, facilitating comprehensive document reviews.","zh":"doc-reviewer是一款AI工具，用于发送姿势数据","ja":"doc-reviewerはAIエージェントの一種で、姿勢データを送信するために使用されます","ko":"doc-reviewer는 AI 도구의 일종으로, 姿勢 데이터를 전송하는 데 사용됩니다","es":"Doc-reviewer es una herramienta de revisión de documentos que realiza un análisis detallado de los cambios en el código","fr":"Doc-reviewer est un outil d''analyse de documents qui effectue une analyse approfondie des modifications du code","de":"Doc-reviewer ist ein Dokumentenprüfungstool, das eine detaillierte Analyse der Änderungen im Code durchführt","pt":"O que é Doc-Reviewer? É uma ferramenta de revisão de documentos que utiliza técnicas de análise de código para melhorar a qualidade do código","ru":"Что такое Doc-Reviewer? Это инструмент для обзора документов, который использует методы анализа кода для улучшения качества кода","ar":"ما هو Doc-Reviewer؟ هو أداة مراجعة الوثائق التي تستخدم تقنيات تحليل الكود لتحسين جودة الكود"},"features":{"en":["Utilizes git status -s to detect uncommitted changes","Supports checkout of PRs using gh pr checkout","Analyzes differences with gh pr diff","Performs detailed analysis of code changes","Checks for accuracy and context completeness","Integrates with opentrack via UDP for posture data transmission"],"zh":["支持UDP数据发送","与opentrack集成","使用git status和git diff进行代码review","支持PR和本地代码review","提供详细的代码分析报告"],"ja":["UDPデータ送信をサポート","opentrackとの統合","git statusとgit diffを使用したコードレビュー","PRとローカルコードレビューをサポート","詳細なコード分析レポートを提供"],"ko":["UDP 데이터 전송 지원","opentrack와의 통합","git status와 git diff를 사용한 코드 리뷰","PR과 로컬 코드 리뷰 지원","상세한 코드 분석 리포트 제공"],"es":["Análisis de cambios en el código con git","Revisión de código con gh","Análisis de documentos en profundidad","Compatibilidad con tecnologías como git y gh","Revisión detallada de los cambios en el código"],"fr":["Analyse des modifications du code avec git","Examen de code avec gh","Analyse approfondie des documents","Compatibilité avec des technologies comme git et gh","Révision détaillée des modifications du code"],"de":["Analyse von Änderungen im Code mit git","Code-Review mit gh","Detaillierte Dokumentenanalyse","Kompatibilität mit Technologien wie git und gh","Detaillierte Überprüfung der Änderungen im Code"],"pt":["Análise de código utilizando git diff e git diff --staged","Revisão de documentos com foco em precisão e contexto","Compatibilidade com gh pr checkout e gh pr view","Suporte a UDP para envio de dados de posição","Integração com opentrack para envio de dados de posição"],"ru":["Анализ кода с использованием git diff и git diff --staged","Обзор документов с фокусом на точности и контексте","Совместимость с gh pr checkout и gh pr view","Поддержка UDP для отправки данных позиции","Интеграция с opentrack для отправки данных позиции"],"ar":["تحليل الكود باستخدام git diff و git diff --staged","مراجعة الوثائق مع التركيز على الدقة والسياق","التكامل مع gh pr checkout و gh pr view","دعم بروتوكول UDP لsending بيانات الموقع","التكامل مع opentrack لإرسال بيانات الموقع"]},"keywords":{"en":["how to use doc-reviewer","doc-reviewer setup guide","opentrack integration with doc-reviewer","git status for code review","gh pr view for pull request analysis","udp protocol for posture data transmission","doc-reviewer vs traditional code review tools","installing doc-reviewer for AI agents","doc-reviewer for camera-based head tracking"],"zh":["doc-reviewer","UDP数据发送","opentrack集成","代码review","AI工具","开发效率","git status","git diff"],"ja":["doc-reviewer","UDPデータ送信","opentrack統合","コードレビュー","AIエージェント","開発効率","git status","git diff"],"ko":["doc-reviewer","UDP 데이터 전송","opentrack 통합","코드 리뷰","AI 도구","개발 효율","git status","git diff"],"es":["doc-reviewer","herramientas de revisión de documentos","análisis de código","git","gh","revisión de código","análisis de documentos","desarrollo de software","herramientas de desarrollo"],"fr":["doc-reviewer","outils d''analyse de documents","analyse de code","git","gh","examen de code","analyse de documents","développement de logiciels","outils de développement"],"de":["doc-reviewer","Dokumentenprüfungstools","Code-Analyse","git","gh","Code-Review","Dokumentenanalyse","Software-Entwicklung","Entwicklungstools"],"pt":["Doc-Reviewer","revisão de documentos","análise de código","git diff","gh pr checkout","opentrack","UDP","desenvolvimento de software","ferramentas de revisão de código"],"ru":["Doc-Reviewer","обзор документов","анализ кода","git diff","gh pr checkout","opentrack","UDP","разработка программного обеспечения","инструменты для обзора кода"],"ar":["Doc-Reviewer","مراجعة الوثائق","تحليل الكود","git diff","gh pr checkout","opentrack","UDP","تطوير البرمجيات","أدوات مراجعة الكود"]}},"owner":"shiguruikai","repo":"cam-head-tracker","repoPath":"shiguruikai/cam-head-tracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.566Z","topics":[],"category":"community","skillMd":{"name":"doc-reviewer","description":"","bodyPreview":"# Document Reviewer\n\n専門的かつ徹底的なドキュメントレビューをします。\n\n## 進め方\n\n### 1. レビュー対象の把握\n\n変更の意図や背景を把握する。\n\n- **PRの場合**:\n    - **競合回避**: `git status -s`で未コミットがある場合、ユーザーに`git stash`を促す。\n    - **チェックアウト**: `gh pr checkout <pr_number>`\n    - **PR情報取得**: `gh pr view <pr_number>`\n    - **差分取得**: `gh pr diff <pr_number>`\n- **ローカル変更の場合**: レビュー対象の指定がない場合、`git diff`および`git diff --staged`で差分を確認する。\n\n### 2. 詳細な分析\n\n- **コンテキストの補完**: 詳細なレビューを要求されている場合、または、変更の意図や背景が不明瞭な場合、関連ファイルをすべて読み込み、全体の整合性を確認する。\n\n以下の観点で分析:\n\n- **正確性**: 内容は正確で、","body":"# Document Reviewer\n\n専門的かつ徹底的なドキュメントレビューをします。\n\n## 進め方\n\n### 1. レビュー対象の把握\n\n変更の意図や背景を把握する。\n\n- **PRの場合**:\n    - **競合回避**: `git status -s`で未コミットがある場合、ユーザーに`git stash`を促す。\n    - **チェックアウト**: `gh pr checkout <pr_number>`\n    - **PR情報取得**: `gh pr view <pr_number>`\n    - **差分取得**: `gh pr diff <pr_number>`\n- **ローカル変更の場合**: レビュー対象の指定がない場合、`git diff`および`git diff --staged`で差分を確認する。\n\n### 2. 詳細な分析\n\n- **コンテキストの補完**: 詳細なレビューを要求されている場合、または、変更の意図や背景が不明瞭な場合、関連ファイルをすべて読み込み、全体の整合性を確認する。\n\n以下の観点で分析:\n\n- **正確性**: 内容は正確で、誤りがないか？\n- **明確性**: 曖昧な表現はなく、誰が読んでも理解しやすいか？\n- **一貫性**: 用語、書式、スタイルが一貫しているか？\n- **完全性**: 不足している情報はないか？\n- **構成**: 論理的な流れになっており、理解しやすい構成か？\n- **最新性**: 最新の情報に基づいているか？\n\n### 3. フィードバックの提示\n\n- **概要**: 変更の概要と全体的な評価\n- **指摘事項**: `重大`, `中度`, `軽微`のレベル別で記述\n- **結論**: マージやコミットの可否、推奨や提案\n"},"lastSynced":"2026-03-08T02:11:42.148Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents utilizing Git and GitHub for comprehensive document analysis.","zh":"适用于使用 Git 和 GitHub 进行全面文档分析的代码审查代理。","ja":"Git および GitHub を使用した包括的なドキュメント分析に適したコードレビューエージェントに最適です。","ko":"Git 및 GitHub를 사용한 종합 문서 분석을 위한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que utilizan Git y GitHub para un análisis de documentos integral.","fr":"Idéal pour les agents de révision de code utilisant Git et GitHub pour une analyse de documents complète.","de":"Ideal für Code-Review-Agenten, die Git und GitHub für eine umfassende Dokumentenanalyse verwenden.","pt":"Ideal para Agentes de Revisão de Código que utilizam Git e GitHub para análise de documentos abrangente.","ru":"Идеально для агентов кодового обзора, использующих Git и GitHub для всестороннего анализа документов.","ar":"مثالي للوكلاء المراجعين للرمز الذين يستخدمون Git و GitHub لتحليل الوثائق الشامل."},"recommendation":{"en":"Empowers agents to perform thorough document reviews using Git commands like `git status` and `git diff`, and GitHub commands like `gh pr view` and `gh pr diff`, ensuring accurate and detailed analysis of code changes and pull requests.","zh":"赋予代理使用 Git 命令（如 `git status` 和 `git diff`）以及 GitHub 命令（如 `gh pr view` 和 `gh pr diff`）进行彻底的文档审查，确保代码更改和拉取请求的准确、详细分析。","ja":"エージェントが `git status` や `git diff` などの Git コマンドと `gh pr view` や `gh pr diff` などの GitHub コマンドを使用して、包括的なドキュメントレビューを実行できるようにし、コードの変更やプルリクエストの正確で詳細な分析を可能にします。","ko":"에이전트가 `git status` 및 `git diff`와 같은 Git 명령 및 `gh pr view` 및 `gh pr diff`와 같은 GitHub 명령을 사용하여 철저한 문서 검토를 수행할 수 있도록 하여 코드 변경 및 풀 요청에 대한 정확하고詳細한 분석을 보장합니다.","es":"Permite a los agentes realizar revisiones de documentos exhaustivas utilizando comandos Git como `git status` y `git diff`, y comandos GitHub como `gh pr view` y `gh pr diff`, lo que garantiza un análisis preciso y detallado de los cambios de código y solicitudes de incorporación.","fr":"Permet aux agents d''effectuer des examens de documents approfondis en utilisant des commandes Git comme `git status` et `git diff`, et des commandes GitHub comme `gh pr view` et `gh pr diff`, garantissant ainsi une analyse précise et détaillée des modifications de code et des demandes d''extraction.","de":"Ermöglicht es den Agenten, gründliche Dokumentenprüfungen durchzuführen, indem sie Git-Befehle wie `git status` und `git diff` sowie GitHub-Befehle wie `gh pr view` und `gh pr diff` verwenden, um so eine genaue und detaillierte Analyse von Codeänderungen und Pull-Requests sicherzustellen.","pt":"Permite que os agentes realizem revisões de documentos abrangentes usando comandos Git como `git status` e `git diff`, e comandos GitHub como `gh pr view` e `gh pr diff`, garantindo uma análise precisa e detalhada das alterações de código e solicitações de pull.","ru":"Наделяет агентов возможностью проводить тщательные обзоры документов с помощью команд Git, таких как `git status` и `git diff`, и команд GitHub, таких как `gh pr view` и `gh pr diff`, обеспечивая точный и подробный анализ изменений кода и запросов на включение.","ar":"يمنح الوكلاء khảية إجراء مراجعات وثائق شاملة باستخدام أوامر Git مثل `git status` و `git diff` ، وأوامر GitHub مثل `gh pr view` و `gh pr diff` ، مما يضمن تحليلًا دقيقًا ومفصلاً لتعديلات الرمز وطلبات السحب."},"useCases":{"en":["Automating code reviews for pull requests","Analyzing local code changes with `git diff`","Retrieving PR information with `gh pr view`"],"zh":["自动化拉取请求的代码审查","使用 `git diff` 分析本地代码更改","使用 `gh pr view` 检索 PR 信息"],"ja":["プルリクエストのコードレビューを自動化する","`git diff` を使用してローカルのコード変更を分析する","`gh pr view` を使用して PR 情報を取得する"],"ko":["풀 요청의 코드 리뷰 자동화","`git diff`를 사용한 로컬 코드 변경 분석","`gh pr view`를 사용한 PR 정보检索"],"es":["Automatización de revisiones de código para solicitudes de incorporación","Análisis de cambios de código local con `git diff`","Recuperación de información de PR con `gh pr view`"],"fr":["Automatisation des examens de code pour les demandes d''extraction","Analyse des modifications de code local avec `git diff`","Récupération d''informations de PR avec `gh pr view`"],"de":["Automatisierung von Code-Reviews für Pull-Requests","Analyse von lokalen Codeänderungen mit `git diff`","Abruf von PR-Informationen mit `gh pr view`"],"pt":["Automatizar revisões de código para solicitações de pull","Analizar alterações de código local com `git diff`","Recuperar informações de PR com `gh pr view`"],"ru":["Автоматизировать обзоры кода для запросов на включение","Анализировать местные изменения кода с помощью `git diff`","Получать информацию о PR с помощью `gh pr view`"],"ar":["تأتمة مراجعة الرمز لطلبات السحب","تحليل التغييرات المحلية للرمز مع `git diff`","استرجاع معلومات PR مع `gh pr view`"]},"limitations":{"en":["Requires Git and GitHub installation","Limited to Git-based version control systems"],"zh":["需要安装 Git 和 GitHub","仅限 Git 基础的版本控制系统"],"ja":["Git および GitHub のインストールが必要","Git ベースのバージョン管理システムに限定される"],"ko":["Git 및 GitHub 설치 필요","Git 기반 버전 관리 시스템으로 제한됨"],"es":["Requiere la instalación de Git y GitHub","Limitado a sistemas de control de versiones basados en Git"],"fr":["Nécessite l''installation de Git et GitHub","Limité aux systèmes de contrôle de version basés sur Git"],"de":["Benötigt die Installation von Git und GitHub","Begrenzt auf Git-basierte Versionskontrollsysteme"],"pt":["Requer instalação do Git e GitHub","Limitado a sistemas de controle de versão baseados em Git"],"ru":["Требует установки Git и GitHub","Ограничен системами контроля версий на основе Git"],"ar":["يتطلب تثبيت Git و GitHub","محدود بنظم التحكم في الإصدارات القائمة على Git"]},"version":4},"contentHash":"cf42d754a05642ebc411bc1d31f0ea1fa679b2aabe384248c2835ec561971711","qualityScore":20}');
