INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shiguruikai/cam-head-tracker/doc-reviewer', 'doc-reviewer', 'shiguruikai', 'cam-head-tracker', 'community', 'doc-reviewer shiguruikai cam-head-tracker community The doc-reviewer skill provides thorough document reviews for developers, utilizing commands like git status and gh pr view to ensure accurate and detailed analysis. doc-reviewer是一款基于UDP的姿势数据发送工具，支持opentrack集成，用于提高开发效率 doc-reviewerはUDPベースの姿勢データ送信ツールで、opentrackとの統合をサポートし、開発効率を向上させるために使用されます doc-reviewer는 UDP 기반의 姿勢 데이터 전송 도구로, opentrack와의 통합을 지원하여 개발 효율을 높이는 데 사용됩니다 Doc-reviewer es una herramienta de revisión de documentos que utiliza tecnologías como git y gh para analizar cambios en el código y proporcionar una revisión detallada Doc-reviewer est un outil d''analyse de documents qui utilise des technologies comme git et gh pour examiner les modifications du code et fournir une révision détaillée Doc-reviewer ist ein Dokumentenprüfungstool, das Technologien wie git und gh verwendet, um Änderungen im Code zu analysieren und eine detaillierte Überprüfung bereitzustellen O Doc-Reviewer é uma ferramenta de revisão de documentos que ajuda a melhorar a qualidade do código, utilizando técnicas de análise de código e revisão de documentos Doc-Reviewer - это инструмент для обзора документов, который помогает улучшить качество кода, используя методы анализа кода и обзора документов Doc-Reviewer هي أداة مراجعة الوثائق التي تساعد على تحسين جودة الكود، باستخدام تقنيات تحليل الكود ومراجعة الوثائق how to use doc-reviewer doc-reviewer setup guide opentrack integration with doc-reviewer git status for code review gh pr view for pull request analysis udp protocol for posture data transmission doc-reviewer vs traditional code review tools installing doc-reviewer for AI agents doc-reviewer for camera-based head tracking doc-reviewer UDP数据发送 opentrack集成 代码review AI工具 开发效率 git status git diff Utilizes git status -s to detect uncommitted changes Supports checkout of PRs using gh pr checkout Analyzes differences with gh pr diff Performs detailed analysis of code changes Checks for accuracy and context completeness Integrates with opentrack via UDP for posture data transmission doc-reviewer is a camera-based head tracking application that sends posture data to opentrack via UDP, facilitating comprehensive document reviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('miura-188cm/ai-send-todo/create-nippo', 'community', 'miura-188cm', 'ai-send-todo', 'miura-188cm/ai-send-todo', 'create-nippo', 0, 0, 20, '2026-03-08T01:57:15.586Z', '2026-03-08T02:11:56.367Z', '25b4d5b55f5bc53462ef434819e8860e63062b4ce6a4d913f785b512aa97b792', '{"id":"miura-188cm/ai-send-todo/create-nippo","name":"create-nippo","description":{"en":"The create-nippo skill generates daily end reports for Slack by summarizing completed and pending tasks, as well as concerns. It benefits developers and teams by automating report generation.","zh":"create-nippo AI工具可以生成日报并发送到Slack，支持Markdown格式","ja":"create-nippo AIエージェントは日報を生成し、Slackに投稿することができます","ko":"create-nippo AI 에이전트는 일일 보고서를 생성하고 Slack에 전송할 수 있습니다","es":"Create-nippo es una herramienta de AI Agent que genera informes de fin de día para Slack, resumiendo tareas completadas, pendientes y preocupaciones","fr":"Create-nippo est un outil d''agent IA qui génère des rapports de fin de journée pour Slack, résumant les tâches terminées, en attente et les préoccupations","de":"Create-nippo ist ein AI-Tool, das tägliche Berichte für Slack erstellt, indem es abgeschlossene, offene Aufgaben und Bedenken zusammenfasst","pt":"O create-nippo é uma ferramenta que gera relatórios diários personalizados para sua equipe no Slack, utilizando a leitura de arquivos Markdown e envio de mensagens via Slack MCP.","ru":"Create-nippo - это инструмент, который создает индивидуальные дневные отчеты для вашей команды в Slack, используя чтение файлов Markdown и отправку сообщений через Slack MCP.","ar":"إن create-nippo هي أداة تُ动生成 تقارير يومية مخصصة لفريقك على Slack، من خلال قراءة ملفات Markdown و Sending رسائل عبر Slack MCP."},"seo":{"title":{"en":"create-nippo: Automated Daily Report Generation for AI Ag...","zh":"create-nippo AI工具：日报生成和Slack发送设置指南","ja":"create-nippo AIエージェント：日報生成とSlack投稿のベストプラクティス","ko":"create-nippo AI 에이전트: 일일 보고서 생성 및 Slack 전송 가이드","es":"Guía de configuración create-nippo para informes de Slack","fr":"Configurer create-nippo pour les rapports Slack","de":"Einrichten von create-nippo für Slack-Berichte","pt":"Guia de Configuração do create-nippo: Geração de Relatóri...","ru":"Настройка create-nippo: Создание Отчетов o Дневных Резуль...","ar":"دليل إعداد create-nippo: إنشاء تقارير يومية باستخدام الأد..."},"description":{"en":"Streamline your daily reporting with create-nippo. Learn how to automate your daily end reports and send them to Slack with ease. Get started now!","zh":"使用create-nippo AI工具生成和发送日报到Slack，自动化您的工作流程","ja":"create-nippo AIエージェントを使用して日報を生成し、Slackに投稿する方法","ko":"create-nippo AI 에이전트를 사용하여 일일 보고서를 생성하고 Slack에 전송하는 방법","es":"Aprende a generar informes de fin de día para Slack con create-nippo, una herramienta de AI Agent para resumir tareas y preocupaciones","fr":"Découvrez comment générer des rapports de fin de journée pour Slack avec create-nippo, un outil d''agent IA pour résumer les tâches et les préoccupations","de":"Erfahren Sie, wie Sie mit create-nippo, einem AI-Tool, tägliche Berichte für Slack erstellen und Aufgaben sowie Bedenken zusammenfassen","pt":"Aprenda a configurar o create-nippo para gerar relatórios diários personalizados para sua equipe no Slack, utilizando a ferramenta de AI ИИ Агенты","ru":"Узнайте, как настроить create-nippo для создания индивидуальных дневных отчетов для вашей команды в Slack, используя ИИ Агенты","ar":"تعرف على كيفية إعداد create-nippo لإنشاء تقارير يومية مخصصة لفريقك على Slack، باستخدام الأداة الإلكترونية لأدوات الذكاء الاصطناعي"},"definition":{"en":"create-nippo is a skill that automates the generation of daily end reports for Slack, summarizing tasks and concerns from TODO markdown files.","zh":"create-nippo AI工具是一种自动化日报生成和发送的工具","ja":"create-nippo AIエージェントは日報を自動生成し、Slackに投稿するAIツールです","ko":"create-nippo AI 에이전트는 일일 보고서를 자동 생성하고 Slack에 전송하는 AI 도구입니다","es":"Create-nippo es un agente de AI que automatiza la generación de informes de fin de día para Slack","fr":"Create-nippo est un agent IA qui automatisé la génération de rapports de fin de journée pour Slack","de":"Create-nippo ist ein AI-Agent, der die Erstellung von Tagesberichten für Slack automatisiert","pt":"O create-nippo é uma ferramenta de geração de relatórios diários que utiliza leitura de arquivos Markdown e envio de mensagens via Slack MCP.","ru":"Create-nippo - это инструмент для создания дневных отчетов, который использует чтение файлов Markdown и отправку сообщений через Slack MCP.","ar":"إن create-nippo هي أداة لإنشاء تقارير يومية تستخدم قراءة ملفات Markdown و Sending رسائل عبر Slack MCP."},"features":{"en":["Generates short Markdown reports for Slack","Summarizes completed and pending tasks from TODO markdown files","Includes current concerns in the report","Passes reports to the send-slack skill for approval and sending","Reads TODO markdown files from the TODO/YYYY/MM/DD/TODO.md path"],"zh":["支持Markdown格式","自动生成日报","发送日报到Slack","支持TODO列表","使用send-slack skill进行发送"],"ja":["Markdown形式をサポート","日報を自動生成","Slackに日報を投稿","TODOリストをサポート","send-slack skillを使用して送信"],"ko":["Markdown 형식을 지원","일일 보고서를 자동 생성","Slack에 일일 보고서를 전송","TODO 목록을 지원","send-slack 스킬을 사용하여 전송"],"es":["Generación automática de informes de fin de día para Slack","Resumen de tareas completadas, pendientes y preocupaciones","Integración con send-slack para enviar informes","Compatibilidad con Markdown para formato de informes","No envía informes automáticamente, requiere aprobación"],"fr":["Génération automatique de rapports de fin de journée pour Slack","Résumé des tâches terminées, en attente et des préoccupations","Intégration avec send-slack pour envoyer des rapports","Compatibilité avec Markdown pour le format des rapports","N''envoie pas les rapports automatiquement, nécessite une approbation"],"de":["Automatische Erstellung von Tagesberichten für Slack","Zusammenfassung von abgeschlossenen, offenen Aufgaben und Bedenken","Integration mit send-slack zum Versenden von Berichten","Kompatibilität mit Markdown für Berichtsformat","Sendet Berichte nicht automatisch, benötigt Zustimmung"],"pt":["Leitura de arquivos Markdown para gerar relatórios","Envio de mensagens personalizadas via Slack MCP","Geração de relatórios diários personalizados","Integração com a ferramenta de AI ИИ Агенты","Suporte a arquivos TODO.md","Compatibilidade com o protocolo Slack"],"ru":["Чтение файлов Markdown для создания отчетов","Отправка индивидуальных сообщений через Slack MCP","Создание индивидуальных дневных отчетов","Интеграция с ИИ Агентами","Поддержка файлов TODO.md","Совместимость с протоколом Slack"],"ar":["قراءة ملفات Markdown لإنشاء تقارير","إرسال رسائل مخصصة عبر Slack MCP","إنشاء تقارير يومية مخصصة","التكامل مع الأداة الإلكترونية لأدوات الذكاء الاصطناعي","دعم ملفات TODO.md","التوافق مع بروتوكول Slack"]},"keywords":{"en":["how to use create-nippo","create-nippo setup guide","automated daily report generation","create-nippo alternative","create-nippo vs slack reporting tools","create-nippo install","what is create-nippo","create-nippo for AI agents","slack reporting automation"],"zh":["create-nippo AI工具","日报生成","Slack发送","Markdown格式","TODO列表","send-slack skill","AI工具","自动化工作流程"],"ja":["create-nippo AIエージェント","日報生成","Slack投稿","Markdown形式","TODOリスト","send-slack skill","AIツール","自動化ワークフロー"],"ko":["create-nippo AI 에이전트","일일 보고서 생성","Slack 전송","Markdown 형식","TODO 목록","send-slack 스킬","AI 도구","자동화 작업 흐름"],"es":["create-nippo","agente de AI","informes de Slack","generación automática de informes","resumen de tareas","integración con send-slack","Markdown","automatización de informes"],"fr":["create-nippo","agent IA","rapports Slack","génération automatique de rapports","résumé de tâches","intégration avec send-slack","Markdown","automatisation de rapports"],"de":["create-nippo","AI-Agent","Slack-Berichte","automatische Erstellung von Berichten","Zusammenfassung von Aufgaben","Integration mit send-slack","Markdown","Automatisierung von Berichten"],"pt":["create-nippo","relatórios diários","Slack MCP","leitura de arquivos Markdown","envio de mensagens personalizadas","ferramenta de AI ИИ Агенты","geração de relatórios","integração com Slack","arquivos TODO.md"],"ru":["create-nippo","дневные отчеты","Slack MCP","чтение файлов Markdown","отправка индивидуальных сообщений","ИИ Агенты","создание отчетов","интеграция с Slack","файлы TODO.md"],"ar":["create-nippo","تقارير يومية","Slack MCP","قراءة ملفات Markdown","إرسال رسائل مخصصة","أدوات الذكاء الاصطناعي","إنشاء تقارير","التكامل مع Slack","ملفات TODO.md"]}},"owner":"miura-188cm","repo":"ai-send-todo","repoPath":"miura-188cm/ai-send-todo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.586Z","topics":[],"category":"community","skillMd":{"name":"create-nippo","description":"MarkdownのTODO/状況ファイルから終業時の報告文を作成する。作業サマリー、持ち越し、懸念事項をSlack送信前にまとめるときに使う。","bodyPreview":"# create-nippo\n\nSlack投稿向けの `daily_end` 報告文を生成する。\n\n## 手順\n\n1. 最新のTODO/状況Markdownを読む。\n2. 完了作業、未完了作業、懸念事項を要約する。\n3. Slack向けに短いMarkdown本文を作る。\n4. `send-slack` skill（Slack MCP）へ渡し、承認後に送信する。\n\n## 出力セクション\n\n- 今日やったこと\n- 未完了で明日に回すこと\n- 現在の懸念事項\n\n## 注意点\n\n- 自動送信しない。\n- 完了事実を推測で補完しない。\n- TODOパスは `TODO/YYYY/MM/DD/TODO.md` を基準に読む。","body":"# create-nippo\n\nSlack投稿向けの `daily_end` 報告文を生成する。\n\n## 手順\n\n1. 最新のTODO/状況Markdownを読む。\n2. 完了作業、未完了作業、懸念事項を要約する。\n3. Slack向けに短いMarkdown本文を作る。\n4. `send-slack` skill（Slack MCP）へ渡し、承認後に送信する。\n\n## 出力セクション\n\n- 今日やったこと\n- 未完了で明日に回すこと\n- 現在の懸念事項\n\n## 注意点\n\n- 自動送信しない。\n- 完了事実を推測で補完しない。\n- TODOパスは `TODO/YYYY/MM/DD/TODO.md` を基準に読む。\n"},"lastSynced":"2026-03-08T02:11:56.367Z","agentAnalysis":{"suitability":{"en":"Perfect for Task Management Agents needing automated daily report generation for Slack.","zh":"非常适合需要自动化每日报告生成用于Slack的任务管理代理。","ja":"Slackで自動的に毎日のレポートを生成する必要があるタスク管理エージェントに最適です。","ko":"Slack에 대한 자동화된 일일 보고서 생성이 필요한 태스크 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de gestión de tareas que necesitan generar informes diarios automatizados para Slack.","fr":"Parfait pour les agents de gestion de tâches nécessitant une génération de rapports quotidiens automatisés pour Slack.","de":"Perfekt für Task-Management-Agents, die eine automatisierte tägliche Berichterstellung für Slack benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Tarefas que precisam de geração automática de relatórios diários para o Slack.","ru":"Идеально подходит для агентов управления задачами, которым требуется автоматизированная ежедневная генерация отчетов для Slack.","ar":"مثالي لوكلاء إدارة المهام الذين يحتاجون إلى توليد تقارير يومية آلي للسلامة."},"recommendation":{"en":"Empowers agents to summarize completed and pending tasks, as well as concerns, using Markdown and send daily end reports to Slack via the send-slack skill, leveraging TODO/状況Markdown files and Slack MCP.","zh":"赋予代理人使用Markdown总结已完成和待处理任务以及问题，并通过send-slack技能将每日结束报告发送到Slack，利用TODO/状況Markdown文件和Slack MCP。","ja":"エージェントにMarkdownを使用して完了したタスクと保留中のタスク、および問題点を要約し、send-slackスキルを使用してSlackに毎日の終了レポートを送信することを可能にし、TODO/状況MarkdownファイルとSlack MCPを利用します。","ko":"에이전트가 Markdown를 사용하여 완료된 태스크와 보류 중인 태스크 및 문제를 요약하고 send-slack 스킬을 통해 Slack에 일일 종료 보고서를 보냄으로써, TODO/상황 Markdown 파일 및 Slack MCP를 활용합니다.","es":"Habilita a los agentes a resumir tareas completadas y pendientes, así como preocupaciones, utilizando Markdown y enviar informes diarios finales a Slack a través de la habilidad send-slack, aprovechando archivos Markdown TODO/状況 y Slack MCP.","fr":"Permet aux agents de résumer les tâches terminées et en attente, ainsi que les préoccupations, en utilisant Markdown et d''envoyer des rapports quotidiens finals à Slack via la compétence send-slack, en exploitant les fichiers Markdown TODO/状況 et Slack MCP.","de":"Ermöglicht es Agenten, abgeschlossene und ausstehende Aufgaben sowie Bedenken mit Markdown zusammenzufassen und tägliche Endberichte an Slack über die send-slack-Fähigkeit zu senden, indem sie TODO/状況-Markdown-Dateien und Slack MCP nutzen.","pt":"Habilita os agentes a resumir tarefas concluídas e pendentes, bem como preocupações, usando Markdown e enviar relatórios diários para o Slack por meio da habilidade send-slack, aproveitando arquivos Markdown TODO/状況 e Slack MCP.","ru":"Позволяет агентам суммировать выполненные и_pending задачи, а также проблемы, используя Markdown и отправлять ежедневные отчеты в Slack через навык send-slack, используя файлы TODO/状況Markdown и Slack MCP.","ar":"تمكّن الوكلاء من تلخيص المهام المكتملة والمعلقة، بالإضافة إلى القوالب، باستخدام Markdown وإرسال تقارير يومية إلى Slack من خلال مهارة send-slack، مستفيدة من ملفات TODO/状況 Markdown وSlack MCP."},"useCases":{"en":["Automating daily report generation for development teams","Summarizing task status for project managers","Generating concerns reports for stakeholders"],"zh":["为开发团队自动化每日报告生成","为项目经理总结任务状态","为利益相关者生成问题报告"],"ja":["開発チームの毎日のレポート生成を自動化する","プロジェクトマネージャーにタスクの状態を要約する","利害関係者に問題レポートを生成する"],"ko":["개발 팀을 위한 일일 보고서 생성 자동화","프로젝트 매니저를 위한 태스크 상태 요약","이해관계자를 위한 문제 보고서 생성"],"es":["Automatizar la generación de informes diarios para equipos de desarrollo","Resumir el estado de las tareas para gerentes de proyecto","Generar informes de preocupaciones para partes interesadas"],"fr":["Automatiser la génération de rapports quotidiens pour les équipes de développement","Résumer le statut des tâches pour les gestionnaires de projet","Générer des rapports de préoccupations pour les parties prenantes"],"de":["Automatisierung der täglichen Berichterstellung für Entwicklungsteams","Zusammenfassung des Aufgabenstatus für Projektmanager","Erstellung von Bedenkenberichten für Interessenten"],"pt":["Automatizar a geração de relatórios diários para equipes de desenvolvimento","Resumir o status das tarefas para gerentes de projeto","Gerar relatórios de preocupações para partes interessadas"],"ru":["Автоматизировать ежедневную генерацию отчетов для команд разработки","Суммировать статус задач для менеджеров проектов","Генерировать отчеты о проблемах для заинтересованных сторон"],"ar":["توفير توليد تقارير يومية آلي للفرق التطويرية","تلخيص حالة المهام لمديري المشاريع","توليد تقارير القوالب للأطراف المهتمة"]},"limitations":{"en":["Requires TODO/状況Markdown files in TODO/YYYY/MM/DD/TODO.md format","Does not support automatic sending without approval","Only compatible with Slack MCP for sending reports"],"zh":["需要TODO/状況Markdown文件在TODO/YYYY/MM/DD/TODO.md格式","不支持无审批的自动发送","仅与Slack MCP兼容以发送报告"],"ja":["TODO/YYYY/MM/DD/TODO.md形式のTODO/状況Markdownファイルが必要","承認なしでの自動送信はサポートされません","レポートを送信するためにSlack MCPのみと互換性がある"],"ko":["TODO/YYYY/MM/DD/TODO.md 형식의 TODO/상황 Markdown 파일이 필요","승인 없이 자동 전송은 지원되지 않음","보고서를 보내기 위해 Slack MCP와만 호환됨"],"es":["Requiere archivos Markdown TODO/状況 en formato TODO/YYYY/MM/DD/TODO.md","No admite el envío automático sin aprobación","Solo es compatible con Slack MCP para el envío de informes"],"fr":["Nécessite des fichiers Markdown TODO/状況 au format TODO/YYYY/MM/DD/TODO.md","Ne prend pas en charge l''envoi automatique sans approbation","N''est compatible qu''avec Slack MCP pour l''envoi de rapports"],"de":["Benötigt TODO/状況-Markdown-Dateien im Format TODO/YYYY/MM/DD/TODO.md","Unterstützt kein automatisches Senden ohne Zustimmung","Kompatibel nur mit Slack MCP zum Senden von Berichten"],"pt":["Requer arquivos Markdown TODO/状況 no formato TODO/YYYY/MM/DD/TODO.md","Não suporta envio automático sem aprovação","Somente compatível com Slack MCP para envio de relatórios"],"ru":["Требует файлов TODO/状況Markdown в формате TODO/YYYY/MM/DD/TODO.md","Не поддерживает автоматическую отправку без одобрения","Только совместимо со Slack MCP для отправки отчетов"],"ar":["يتطلب ملفات TODO/状況 Markdown بالتنسيق TODO/YYYY/MM/DD/TODO.md","لا يدعم الإرسال الآلي بدون موافقة","متوافق فقط مع Slack MCP لإرسال التقارير"]},"version":4},"contentHash":"25b4d5b55f5bc53462ef434819e8860e63062b4ce6a4d913f785b512aa97b792","qualityScore":20}');
