INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deadronos/deadronostask/performance-optimization', 'performance-optimization', 'deadronos', 'deadronostask', 'community', 'performance-optimization deadronos deadronostask community The performance-optimization skill helps developers make performance work repeatable and evidence-driven, targeting issues like FPS drops and slow load times. 性能优化技能帮助开发者优化应用程序的性能，包括定义症状、测量性能和优化代码 パフォーマンス最適化スキルは、開発者がアプリケーションのパフォーマンスを最適化するのに役立ちます。シンポムを定義し、パフォーマンスを測定し、コードを最適化します 성능 최적화 스킬은 개발자가 애플리케이션의 성능을 최적화하는 데 도움을 줍니다. 증상을 정의하고 성능을 측정하고 코드를 최적화합니다 Optimiza el rendimiento de tu proyecto con mediciones precisas y soluciones efectivas para problemas comunes como FPS drops y memoria creciente Optimisez les performances de votre projet avec des mesures précises et des solutions efficaces pour les problèmes courants tels que les baisses de FPS et la croissance de la mémoire Optimieren Sie die Leistung Ihres Projekts mit genauen Messungen und effektiven Lösungen für häufige Probleme wie FPS-Drops und Speicherwachstum Otimização de desempenho para desenvolvedores, com foco em reduzir tempos de carregamento e melhorar a experiência do usuário Производительность для разработчиков, с фокусом на снижении времени загрузки и улучшении пользовательского опыта تحسين الأداء للمطورين، مع التركيز على تقليل وقت التحميل وتحسين تجربة المستخدم how to use performance-optimization performance-optimization setup guide what is performance-optimization performance-optimization alternative performance-optimization vs web optimization optimize runtime performance improve load time performance performance-optimization install browser performance optimization 性能优化 AI代理工具 应用程序性能 FPS优化 负载时间优化 内存使用优化 浏览器性能工具 Defines symptoms and targets for performance optimization, such as FPS drops and slow first paint Measures performance before changing code using browser performance tools Captures reproduction of issues, including GPU/CPU pegged and memory growth Supports measurable targets, like steady 60 FPS and smaller JS bundles Optimizes load time by reducing large bundles and long shader compile times Performance-optimization is a technique to improve application performance by measuring and optimizing runtime, load time, and other key metrics.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kaenozu/Ult/system-architect', 'community', 'kaenozu', 'Ult', 'kaenozu/Ult', 'system-architect', 0, 0, 20, '2026-03-08T01:57:15.602Z', '2026-03-08T02:13:06.366Z', 'f0cf9bba1036c8a880026dbf313327596328916475f760f193f2718c91078f4c', '{"id":"kaenozu/Ult/system-architect","name":"system-architect","description":{"en":"The system-architect skill enables experts to build robust systems with mathematical integrity, testability, and high performance. It benefits developers seeking to create reliable and efficient systems.","zh":"系统架构师负责构建系统的‘脑’和‘骨骼’，确保数学的整合性、测试的可能性和执行的性能达到最高水平","ja":"システムアーキテクトは、システムの「脳」と「骨組み」を構築するエキスパートです。単なる機能実装にとどまらず、数学的整合性、テスト可能性、および実行パフォーマンスを最高水準で両立させます","ko":"시스템 아키텍트는 시스템의 ''뇌''와 ''골격''을 구축하는 전문가입니다. 단순한 기능 구현에만 머무르지 않고 수학적 일관성, 테스트 가능성 및 실행 성능을 최고 수준으로 유지합니다","es":"System Architect es un experto en diseño y desarrollo de sistemas, que combina análisis estáticos, TDD y procesamiento paralelo para crear sistemas escalables","fr":"System Architect est un expert en conception et développement de systèmes, qui combine l''analyse statique, le TDD et le traitement parallèle pour créer des systèmes évolutifs","de":"System Architect ist ein Experte für die Gestaltung und Entwicklung von Systemen, der statische Analyse, TDD und parallele Verarbeitung kombiniert, um skalierbare Systeme zu erstellen","pt":"O arquiteto de sistema é um especialista em construir a ''cerebro'' e ''esqueleto'' do sistema, garantindo a integridade matemática e a performance de execução","ru":"Системный архитектор - это эксперт, строящий ''мозг'' и ''скелет'' системы, гарантирующий математическую целостность и производительность исполнения","ar":"مهندس النظام هو خبير في بناء ''الدماغ'' و ''الهيكل'' للنظام، مما يضمن السلامة الرياضية وأداء التنفيذ"},"seo":{"title":{"en":"System-Architect: Comprehensive Setup Guide for AI Agents","zh":"系统架构师Setup Guide：包括静态分析和TDD","ja":"システムアーキテクトのベストプラクティス：包括的静的解析とTDD","ko":"시스템 아키텍트 설정 가이드: 정적 분석 및 TDD","es":"Guía de configuración para System Architect: Desarrollo d...","fr":"Guide de mise en place pour System Architect: Développeme...","de":"Einrichtungsleitfaden für System Architect: Entwicklung v...","pt":"Guia de Configuração de Arquiteto de Sistema: Práticas Re...","ru":"Настройка Системного Архитектора: Лучшие Практики","ar":"دليل تكوين مهندس النظام: أفضل الممارسات"},"description":{"en":"Unlock the full potential of system-architect with our expert guide. Learn how to implement inclusive static analysis, TDD, and intelligent ensemble integrat...","zh":"了解系统架构师的技术细节，包括静态分析、TDD、知能的アンサンブル統合等，AIエージェント开发最佳实践","ja":"システムアーキテクトの技術的側面を学び、包括的静的解析、TDD、知能のアンサンブル統合などをマスターしてください。AIエージェント開発のベストプラクティス","ko":"시스템 아키텍트의 기술적 측면을 배우고 정적 분석, TDD, 지능의 앙상블 통합 등에 대한 전문 지식을 얻으세요. AI 에이전트 개발의 최선의 방법","es":"Aprende a diseñar y desarrollar sistemas escalables con System Architect, incluyendo análisis estáticos, TDD y procesamiento paralelo","fr":"Découvrez comment concevoir et développer des systèmes évolutifs avec System Architect, y compris l''analyse statique, le TDD et le traitement parallèle","de":"Erfahren Sie, wie Sie mit System Architect skalierbare Systeme entwerfen und entwickeln, einschließlich statischer Analyse, TDD und parallelem Verarbeitung","pt":"Aprenda a configurar e otimizar seu sistema com o arquiteto de sistema, utilizando técnicas de análise estática e TDD","ru":"Узнайте, как настроить и оптимизировать свою систему с системным архитектором, используя статический анализ и TDD","ar":"تعلم كيفية تكوين ونظام وتحسين نظامك باستخدام مهندس النظام، باستخدام تقنيات التحليل الساكن و TDD"},"definition":{"en":"System-architect is a skill that expertise in constructing a system''s core architecture, ensuring harmony between functionality, mathematical consistency, and execution performance.","zh":"系统架构师是一种专家，负责构建系统的核心结构，确保系统的数学整合性、测试可能性和执行性能","ja":"システムアーキテクトは、システムの核心的な構造を構築するエキスパートです。数学的整合性、テスト可能性、および実行パフォーマンスを確保します","ko":"시스템 아키텍트는 시스템의 핵심 구조를 구축하는 전문가입니다. 수학적 일관성, 테스트 가능성 및 실행 성능을 보장합니다","es":"System Architect es un experto en diseño y desarrollo de sistemas que combina análisis estáticos, TDD y procesamiento paralelo","fr":"System Architect est un expert en conception et développement de systèmes qui combine l''analyse statique, le TDD et le traitement parallèle","de":"System Architect ist ein Experte für die Gestaltung und Entwicklung von Systemen, der statische Analyse, TDD und parallele Verarbeitung kombiniert","pt":"Arquiteto de sistema é um especialista que projeta e constrói a estrutura e a lógica do sistema","ru":"Системный архитектор - это эксперт, проектирующий и строящий структуру и логику системы","ar":"مهندس النظام هو خبير يصمم ويبني هيكل ومنطق النظام"},"features":{"en":["Performs inclusive static analysis to scan all source code and ensure dependency and type definition integrity","Implements Test-Driven Development (TDD) using jest or lightweight scripts for core logic validation","Integrates intelligent ensemble methods to combine multiple sources and adapt to market regimes","Utilizes Result types, such as MarketDataResult, to control errors through type definitions rather than exceptions","Enables parallel processing to optimize performance"],"zh":["包括静态分析","TDD（测试驱动开发）","知能的アンサンブル統合","并行处理"],"ja":["包括的静的解析","TDD（Test-Driven Development）","知能のアンサンブル統合","並列処理"],"ko":["정적 분석","TDD（테스트 주도 개발）","지능의 앙상블 통합","병렬 처리"],"es":["Análisis estático exhaustivo de código fuente","Desarrollo dirigidado por pruebas (TDD) con Jest","Integración de inteligencia artificial y aprendizaje automático","Procesamiento paralelo para mejorar el rendimiento","Control de errores mediante tipos de resultado (Result)"],"fr":["Analyse statique exhaustive du code source","Développement piloté par les tests (TDD) avec Jest","Intégration d''intelligence artificielle et d''apprentissage automatique","Traitement parallèle pour améliorer les performances","Contrôle des erreurs via des types de résultat (Result)"],"de":["Umfassende statische Analyse von Quellcode","Testgetriebene Entwicklung (TDD) mit Jest","Integration von künstlicher Intelligenz und maschinellem Lernen","Parallele Verarbeitung zur Leistungssteigerung","Fehlerkontrolle über Ergebnistypen (Result)"],"pt":["Análise estática completa do código-fonte","Implementação de TDD (Desenvolvimento Dirigido por Testes)","Integração de múltiplas fontes de dados (AI, técnica, correlação, oferta e demanda)","Otimização de performance com processamento paralelo"],"ru":["Полный статический анализ исходного кода","Реализация TDD (Тест-ориентированное развитие)","Интеграция множества источников данных (ИИ, техническая, корреляция, предложение и спрос)","Оптимизация производительности с параллельной обработкой"],"ar":["تحليل ساكن كامل للكود المصدري","تنفيذ TDD (التطوير الموجه بالاختبار)","دمج مصادر متعددة من البيانات (AI، تقنية، ارتباط، عرض وطلب)","تحسين الأداء مع المعالجة الموازية"]},"keywords":{"en":["how to use system-architect","system-architect setup guide","system-architect alternative","system-architect vs competitor","system-architect install","what is system-architect","system-architect tutorial","system-architect best practices","system-architect for AI agents","system-architect implementation"],"zh":["系统架构师","AIエージェント","静态分析","TDD","知能的アンサンブル統合","并行处理","系统开发"],"ja":["システムアーキテクト","AIエージェント","包括的静的解析","TDD","知能のアンサンブル統合","並列処理","システム開発"],"ko":["시스템 아키텍트","AI 에이전트","정적 분석","TDD","지능의 앙상블 통합","병렬 처리","시스템 개발"],"es":["System Architect","diseño de sistemas","desarrollo de sistemas","análisis estático","TDD","procesamiento paralelo","inteligencia artificial","aprendizaje automático","herramientas de desarrollo"],"fr":["System Architect","conception de systèmes","développement de systèmes","analyse statique","TDD","traitement parallèle","intelligence artificielle","apprentissage automatique","outils de développement"],"de":["System Architect","Systemgestaltung","Systementwicklung","statische Analyse","TDD","parallele Verarbeitung","künstliche Intelligenz","maschinelles Lernen","Entwicklungstools"],"pt":["arquiteto de sistema","análise estática","TDD","integração de dados","otimização de performance","desenvolvimento de software","engenharia de sistemas","AI","ferramentas de desenvolvimento"],"ru":["системный архитектор","статический анализ","TDD","интеграция данных","оптимизация производительности","разработка программного обеспечения","системная инженерия","ИИ","инструменты разработки"],"ar":["مهندس النظام","تحليل ساكن","TDD","دمج البيانات","تحسين الأداء","تطوير البرمجيات","هندسة النظم","AI","أدوات التطوير"]}},"owner":"kaenozu","repo":"Ult","repoPath":"kaenozu/Ult","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.602Z","topics":[],"category":"community","skillMd":{"name":"system-architect","description":"複雑なシステムの包括的レビュー、TDDに基づく堅牢なコアロジック構築、AIアンサンブルの統合、および高パフォーマンスな並列処理設計を専門とする建築家。大規模なリファクタリングや、信頼性が極めて重要な意思決定エンジンの構築に使用する。","bodyPreview":"# System Architect\n\nあなたは、システムの「脳」と「骨組み」を構築するエキスパートです。単なる機能実装にとどまらず、数学的整合性、テスト可能性、および実行パフォーマンスを最高水準で両立させます。\n\n## 核心的な行動原則\n\n1. **包括的静的解析**:\n   - 変更前に必ず全ソースコードをスキャンし、依存関係と型定義の整合性を把握せよ。\n   - `MarketDataResult` のような `Result` 型を導入し、例外ではなく型でエラーを制御せよ。\n\n2. **TDD (Test-Driven Development) の徹底**:\n   - コアロジック（計算、判定、重み付け）は、必ずテストコードを先に書け。\n   - `jest` または軽量なスクリプトによる整合性検証を行い、デグレードを物理的に防げ。\n\n3. **知能のアンサンブル統合**:\n   - 複数のソース（AI、テクニカル、相関、需給）を一本の糸で繋げ。\n   - 相場環境（Market Regime）を文脈として読み取り、動的にロジックの重みを変更せよ。\n\n4. **並列処理によるパフ","body":"# System Architect\n\nあなたは、システムの「脳」と「骨組み」を構築するエキスパートです。単なる機能実装にとどまらず、数学的整合性、テスト可能性、および実行パフォーマンスを最高水準で両立させます。\n\n## 核心的な行動原則\n\n1. **包括的静的解析**:\n   - 変更前に必ず全ソースコードをスキャンし、依存関係と型定義の整合性を把握せよ。\n   - `MarketDataResult` のような `Result` 型を導入し、例外ではなく型でエラーを制御せよ。\n\n2. **TDD (Test-Driven Development) の徹底**:\n   - コアロジック（計算、判定、重み付け）は、必ずテストコードを先に書け。\n   - `jest` または軽量なスクリプトによる整合性検証を行い、デグレードを物理的に防げ。\n\n3. **知能のアンサンブル統合**:\n   - 複数のソース（AI、テクニカル、相関、需給）を一本の糸で繋げ。\n   - 相場環境（Market Regime）を文脈として読み取り、動的にロジックの重みを変更せよ。\n\n4. **並列処理によるパフォーマンス確保**:\n   - 重い計算（推論、最適化）はメインスレッドから分離せよ。\n   - `Web Worker` を活用し、UIの滑らかさ(60fps)を犠牲にしない設計を行え。\n\n## ワークフロー\n\n### 1. 解析フェーズ\nプロジェクト内の全 `app/lib` または `src` を静的解析し、ビジネスロジックの欠損や冗長性を特定する。\n\n### 2. 堅牢化フェーズ (TDD)\n- **Red**: 境界値や異常系を含むテストケースを作成。\n- **Green**: ロジックを実装。\n- **Refactor**: 型の純粋性と計算の効率を高める。\n\n### 3. 統合フェーズ\nバラバラなモジュールを `UnifiedService` などのオーケストレーターで統合し、一貫性のある意思決定出力を生成する。\n\n### 4. 検証フェーズ\n`scripts/integrity-check.cjs` 等を用いて、環境に依存しないロジックの正当性を証明する。\n\n## 参照リソース\n- **TDDワークフロー**: [references/tdd-workflow.md](references/tdd-workflow.md)\n- **アンサンブル設計**: [references/ensemble-patterns.md](references/ensemble-patterns.md)\n- **並列処理設計**: [references/performance-optimization.md](references/performance-optimization.md)"},"lastSynced":"2026-03-08T02:13:06.366Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing robust system design with mathematical integrity and high performance capabilities.","zh":"非常适合需要强大系统设计、数学完整性和高性能能力的AI代理。","ja":"強力なシステム設計、数学的完全性、および高性能能力が必要なAIエージェントに最適です。","ko":"강력한 시스템 디자인, 수학적 완전성 및 고성능 능력이 필요한 AI 에이전트에게 최적입니다.","es":"Perfecto para agentes de IA que necesitan un diseño de sistema robusto con integridad matemática y capacidades de alto rendimiento.","fr":"Parfait pour les agents IA nécessitant une conception de système robuste avec intégrité mathématique et des capacités de haute performance.","de":"Perfekt für KI-Agents, die ein robustes Systemdesign mit mathematischer Integrität und Hochleistungs-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de IA que necessitam de design de sistema robusto com integridade matemática e capacidades de alto desempenho.","ru":"Идеально подходит для агентов ИИ, которым требуется прочная система проектирования с математической целостностью и возможностями высокого уровня производительности.","ar":"مثالي لموكلات الذكاء الاصطناعي التي تحتاج إلى تصميم نظام قوي مع سلامة رياضية وخصائص أداء عالية"},"recommendation":{"en":"Empowers agents to build reliable systems with comprehensive static analysis, test-driven development using jest, and ensemble integration of multiple sources like AI, technical, and market data, ensuring dynamic logic adjustments based on market regimes.","zh":"赋予代理构建可靠系统的能力，通过使用jest的全面静态分析、测试驱动开发以及AI、技术和市场数据等多个来源的集成，确保根据市场状况进行动态逻辑调整。","ja":"エージェントが信頼性の高いシステムを構築できるようにすることで、jestを使用した包括的な静的分析、テスト駆動開発、およびAI、技術、市場データなどの複数のソースのアンサンブル統合を実現し、市場状況に基づいて動的なロジック調整を可能にします。","ko":"에이전트가 신뢰할 수 있는 시스템을 구축할 수 있도록 하여 jest를 사용한 포괄적인 정적 분석, 테스트 주도 개발 및 AI, 기술, 시장 데이터 등 여러 소스의 앙상블 통합을 통해 시장 상황에 따라 동적 로직 조정을 보장합니다.","es":"Permite a los agentes crear sistemas confiables con un análisis estático integral, desarrollo dirigido por pruebas utilizando jest y una integración de conjunto de múltiples fuentes como datos de IA, técnicos y de mercado, garantizando ajustes lógicos dinámicos basados en regímenes de mercado.","fr":"Permet aux agents de créer des systèmes fiables avec une analyse statique complète, un développement piloté par des tests utilisant jest et une intégration de plusieurs sources telles que des données d''IA, techniques et de marché, garantissant des ajustements logiques dynamiques basés sur les régimes de marché.","de":"Ermöglicht es Agents, zuverlässige Systeme mit umfassender statischer Analyse, testgetriebenem Entwicklung unter Verwendung von jest und Ensemble-Integration mehrerer Quellen wie KI-, technischen und Marktdaten zu erstellen, wodurch dynamische Logik-Anpassungen basierend auf Markregimen sichergestellt werden.","pt":"Habilita os agentes a construir sistemas confiáveis com análise estática abrangente, desenvolvimento orientado a testes usando jest, e integração de ensemble de múltiplas fontes como IA, dados técnicos e de mercado, garantindo ajustes lógicos dinâmicos com base em regimes de mercado.","ru":"Позволяет агентам создавать надежные системы с комплексным статическим анализом, разработкой, управляемой тестированием, с использованием jest, и ансамблевой интеграцией нескольких источников, таких как ИИ, технические и рыночные данные, обеспечивающей динамические логические корректировки на основе рыночных режимов.","ar":"تمكن الوكلاء من بناء أنظمة موثوقة مع تحليل静ي شامل، وتطوير مدفوع بالاختبار باستخدام jest، وتكامل مجموعة من مصادر متعددة مثل الذكاء الاصطناعي والبيانات الفنية والسوقية، مما يضمن التعديلات المنطقية الديناميكية على أساس أنظمة السوق"},"useCases":{"en":["Designing scalable systems with mathematical integrity","Implementing test-driven development for core logic","Integrating multiple data sources for dynamic system adjustments"],"zh":["设计具有数学完整性的可扩展系统","实现核心逻辑的测试驱动开发","集成多个数据源以进行动态系统调整"],"ja":["数学的完全性を持つスケーラブルなシステムを設計する","コアロジックのテスト駆動開発を実装する","複数のデータソースを統合して動的なシステム調整を行う"],"ko":["수학적 완전성을 갖춘 확장 가능한 시스템을 설계한다","핵심 로직에 대한 테스트 주도 개발을 구현한다","여러 데이터 소스를 통합하여 동적 시스템 조정을 수행한다"],"es":["Diseñar sistemas escalables con integridad matemática","Implementar desarrollo dirigido por pruebas para la lógica principal","Integrar múltiples fuentes de datos para ajustes de sistema dinámicos"],"fr":["Concevoir des systèmes évolutifs avec intégrité mathématique","Mettre en œuvre un développement piloté par des tests pour la logique principale","Intégrer plusieurs sources de données pour des ajustements de système dynamiques"],"de":["Entwerfen von skalierbaren Systemen mit mathematischer Integrität","Implementieren von testgetriebenem Entwicklung für die Kernlogik","Integrieren mehrerer Datenquellen für dynamische Systemanpassungen"],"pt":["Projeto de sistemas escaláveis com integridade matemática","Implementação de desenvolvimento orientado a testes para lógica central","Integração de várias fontes de dados para ajustes de sistema dinâmicos"],"ru":["Проектирование масштабируемых систем с математической целостностью","Реализация разработки, управляемой тестированием, для центральной логики","Интеграция нескольких источников данных для динамических корректировок системы"],"ar":["تصميم أنظمة قابلة للتوسيع مع سلامة رياضية","تنفيذ تطوير مدفوع بالاختبار للمنطق الأساسي","تكامل مصادر بيانات متعددة لتعديلات نظام ديناميكية"]},"limitations":{"en":["Requires comprehensive understanding of system architecture principles","Dependent on high-quality test data for effective TDD","May require additional resources for complex ensemble integrations"],"zh":["需要对系统架构原则有全面了解","依赖于高质量的测试数据以实现有效的TDD","可能需要额外资源以进行复杂的集成"],"ja":["システムアーキテクチャの原則について包括的な理解が必要","効果的なTDDを実現するために、高品質のテストデータに依存する","複雑なアンサンブル統合を実行するために、追加のリソースが必要になる場合がある"],"ko":["시스템 아키텍처 원리에 대한 포괄적인 이해가 필요하다","有效한 TDD를 구현하기 위해 고품질의 테스트 데이터에 의존한다","복잡한 앙상블 통합을 수행하기 위해 추가 리소스가 필요할 수 있다"],"es":["Requiere una comprensión integral de los principios de arquitectura de sistema","Depende de datos de prueba de alta calidad para un TDD eficaz","Puede requerir recursos adicionales para integraciones de conjunto complejas"],"fr":["Nécessite une compréhension complète des principes d''architecture de système","Dépend de données de test de haute qualité pour un TDD efficace","Peut nécessiter des ressources supplémentaires pour des intégrations de plusieurs sources complexes"],"de":["Erfordert ein umfassendes Verständnis der Systemarchitektur-Prinzipien","Hängt von hochwertigen Testdaten für ein effektives TDD ab","Kann zusätzliche Ressourcen für komplexe Ensemble-Integrationen erfordern"],"pt":["Exige compreensão abrangente dos princípios de arquitetura de sistema","Depende de dados de teste de alta qualidade para TDD eficaz","Pode exigir recursos adicionais para integrações de ensemble complexas"],"ru":["Требует всестороннего понимания принципов системы архитектуры","Зависит от высококачественных тестовых данных для эффективного TDD","Может требовать дополнительных ресурсов для сложных ансамблевых интеграций"],"ar":["يتطلب فهمًا شاملاً لمبادئ هندسة النظام","يعتمد على بيانات اختبار عالية الجودة للتطوير القائم على الاختبار الفعال","قد يتطلب موارد إضافية لعمليات التكامل المعقدة"]},"version":4},"contentHash":"f0cf9bba1036c8a880026dbf313327596328916475f760f193f2718c91078f4c","qualityScore":20}');
