INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kaenozu/Ult/system-architect', 'system-architect', 'kaenozu', 'Ult', 'community', 'system-architect kaenozu Ult community The system-architect skill enables experts to build robust systems with mathematical integrity, testability, and high performance. It benefits developers seeking to create reliable and efficient systems. 系统架构师负责构建系统的‘脑’和‘骨骼’，确保数学的整合性、测试的可能性和执行的性能达到最高水平 システムアーキテクトは、システムの「脳」と「骨組み」を構築するエキスパートです。単なる機能実装にとどまらず、数学的整合性、テスト可能性、および実行パフォーマンスを最高水準で両立させます 시스템 아키텍트는 시스템의 ''뇌''와 ''골격''을 구축하는 전문가입니다. 단순한 기능 구현에만 머무르지 않고 수학적 일관성, 테스트 가능성 및 실행 성능을 최고 수준으로 유지합니다 System Architect es un experto en diseño y desarrollo de sistemas, que combina análisis estáticos, TDD y procesamiento paralelo para crear sistemas escalables System Architect est un expert en conception et développement de systèmes, qui combine l''analyse statique, le TDD et le traitement parallèle pour créer des systèmes évolutifs System Architect ist ein Experte für die Gestaltung und Entwicklung von Systemen, der statische Analyse, TDD und parallele Verarbeitung kombiniert, um skalierbare Systeme zu erstellen O arquiteto de sistema é um especialista em construir a ''cerebro'' e ''esqueleto'' do sistema, garantindo a integridade matemática e a performance de execução Системный архитектор - это эксперт, строящий ''мозг'' и ''скелет'' системы, гарантирующий математическую целостность и производительность исполнения مهندس النظام هو خبير في بناء ''الدماغ'' و ''الهيكل'' للنظام، مما يضمن السلامة الرياضية وأداء التنفيذ how to use system-architect system-architect setup guide system-architect alternative system-architect vs competitor system-architect install what is system-architect system-architect tutorial system-architect best practices system-architect for AI agents system-architect implementation 系统架构师 AIエージェント 静态分析 TDD 知能的アンサンブル統合 并行处理 系统开发 Performs inclusive static analysis to scan all source code and ensure dependency and type definition integrity Implements Test-Driven Development (TDD) using jest or lightweight scripts for core logic validation Integrates intelligent ensemble methods to combine multiple sources and adapt to market regimes Utilizes Result types, such as MarketDataResult, to control errors through type definitions rather than exceptions Enables parallel processing to optimize performance System-architect is a skill that expertise in constructing a system''s core architecture, ensuring harmony between functionality, mathematical consistency, and execution performance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EEMO22/project-mall/library-update-policy', 'community', 'EEMO22', 'project-mall', 'EEMO22/project-mall', 'library-update-policy', 0, 0, 20, '2026-03-08T01:57:15.624Z', '2026-03-08T02:13:31.624Z', 'd3705679d3e183bbfb7fd38ff4f00f24bd00e23f8b6b45bcbb6b709dd2ea7b2b', '{"id":"EEMO22/project-mall/library-update-policy","name":"library-update-policy","description":{"en":"The library-update-policy skill helps AI agents manage library updates by detecting exact versions and reproducing issues before changing code, benefiting developer teams working with complex dependencies.","zh":"库更新策略是一种确保代码更新的方法，通过检测确切版本和重现问题来实现高效的更新","ja":"ライブラリ更新ポリシーは、コードの更新を効率化するための方法で、正確なバージョン検出と問題の再現が含まれます","ko":"라이브러리 업데이트 정책은 코드를 효율적으로 업데이트하는 방법으로, 정확한 버전 탐지와 문제 재현을 제공합니다","es":"La política de actualización de bibliotecas es una guía para detectar versiones exactas y reproducir problemas antes de cambiar el código, preferir soluciones locales y capturar notas de actualización resueltas","fr":"La politique de mise à jour de bibliothèques est un guide pour détecter les versions exactes et reproduire les problèmes avant de modifier le code, préférer les solutions locales et capturer les notes de mise à jour résolues","de":"Die Bibliotheks-Update-Richtlinie ist ein Leitfaden zur Erkennung exakter Versionen und Reproduktion von Problemen vor Codeänderungen, lokalen Lösungen zu bevorzugen und gelöste Update-Hinweise zu erfassen","pt":"A política de atualização de bibliotecas visa detectar a versão exata e reproduzir o problema antes de alterar o código, priorizando soluções locais e capturando notas de atualização.","ru":"Политика обновления библиотек направлена на обнаружение точной версии и воспроизведение проблемы перед изменением кода, отдавая предпочтение локальным решениям.","ar":"تهدف سياسة تحديث المكتبات إلى تحديد الإصدار الدقيق واعادة إنتاج المشكلة قبل التعديل على الكود، مع التركيز على الحلول المحلية وتسجيل ملاحظات التحديث"},"seo":{"title":{"en":"library-update-policy: Best Practices for AI Agents | AI ...","zh":"库更新策略设置指南 - 实现精确版本检测和升级","ja":"ライブラリ更新ポリシーのベストプラクティス - AIエージェントを活用","ko":"라이브러리 업데이트 정책 가이드 - 정확한 버전 탐지 및 복제","es":"Herramientas de AI: Guía de Configuración de Política de ...","fr":"Outils d''IA: Guide de Configuration de la Politique de Mi...","de":"AI-Tools: Setup-Leitfaden für Bibliotheks-Update-Richtlinien","pt":"Política de Atualização de Bibliotecas: Melhores Práticas...","ru":"Политика обновления библиотек ИИ Агентов: Руководство по ...","ar":"سياسة تحديث المكتبات: إرشادات للتعامل مع تحديثات المكتبات"},"description":{"en":"Discover how library-update-policy helps AI agents detect exact versions, reproduce issues, and confirm behavior before changing code. Learn how to set it up...","zh":"了解库更新策略的技术细节，包括版本检测、项目本地修复和文档确认","ja":"ライブラリ更新ポリシーの詳細を学び、AIエージェントを活用して効率を向上させる","ko":"라이브러리 업데이트 정책의 기술적인 요점을 살펴보세요. 버전 탐지, 프로젝트 로컬 수정 및 문서 확인 등","es":"Aprende a implementar la política de actualización de bibliotecas para detectar versiones exactas y reproducir problemas antes de cambiar el código","fr":"Découvrez comment mettre en œuvre la politique de mise à jour de bibliothèques pour détecter les versions exactes et reproduire les problèmes avant de modifi...","de":"Erfahren Sie, wie Sie die Bibliotheks-Update-Richtlinie implementieren, um exakte Versionen zu erkennen und Probleme vor Codeänderungen zu reproduzieren","pt":"Aprenda a lidar com atualizações de bibliotecas de forma eficaz, detectando versões exatas e reproduzindo problemas antes de alterar o código.","ru":"Изучите лучшие практики обновления библиотек ИИ Агентов, включая обнаружение точных версий и воспроизведение проблем.","ar":"تعرف على كيفية التعامل مع تحديثات المكتبات بطريقة فعالة، من خلال تحديد الإصدارات الدقيقة واعادة إنتاج المشاكل قبل التعديل على الكود"},"definition":{"en":"library-update-policy is a set of guidelines for managing library updates, emphasizing project-local fixes, user confirmation, and concise documentation.","zh":"库更新策略是指在更新代码库时遵循的一套规则，包括版本检测和问题重现","ja":"ライブラリ更新ポリシーとは、コードライブラリの更新時に従うルールの集合で、バージョン検出と問題の再現が含まれます","ko":"라이브러리 업데이트 정책이란 코드 라이브러리를 업데이트할 때 따르는 규칙의 집합으로, 버전 탐지와 문제 재현을 포함합니다","es":"La política de actualización de bibliotecas es un conjunto de reglas para gestionar actualizaciones de bibliotecas de forma eficiente","fr":"La politique de mise à jour de bibliothèques est un ensemble de règles pour gérer les mises à jour de bibliothèques de manière efficace","de":"Die Bibliotheks-Update-Richtlinie ist ein Satz von Regeln zur effizienten Verwaltung von Bibliotheks-Updates","pt":"A política de atualização de bibliotecas é um conjunto de diretrizes para gerenciar atualizações de bibliotecas de forma eficaz.","ru":"Политика обновления библиотек - это набор руководств для эффективного управления обновлениями библиотек ИИ Агентов.","ar":"سياسة تحديث المكتبات هي مجموعة من الإرشادات للتعامل مع تحديثات المكتبات بطريقة فعالة"},"features":{"en":["Detects exact version and reproduces the issue before changing code","Prefers project-local fixes before broad refactors","Asks user to confirm behavior when documentation and runtime differ","Treats user-provided documentation links and usage guidance as a source of truth","Captures resolved upgrade notes in concise repository documentation"],"zh":["检测确切版本以确保更新的准确性","项目本地修复以减少对整个代码库的影响","文档确认以确保更新的正确性","捕获升级说明以方便后续更新","用户提供的文档链接和使用指南作为真实来源"],"ja":["正確なバージョン検出による更新の精度向上","プロジェクトローカル修正によるコード全体への影響の最小化","ドキュメントの確認による更新の正確性の確保","アップグレードノートのキャプチャによる後続の更新の効率化","ユーザー提供のドキュメントリンクと使用ガイドラインによる真実性の確保"],"ko":["정확한 버전 탐지로 업데이트의 정확성을 보장","프로젝트 로컬 수정으로 코드 전체에 대한 영향을 최소화","문서 확인으로 업데이트의 정확성을 보장","업그레이드 노트의 캡처로 이후 업데이트의 효율성을 향상","사용자 제공 문서 링크와 사용 지침을 통해 真実性를 보장"],"es":["Detección de versiones exactas","Reproducción de problemas antes de cambiar el código","Preferencia de soluciones locales","Captura de notas de actualización resueltas","Confirmación de comportamiento con documentos y tiempo de ejecución","Uso de enlaces de documentos y orientación de uso proporcionados por el usuario como fuente de verdad"],"fr":["Détection de versions exactes","Reproduction de problèmes avant de modifier le code","Préférence de solutions locales","Capture de notes de mise à jour résolues","Confirmation de comportement avec des documents et du temps d''exécution","Utilisation de liens de documents et d''orientation d''utilisation fournis par l''utilisateur comme source de vérité"],"de":["Erkennung exakter Versionen","Reproduktion von Problemen vor Codeänderungen","Bevorzugung lokaler Lösungen","Erfassung gelöster Update-Hinweise","Bestätigung des Verhaltens mit Dokumenten und Laufzeit","Verwendung von Dokumenten-Links und Benutzungsanleitungen als Quelle der Wahrheit"],"pt":["Detecção da versão exata para reproduzir problemas","Priorização de soluções locais antes de refatorar o código","Confirmação do comportamento com o usuário quando a documentação e o tempo de execução diferem","Tratamento de links de documentação e orientação de uso fornecidos pelo usuário como fonte de verdade","Captação de notas de atualização resolvidas em documentos concisos do repositório"],"ru":["Обнаружение точной версии для воспроизведения проблем","Отдание предпочтения локальным решениям перед refactorингом кода","Подтверждение поведения с пользователем при различии документации и времени выполнения","Рассмотрение ссылок на документацию и рекомендаций по использованию, предоставленных пользователем, как источника истины","Захват решенных заметок об обновлении в краткой документации репозитория"],"ar":["تحديد الإصدار الدقيق لاعادة إنتاج المشاكل","الأولوية للحلول المحلية قبل إعادة هيكلة الكود","التأكد من السلوك مع المستخدم عند اختلاف الوثائق والزمن التنفيذي","معالجة روابط الوثائق وإرشادات الاستخدام المقدمة من قبل المستخدم كمرجع حقيقي","تسجيل ملاحظات التحديث المحلولة في وثائق المستودع الموجزة"]},"keywords":{"en":["how to use library-update-policy","library-update-policy setup guide","library-update-policy best practices","library-update-policy alternative","library-update-policy vs dependency management tools","what is library-update-policy","library-update-policy install","library-update-policy for AI agents"],"zh":["库更新策略","AI工具","代码更新","版本检测","项目本地修复","文档确认","升级说明","代码库管理"],"ja":["ライブラリ更新ポリシー","AIエージェント","コード更新","バージョン検出","プロジェクトローカル修正","ドキュメントの確認","アップグレードノート","コードライブラリ管理"],"ko":["라이브러리 업데이트 정책","AI 에이전트","코드 업데이트","버전 탐지","프로젝트 로컬 수정","문서 확인","업그레이드 노트","코드 라이브러리 관리"],"es":["política de actualización de bibliotecas","herramientas de AI","gestión de bibliotecas","actualización de bibliotecas","detección de versiones","reproducción de problemas","soluciones locales","captura de notas de actualización"],"fr":["politique de mise à jour de bibliothèques","outils d''IA","gestion de bibliothèques","mise à jour de bibliothèques","détection de versions","reproduction de problèmes","solutions locales","capture de notes de mise à jour"],"de":["Bibliotheks-Update-Richtlinie","AI-Tools","Bibliotheksverwaltung","Bibliotheks-Update","Versionserkennung","Problemreproduktion","lokale Lösungen","Erfassung von Update-Hinweisen"],"pt":["política de atualização de bibliotecas","gerenciamento de bibliotecas","desenvolvimento de software","atualização de bibliotecas","bibliotecas de código","desenvolvedores de software","melhores práticas de desenvolvimento"],"ru":["политика обновления библиотек","управление библиотеками","разработка программного обеспечения","обновление библиотек","библиотеки кода","разработчики программного обеспечения","лучшие практики разработки"],"ar":["سياسة تحديث المكتبات","إدارة المكتبات","تطوير البرمجيات","تحديث المكتبات","مكتبات الشفرة","مطورو البرمجيات","أفضل الممارسات للتطوير"]}},"owner":"EEMO22","repo":"project-mall","repoPath":"EEMO22/project-mall","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.624Z","topics":[],"category":"community","skillMd":{"name":"library-update-policy","description":"Handle library updates and breaking changes with user-confirmed behavior and project-safe migration notes. Use when dependencies fail, APIs change, or syntax differs from expected docs.","bodyPreview":"# Library Update Policy\n\n- Detect the exact version and reproduce the issue before changing code.\n- Prefer project-local fixes before broad refactors.\n- Ask user to confirm behavior when docs and runtime differ.\n- Treat user-provided doc links and usage guidance as source of truth.\n- Capture resolved upgrade notes in concise repository docs.","body":"# Library Update Policy\n\n- Detect the exact version and reproduce the issue before changing code.\n- Prefer project-local fixes before broad refactors.\n- Ask user to confirm behavior when docs and runtime differ.\n- Treat user-provided doc links and usage guidance as source of truth.\n- Capture resolved upgrade notes in concise repository docs.\n"},"lastSynced":"2026-03-08T02:13:31.624Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Maintenance Agents requiring precise library version management and conflict resolution.","zh":"适用于需要精确库版本管理和冲突解决的代码维护代理。","ja":"コードメンテナンスエージェントが正確なライブラリバージョン管理とコンフリクト解決を必要とする場合に最適です。","ko":"정확한 라이브러리 버전 관리와 충돌 해결이 필요한 코드 유지 보수 에이전트에 적합합니다.","es":"Ideal para Agentes de Mantenimiento de Código que requieren un manejo preciso de versiones de bibliotecas y resolución de conflictos.","fr":"Idéal pour les Agents de Maintenance de Code nécessitant une gestion précise des versions de bibliothèques et une résolution de conflits.","de":"Ideal für Code-Wartungs-Agents, die eine präzise Bibliotheksversionsverwaltung und Konfliktlösung erfordern.","pt":"Ideal para Agentes de Manutenção de Código que requerem gerenciamento preciso de versão de bibliotecas e resolução de conflitos.","ru":"Идеально подходит для агентов по обслуживанию кода, требующих точного управления версиями библиотек и разрешения конфликтов.","ar":"مثالي لوكلاء صيانة الشفرة الذين يحتاجون إلى إدارة دقيقة لإصدارات المكتبات وحل النزاعات."},"recommendation":{"en":"Empowers agents to detect exact library versions, reproduce issues before code changes, and prefer project-local fixes, ensuring seamless dependency management and reducing potential errors through confirmations and concise documentation updates.","zh":"赋予代理检测确切的库版本、在代码更改前复现问题、并更喜欢项目本地的修复方法，确保无缝的依赖管理，并通过确认和简洁的文档更新减少潜在错误。","ja":"エージェントが正確なライブラリバージョンを検出してコード変更前に問題を再現し、プロジェクトローカルの修正を優先することで、シームレスな依存関係管理を実現し、確認と簡潔なドキュメント更新を通じて潜在的なエラーを減らします。","ko":"에이전트가 정확한 라이브러리 버전을 감지하고 코드 변경 전에 문제를 재현하고 프로젝트 로컬 수정을 우선하여 무결점 의존성 관리를 보장하고 확인 및 간결한 문서 업데이트를 통해 잠재적인 오류를 줄입니다.","es":"Habilita a los agentes para detectar versiones exactas de bibliotecas, reproducir problemas antes de los cambios de código y preferir soluciones locales de proyecto, garantizando una gestión de dependencias sin problemas y reduciendo los errores potenciales a través de confirmaciones y actualizaciones de documentación concisas.","fr":"Permet aux agents de détecter les versions exactes de bibliothèques, de reproduire les problèmes avant les changements de code et de préférer les corrections locales de projet, assurant ainsi une gestion de dépendances sans problème et réduisant les erreurs potentielles grâce à des confirmations et des mises à jour de documentation concises.","de":"Ermächtigt die Agents, um exakte Bibliotheksversionen zu erkennen, Probleme vor Codeänderungen zu reproduzieren und projektlokale Lösungen zu bevorzugen, um eine nahtlose Abhängigkeitsverwaltung zu gewährleisten und potenzielle Fehler durch Bestätigungen und präzise Dokumentationsaktualisierungen zu reduzieren.","pt":"Habilita os agentes a detectar versões exatas de bibliotecas, reproduzir problemas antes de alterações de código e preferir soluções locais de projeto, garantindo gerenciamento de dependências sem interrupções e reduzindo erros potenciais por meio de confirmações e atualizações de documentação concisas.","ru":"Наделяет агентов возможностью обнаруживать точные версии библиотек, воспроизводить проблемы до внесения изменений в код, и отдавать предпочтение исправлениям на уровне проекта, обеспечивая бесперебойное управление зависимостями и снижая потенциальные ошибки посредством подтверждений и кратких обновлений документации.","ar":"تمكّن الوكلاء من كشف إصدارات المكتبات بدقة، واعادة إنتاج المشكلات قبل تغييرات الشفرة، والتفضيل للحلول المحلية للمشروع، مما يضمن إدارة التبعيات بدون انقطاع وتقليل الأخطاء المحتملة من خلال التأكيدات وتحديثات الوثائق الموجزة."},"useCases":{"en":["Detecting and resolving library version conflicts","Reproducing issues before applying code changes","Documenting resolved upgrade notes for future reference"],"zh":["检测和解决库版本冲突","在应用代码更改前复现问题","为将来参考记录解决的升级说明"],"ja":["ライブラリバージョンのコンフリクトを検出して解決する","コード変更を適用する前に問題を再現する","解決したアップグレードのノートを将来の参考のために文書化する"],"ko":["라이브러리 버전 충돌을 감지하고 해결한다","코드 변경을 적용하기 전에 문제를 재현한다","해결된 업그레이드 노트를 미래 참조를 위해 문서화한다"],"es":["Detección y resolución de conflictos de versiones de bibliotecas","Reproducción de problemas antes de aplicar cambios de código","Documentación de notas de actualización resueltas para referencia futura"],"fr":["Détection et résolution de conflits de versions de bibliothèques","Reproduction de problèmes avant d''appliquer des changements de code","Documentation des notes de mise à jour résolues pour référence future"],"de":["Erkennung und Lösung von Bibliotheksversionskonflikten","Reproduktion von Problemen vor Codeänderungen","Dokumentation der gelösten Upgrade-Notizen für zukünftige Referenz"],"pt":["Detecção e resolução de conflitos de versão de bibliotecas","Reprodução de problemas antes da aplicação de alterações de código","Documentação de notas de atualização resolvidas para referência futura"],"ru":["Обнаружение и разрешение конфликтов версий библиотек","Воспроизведение проблем до внесения изменений в код","Документирование заметок об обновлении для будущей справки"],"ar":["كشف وحل نزاعات إصدارات المكتبات","إعادة إنتاج المشكلات قبل تطبيق تغييرات الشفرة","توثيق ملاحظات التحديثات المحلولة لمستقبل المرجع"]},"limitations":{"en":["Requires access to project documentation and runtime environment","Dependent on user-provided documentation links and usage guidance"],"zh":["需要访问项目文档和运行环境","依赖于用户提供的文档链接和使用指南"],"ja":["プロジェクトドキュメントと実行環境へのアクセスが必要","ユーザー提供のドキュメントリンクと使用ガイダンスに依存する"],"ko":["프로젝트 문서와 런타임 환경에 대한 액세스가 필요함","사용자 제공 문서 링크 및 사용 지침에 의존함"],"es":["Requiere acceso a la documentación del proyecto y al entorno de ejecución","Dependiente de los enlaces de documentación y la guía de uso proporcionados por el usuario"],"fr":["Nécessite un accès à la documentation du projet et à l''environnement d''exécution","Dépend des liens de documentation et des conseils d''utilisation fournis par l''utilisateur"],"de":["Erfordert Zugriff auf die Projektdokumentation und die Laufzeitumgebung","Abhängig von den vom Benutzer bereitgestellten Dokumentationslinks und Nutzungsanleitungen"],"pt":["Requer acesso à documentação do projeto e ambiente de tempo de execução","Dependente de links de documentação e orientação de uso fornecidos pelo usuário"],"ru":["Требует доступа к документации проекта и среды выполнения","Зависит от ссылок на документацию и руководства по использованию, предоставляемых пользователем"],"ar":["يتطلب الوصول إلى توثيق المشروع وبيئة وقت التشغيل","يعتمد على روابط التوثيق وإرشادات الاستخدام المقدمة من قبل المستخدم"]},"version":4},"contentHash":"d3705679d3e183bbfb7fd38ff4f00f24bd00e23f8b6b45bcbb6b709dd2ea7b2b","qualityScore":20}');
