INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EEMO22/project-mall/library-update-policy', 'library-update-policy', 'EEMO22', 'project-mall', 'community', 'library-update-policy EEMO22 project-mall community The library-update-policy skill helps AI agents manage library updates by detecting exact versions and reproducing issues before changing code, benefiting developer teams working with complex dependencies. 库更新策略是一种确保代码更新的方法，通过检测确切版本和重现问题来实现高效的更新 ライブラリ更新ポリシーは、コードの更新を効率化するための方法で、正確なバージョン検出と問題の再現が含まれます 라이브러리 업데이트 정책은 코드를 효율적으로 업데이트하는 방법으로, 정확한 버전 탐지와 문제 재현을 제공합니다 La política de actualización de bibliotecas es una guía para detectar versiones exactas y reproducir problemas antes de cambiar el código, preferir soluciones locales y capturar notas de actualización resueltas La politique de mise à jour de bibliothèques est un guide pour détecter les versions exactes et reproduire les problèmes avant de modifier le code, préférer les solutions locales et capturer les notes de mise à jour résolues Die Bibliotheks-Update-Richtlinie ist ein Leitfaden zur Erkennung exakter Versionen und Reproduktion von Problemen vor Codeänderungen, lokalen Lösungen zu bevorzugen und gelöste Update-Hinweise zu erfassen A política de atualização de bibliotecas visa detectar a versão exata e reproduzir o problema antes de alterar o código, priorizando soluções locais e capturando notas de atualização. Политика обновления библиотек направлена на обнаружение точной версии и воспроизведение проблемы перед изменением кода, отдавая предпочтение локальным решениям. تهدف سياسة تحديث المكتبات إلى تحديد الإصدار الدقيق واعادة إنتاج المشكلة قبل التعديل على الكود، مع التركيز على الحلول المحلية وتسجيل ملاحظات التحديث how to use library-update-policy library-update-policy setup guide library-update-policy best practices library-update-policy alternative library-update-policy vs dependency management tools what is library-update-policy library-update-policy install library-update-policy for AI agents 库更新策略 AI工具 代码更新 版本检测 项目本地修复 文档确认 升级说明 代码库管理 Detects exact version and reproduces the issue before changing code Prefers project-local fixes before broad refactors Asks user to confirm behavior when documentation and runtime differ Treats user-provided documentation links and usage guidance as a source of truth Captures resolved upgrade notes in concise repository documentation library-update-policy is a set of guidelines for managing library updates, emphasizing project-local fixes, user confirmation, and concise documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ffernandomoraes/react-starter-template/antd-specialist', 'community', 'ffernandomoraes', 'react-starter-template', 'ffernandomoraes/react-starter-template', 'antd-specialist', 0, 0, 20, '2026-03-08T01:57:15.625Z', '2026-03-08T02:13:33.541Z', '7e642629732c210b59ae509313e34258c33da4bf5249cc7942bf1a65b5beff83', '{"id":"ffernandomoraes/react-starter-template/antd-specialist","name":"antd-specialist","description":{"en":"The antd-specialist skill enables AI agents to consume remote content using WebFetch, following specific guidelines and rules for Ant Design 6. This skill benefits developers working with Ant Design.","zh":"Ant Design 6 Specialist 是一个使用 WebFetch 消费 antd-specialist.txt 内容的 AI Agent，提供 Ant Design 6 的设置和使用指南","ja":"Ant Design 6 Specialist は WebFetch を使用して antd-specialist.txt の内容を消費する AI エージェントで、Ant Design 6 の設定と使用方法を提供します","ko":"Ant Design 6 Specialist는 WebFetch를 사용하여 antd-specialist.txt 내용을 소비하는 AI 에이전트로, Ant Design 6의 설정 및 사용 방법을 제공합니다","es":"El especialista en Ant Design 6 es una herramienta que ayuda a los desarrolladores a configurar y utilizar la biblioteca Ant Design de manera efectiva","fr":"Le spécialiste Ant Design 6 est un outil qui aide les développeurs à configurer et à utiliser la bibliothèque Ant Design de manière efficace","de":"Der Ant Design 6-Spezialist ist ein Tool, das Entwicklern hilft, die Bibliothek Ant Design effektiv zu konfigurieren und zu verwenden","pt":"O antd-specialist é uma habilidade que requer configuração com consumo de conteúdo via WebFetch e implementação de diretrizes de especialista.","ru":"Antd-specialist - это навык, требующий настройки с потреблением контента через WebFetch и реализацией руководств специалиста для ИИ Агентов.","ar":"العامل اند-اسبيشالست هو مهارة تتطلب إعدادًا باستخدام استهلاك المحتوى عبر WebFetch وتنفيذ إرشادات الخبير للـ AI Tools."},"seo":{"title":{"en":"antd-specialist: WebFetch Integration Setup Guide | AI Ag...","zh":"Ant Design 6 Specialist 设置指南","ja":"Ant Design 6 Specialist のベストプラクティス","ko":"Ant Design 6 Specialist 설정 가이드","es":"Guía de Configuración de Ant Design 6 Specialist","fr":"Guide de Mise en Place de Ant Design 6 Specialist","de":"Einrichtungsanleitung für Ant Design 6 Specialist","pt":"Guia de Configuração do Antd-Specialist para Desenvolvedores","ru":"ИИ Агенты: Настройка Antd-Specialist для Разработчиков","ar":"دليل إعداد العامل اند-اسبيشالست للـ AI Tools"},"description":{"en":"Unlock antd-specialist''s full potential by learning how to integrate WebFetch and consume remote content for AI agents - get started now!","zh":"了解 Ant Design 6 Specialist 的设置和使用方法，掌握 WebFetch 和 antd-specialist.txt 的应用","ja":"Ant Design 6 Specialist の設定と使用方法を学び、WebFetch と antd-specialist.txt の応用をマスターしましょう","ko":"Ant Design 6 Specialist 설정과 사용 방법을 알아보고 WebFetch와 antd-specialist.txt의 적용을 익히세요","es":"Aprende a configurar y utilizar el especialista en Ant Design 6 para mejorar tus proyectos de desarrollo web con React y herramientas de CLI","fr":"Découvrez comment configurer et utiliser le spécialiste Ant Design 6 pour améliorer vos projets de développement web avec React et les outils de ligne de com...","de":"Erfahren Sie, wie Sie den Ant Design 6-Spezialisten konfigurieren und verwenden können, um Ihre Webentwicklungsprojekte mit React und CLI-Tools zu verbessern","pt":"Aprenda a configurar o antd-specialist com nosso guia passo a passo, incluindo consumo de conteúdo com WebFetch e implementação de diretrizes de especialista","ru":"Узнайте, как настроить antd-specialist с помощью нашего пошагового руководства, включая потребление контента с WebFetch и реализацию руководств специалиста д...","ar":"تعرف على كيفية إعداد العامل اند-اسبيشالست بخطوات بسيطة، بما في ذلك استهلاك المحتوى باستخدام WebFetch وتنفيذ إرشادات الخبير للـ AI Tools"},"definition":{"en":"antd-specialist is a skill that enables AI agents to integrate with Ant Design 6 using WebFetch, following predefined rules and guidelines.","zh":"Ant Design 6 Specialist 是一个使用 WebFetch 的 AI Agent，提供 Ant Design 6 的设置和使用指南","ja":"Ant Design 6 Specialist は WebFetch を使用する AI エージェントで、Ant Design 6 の設定と使用方法を提供するものです","ko":"Ant Design 6 Specialist는 WebFetch를 사용하는 AI 에이전트로, Ant Design 6의 설정 및 사용 방법을 제공하는 것입니다","es":"Un especialista en Ant Design 6 es un agente de inteligencia artificial que proporciona directrices y reglas para el uso de la biblioteca Ant Design","fr":"Un spécialiste Ant Design 6 est un agent d''intelligence artificielle qui fournit des directives et des règles pour l''utilisation de la bibliothèque Ant Design","de":"Ein Ant Design 6-Spezialist ist ein künstliches Intelligenzagent, das Richtlinien und Regeln für die Verwendung der Bibliothek Ant Design bereitstellt","pt":"O que é antd-specialist? É uma habilidade que segue diretrizes de especialista para desenvolvedores, consumindo conteúdo via WebFetch.","ru":"Что такое antd-specialist? Это навык, следующий руководствам специалиста для разработчиков, потребляющий контент через WebFetch для ИИ Агентов.","ar":"ما هو العامل اند-اسبيشالست؟ إنه مهارة تتبع إرشادات الخبير للمطورين، واستهلاك المحتوى عبر WebFetch للـ AI Tools."},"features":{"en":["Consumes remote content from a specified URL using WebFetch","Follows guidelines and rules defined in the antd-specialist.txt file","Integrates with Ant Design 6 for specialized functionality","Requires WebFetch tool for content consumption","Enforces strict adherence to predefined rules and standards","Supports AI agent actions based on consumed remote content"],"zh":["使用 WebFetch 消费 antd-specialist.txt 内容","提供 Ant Design 6 的设置和使用指南","支持 Ant Design 6 的开发和应用","集成 WebFetch 和 antd-specialist.txt 的功能","提供 Ant Design 6 的最佳实践和设置方法"],"ja":["WebFetch を使用して antd-specialist.txt の内容を消費する","Ant Design 6 の設定と使用方法を提供する","Ant Design 6 の開発と応用をサポートする","WebFetch と antd-specialist.txt の機能を統合する","Ant Design 6 のベストプラクティスと設定方法を提供する"],"ko":["WebFetch를 사용하여 antd-specialist.txt 내용을 소비하는","Ant Design 6의 설정 및 사용 방법을 제공하는","Ant Design 6의 개발과 적용을 지원하는","WebFetch와 antd-specialist.txt의 기능을 통합하는","Ant Design 6의 최선의 관행과 설정 방법을 제공하는"],"es":["Consume contenido de la URL proporcionada mediante WebFetch","Sigue las directrices y reglas establecidas en el documento remoto","Compatibilidad con React y herramientas de CLI","Mejora la configuración y el uso de la biblioteca Ant Design","Proporciona documentación completa para el especialista"],"fr":["Consomme le contenu de l''URL fournie via WebFetch","Suive les directives et les règles établies dans le document distant","Compatibilité avec React et les outils de ligne de commande","Améliore la configuration et l''utilisation de la bibliothèque Ant Design","Fournit une documentation complète pour le spécialiste"],"de":["Konsumiert den Inhalt der bereitgestellten URL über WebFetch","Folgt den Richtlinien und Regeln, die im Remote-Dokument festgelegt sind","Kompatibilität mit React und CLI-Tools","Verbessert die Konfiguration und den Einsatz der Bibliothek Ant Design","Bietet eine umfassende Dokumentation für den Spezialisten"],"pt":["Consumo de conteúdo via WebFetch","Implementação de diretrizes de especialista","Suporte à Ant Design 6","Integração com ferramentas de desenvolvimento","Seguimento de padrões e regras de especialista","Acesso a documentação completa"],"ru":["Потребление контента через WebFetch","Реализация руководств специалиста","Поддержка Ant Design 6 для ИИ Агентов","Интеграция с инструментами разработки","Следование стандартам и правилам специалиста","Доступ к полной документации"],"ar":["استهلاك المحتوى عبر WebFetch","تنفيذ إرشادات الخبير","دعم تصميم اند 6 للـ AI Tools","تكامل مع أدوات التطوير","متابعة معايير وقواعد الخبير","الوصول إلى الوثائق الكاملة"]},"keywords":{"en":["how to use antd-specialist","what is antd-specialist","antd-specialist alternative","antd-specialist vs ant design","antd-specialist install","antd-specialist setup guide","webfetch integra