INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ffernandomoraes/react-starter-template/antd-specialist', 'antd-specialist', 'ffernandomoraes', 'react-starter-template', 'community', 'antd-specialist ffernandomoraes react-starter-template community The antd-specialist skill enables AI agents to consume remote content using WebFetch, following specific guidelines and rules for Ant Design 6. This skill benefits developers working with Ant Design. Ant Design 6 Specialist 是一个使用 WebFetch 消费 antd-specialist.txt 内容的 AI Agent，提供 Ant Design 6 的设置和使用指南 Ant Design 6 Specialist は WebFetch を使用して antd-specialist.txt の内容を消費する AI エージェントで、Ant Design 6 の設定と使用方法を提供します Ant Design 6 Specialist는 WebFetch를 사용하여 antd-specialist.txt 내용을 소비하는 AI 에이전트로, Ant Design 6의 설정 및 사용 방법을 제공합니다 El especialista en Ant Design 6 es una herramienta que ayuda a los desarrolladores a configurar y utilizar la biblioteca Ant Design de manera efectiva Le spécialiste Ant Design 6 est un outil qui aide les développeurs à configurer et à utiliser la bibliothèque Ant Design de manière efficace Der Ant Design 6-Spezialist ist ein Tool, das Entwicklern hilft, die Bibliothek Ant Design effektiv zu konfigurieren und zu verwenden O antd-specialist é uma habilidade que requer configuração com consumo de conteúdo via WebFetch e implementação de diretrizes de especialista. Antd-specialist - это навык, требующий настройки с потреблением контента через WebFetch и реализацией руководств специалиста для ИИ Агентов. العامل اند-اسبيشالست هو مهارة تتطلب إعدادًا باستخدام استهلاك المحتوى عبر WebFetch وتنفيذ إرشادات الخبير للـ AI Tools. how to use antd-specialist what is antd-specialist antd-specialist alternative antd-specialist vs ant design antd-specialist install antd-specialist setup guide webfetch integration ant design 6 specialist ai agent skills Ant Design 6 WebFetch antd-specialist.txt AI Agent 设置指南 最佳实践 Ant Design 6 设置 WebFetch 应用 antd-specialist.txt 使用 Consumes remote content from a specified URL using WebFetch Follows guidelines and rules defined in the antd-specialist.txt file Integrates with Ant Design 6 for specialized functionality Requires WebFetch tool for content consumption Enforces strict adherence to predefined rules and standards Supports AI agent actions based on consumed remote content antd-specialist is a skill that enables AI agents to integrate with Ant Design 6 using WebFetch, following predefined rules and guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jwiegley/claude-prompts/nixos', 'community', 'jwiegley', 'claude-prompts', 'jwiegley/claude-prompts', 'nixos', 0, 0, 20, '2026-03-08T01:57:15.638Z', '2026-03-08T02:13:39.490Z', 'd5ef7f01b662747fbd50bd9e38f29fe019898d48d141ea553c5fe02aea158864', '{"id":"jwiegley/claude-prompts/nixos","name":"nixos","description":{"en":"The nixos skill provides commands and agents for NixOS installation, leveraging nix-pro and nixos MCP to resolve issues and ensure secure usage, benefiting AI agent developers and NixOS users","zh":"NixOS是基于Nix包管理器的Linux发行版，本文介绍如何使用nix-pro和nixos MCP解决NixOS安装中的常见问题","ja":"NixOSはNixパッケージマネージャーをベースとしたLinuxディストリビューションです。本文では、nix-proとnixos MCPを使用してNixOSのインストールにおける一般的な問題を解決する方法について説明します","ko":"NixOS는 Nix 패키지 관리자를 기반으로 하는 Linux 배포판입니다. 본 문서에서는 NixOS 설치에서 일반적인 문제를 해결하는 방법을介绍합니다","es":"NixOS es una distribución de Linux que se puede configurar con Claude Code y nix-pro para resolver problemas de instalación y seguridad.","fr":"NixOS est une distribution Linux qui peut être configurée avec Claude Code et nix-pro pour résoudre les problèmes d''installation et de sécurité.","de":"NixOS ist eine Linux-Distribution, die mit Claude Code und nix-pro konfiguriert werden kann, um Installations- und Sicherheitsprobleme zu lösen.","pt":"O NixOS é uma distribuição Linux que oferece uma abordagem única para gerenciamento de pacotes e configuração do sistema. Utilize nix-pro e nixos MCP para resolver problemas comuns.","ru":"NixOS - это дистрибутив Linux, который предлагает уникальный подход к управлению пакетами и конфигурации системы. Используйте nix-pro и nixos MCP для решения общих проблем с ИИ Агентами.","ar":"NixOS هو توزيع لينكس يقدم نهجًا فريدًا لإدارة الحزم وتكوين النظام. استخدم nix-pro و nixos MCP لحل المشكلات الشائعة لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"nixos: NixOS Setup Guide for AI Agents","zh":"NixOSSetup指南：使用nix-pro和nixos MCP","ja":"NixOSのベストプラクティス：nix-proとnixos MCPの活用","ko":"NixOS설치 가이드: nix-pro와 nixos MCP 활용","es":"Guía de configuración de NixOS con Claude Code","fr":"Configurer NixOS avec Claude Code : Meilleures pratiques","de":"NixOS-Setup-Anleitung mit Claude Code und nix-pro","pt":"Guia de Configuração NixOS: Melhores Práticas para Desenv...","ru":"Настройка NixOS: Руководство по лучшим практикам для разр...","ar":"دليل تكوين NixOS: أفضل الممارسات للطورين باستخدام أدوات ا..."},"description":{"en":"Unlock the full potential of NixOS with our expert guide, featuring tips on using nix-pro, nixos MCP, and SOPS secrets.yaml securely","zh":"了解NixOS的安装和配置，使用nix-pro和nixos MCP解决常见问题，提高开发效率","ja":"NixOSのインストールと設定について学び、nix-proとnixos MCPを使用して開発を効率化する","ko":"NixOS 설치와 설정에 대해 알아보고 nix-pro와 nixos MCP를 사용하여 개발 효율성을 높여보세요","es":"Aprende a configurar NixOS de manera segura con Claude Code y nix-pro, evitando la desencriptación de SOPS secrets.yaml","fr":"Découvrez comment configurer NixOS en toute sécurité avec Claude Code et nix-pro, en évitant la désencryption de SOPS secrets.yaml","de":"Erfahren Sie, wie Sie NixOS sicher mit Claude Code und nix-pro konfigurieren, ohne die SOPS secrets.yaml-Datei zu entschlüsseln","pt":"Aprenda a configurar o NixOS com segurança e eficiência, utilizando ferramentas como nix-pro e nixos MCP","ru":"Узнайте, как настроить NixOS безопасно и эффективно, используя инструменты nix-pro и nixos MCP для ИИ Агентов","ar":"تعلم كيفية تكوين NixOS بطريقة آمنة وفعالة، باستخدام أدوات مثل nix-pro و nixos MCP لأدوات الذكاء الاصطناعي"},"definition":{"en":"nixos is a collection of commands, agents, and skills for NixOS, focusing on secure and efficient installation and management","zh":"NixOS是一个基于Nix包管理器的Linux发行版，使用nix-pro和nixos MCP可以提高开发效率","ja":"NixOSは、NixパッケージマネージャーをベースとしたLinuxディストリビューションであり、nix-proとnixos MCPを使用することで開発効率を向上させることができます","ko":"NixOS는 Nix 패키지 관리자를 기반으로 하는 Linux 배포판으로, nix-pro와 nixos MCP를 사용하여 개발 효율성을 높일 수 있습니다","es":"NixOS es una distribución de Linux que utiliza el gestor de paquetes Nix y se puede configurar con Claude Code para mejorar la seguridad y la eficiencia.","fr":"NixOS est une distribution Linux qui utilise le gestionnaire de paquets Nix et peut être configurée avec Claude Code pour améliorer la sécurité et l''efficacité.","de":"NixOS ist eine Linux-Distribution, die den Paketmanager Nix verwendet und mit Claude Code konfiguriert werden kann, um die Sicherheit und Effizienz zu verbessern.","pt":"NixOS é uma distribuição Linux que utiliza o gerenciador de pacotes Nix para fornecer uma configuração do sistema imutável e reproduzível.","ru":"NixOS - это дистрибутив Linux, который использует менеджер пакетов Nix для предоставления неизменной и воспроизводимой конфигурации системы для ИИ Агентов.","ar":"NixOS هو توزيع لينكس يستخدم مدير الحزم Nix لتوفير تكوين نظام غير قابل للتغيير وقابل للتكرار لأدوات الذكاء الاصطناعي."},"features":{"en":["Utilizes nix-pro for efficient NixOS management","Leverages nixos MCP to resolve installation issues","Ensures secure handling of SOPS secrets.yaml files","Integrates with Web Search and Perplexity for research and resource discovery","Employs sequential-thinking for task breakdown and context7 for code examples"],"zh":["使用nix-pro解决NixOS安装中的常见问题","利用nixos MCP提高开发效率","支持Web Search和Perplexity进行研究和资源发现","支持sequential-thinking进行任务分解","支持context7进行代码示例展示"],"ja":["nix-proを使用してNixOSのインストールにおける一般的な問題を解決する","nixos MCPを使用して開発効率を向上させる","Web SearchとPerplexityをサポートして研究とリソースの発見を実行する","sequential-thinkingをサポートしてタスクを分解する","context7をサポートしてコード例を表示する"],"ko":["nix-pro를 사용하여 NixOS 설치에서 일반적인 문제를 해결합니다","nixos MCP를 사용하여 개발 효율성을 높입니다","Web Search와 Perplexity를 지원하여 연구와 리소스 발견을 수행합니다","sequential-thinking을 지원하여 태스크를 분解합니다","context7를 지원하여 코드 예시를 표시합니다"],"es":["Configuración segura con nix-pro y Claude Code","Evitación de la desencriptación de SOPS secrets.yaml","Uso de Web Search y Perplexity para la investigación","Uso de la secuencialidad para dividir tareas","Uso de context7 para ejemplos de código"],"fr":["Configuration sécurisée avec nix-pro et Claude Code","Évitement de la désencryption de SOPS secrets.yaml","Utilisation de Web Search et Perplexity pour la recherche","Utilisation de la pensée séquentielle pour diviser les tâches","Utilisation de context7 pour des exemples de code"],"de":["Sichere Konfiguration mit nix-pro und Claude Code","Vermeidung der Entschlüsselung von SOPS secrets.yaml","Verwendung von Web Search und Perplexity für die Recherche","Verwendung der Sequenzialität zur Aufteilung von Aufgaben","Verwendung von context7 für Codebeispiele"],"pt":["Utilize nix-pro para resolver problemas comuns","Utilize nixos MCP para gerenciar a configuração do sistema","Integração com Web Search e Perplexity para pesquisa e descoberta de recursos","Utilize sequential-thinking para quebrar tarefas em etapas menores","Utilize context7 para exemplos de código"],"ru":["Используйте nix-pro для решения общих проблем","Используйте nixos MCP для управления конфигурацией системы для ИИ Агентов","Интеграция с Web Search и Perplexity для исследования и обнаружения ресурсов","Используйте sequential-thinking для разбиения задач на более мелкие этапы","Используйте context7 для примеров кода"],"ar":["استخدم nix-pro لحل المشكلات الشائعة","استخدم nixos MCP لإدارة تكوين النظام لأدوات الذكاء الاصطناعي","التكامل مع Web Search و Perplexity للبحث واكتشاف الموارد","استخدم sequential-thinking لتقسيم المهام إلى خطوات أصغر","استخدم context7 لأمثلة الشفرة"]},"keywords":{"en":["nixos setup guide","how to use nixos","nixos vs guix","nixos install","what is nixos","nixos alternative","nixos MCP tutorial","nix-pro commands","SOPS secrets.yaml security"],"zh":["NixOS安装","nix-pro","nixos MCP","Linux发行版","Nix包管理器","开发效率","Web Search","Perplexity","sequential-thinking","context7"],"ja":["NixOSインストール","nix-pro","nixos MCP","Linuxディストリビューション","Nixパッケージマネージャー","開発効率","Web Search","Perplexity","sequential-thinking","context7"],"ko":["NixOS설치","nix-pro","nixos MCP","Linux배포판","Nix패키지관리자","개발효율성","Web Search","Perplexity","sequential-thinking","context7"],"es":["NixOS configuración","Claude Code","nix-pro","SOPS secrets.yaml","seguridad en NixOS","configuración de NixOS","herramientas de desarrollo para NixOS","AI Agentes para NixOS","Agentes de inteligencia artificial para Linux"],"fr":["Configuration de NixOS","Claude Code","nix-pro","SOPS secrets.yaml","sécurité sous NixOS","configuration de NixOS","outils de développement pour NixOS","Agents IA pour NixOS","Agents d''intelligence artificielle pour Linux"],"de":["NixOS-Konfiguration","Claude Code","nix-pro","SOPS secrets.yaml","Sicherheit unter NixOS","NixOS-Konfiguration","Entwicklungstools für NixOS","KI-Agents für NixOS","Künstliche Intelligenz-Agents für Linux"],"pt":["nixos","nix-pro","nixos MCP","configuração do sistema","gerenciamento de pacotes","desenvolvedores","linux","segurança","eficiência"],"ru":["nixos","nix-pro","nixos MCP","конфигурация системы","управление пакетами","разработчики","linux","безопасность","эффективность","ИИ Агенты"],"ar":["nixos","nix-pro","nixos MCP","تكوين النظام","إدارة الحزم","طورين","لينكس","أمان","كفاءة","أدوات الذكاء الاصطناعي"]}},"owner":"jwiegley","repo":"claude-prompts","repoPath":"jwiegley/claude-prompts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.638Z","topics":[],"category":"community","skillMd":{"name":"nixos","description":"Resolve NixOS issues using research and sequential thinking","bodyPreview":"Use nix-pro and nixos MCP to resolve the following issues with the current NixOS installation.\n\n- Do not, under any circumstances, decrypt the SOPS secrets.yaml file. See the\n  @CLAUDE.md file for extensive notes on this important security consideration.\n\n- Use Web Search and Perplexity as need for research and discovering resources.\n\n- Use sequential-thinking when appropriate to break down tasks further.\n\n- Use context7 whenever code examples might help.\n\n- Each time before you intend to build","body":"Use nix-pro and nixos MCP to resolve the following issues with the current NixOS installation.\n\n- Do not, under any circumstances, decrypt the SOPS secrets.yaml file. See the\n  @CLAUDE.md file for extensive notes on this important security consideration.\n\n- Use Web Search and Perplexity as need for research and discovering resources.\n\n- Use sequential-thinking when appropriate to break down tasks further.\n\n- Use context7 whenever code examples might help.\n\n- Each time before you intend to build or switch to a new configuration, use\n  `touch` a create a file named `/etc/nixos/.nixos-build`. Remove this file\n  when the build or the switch is completed. If you see that this file already\n  exists, wait for up to ten minutes, checking every 10 seconds during that\n  time to see if the file has been removed. This way, multiple nixos jobs can\n  be working with the system at the same time, but only one will be building\n  or switching at any given time.\n"},"lastSynced":"2026-03-08T02:13:39.490Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing secure NixOS installation and management capabilities.","zh":"非常适合需要安全的 NixOS 安装和管理能力的 DevOps Agents。","ja":"DevOps エージェントがセキュアな NixOS のインストールと管理機能を必要とする場合に最適です。","ko":"보안이 필요한 NixOS 설치 및 관리 기능을 필요로 하는 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan capacidades de instalación y administración de NixOS seguras.","fr":"Parfait pour les agents DevOps ayant besoin de capacités d''installation et de gestion de NixOS sécurisées.","de":"Perfekt für DevOps-Agents, die sichere NixOS-Installations- und Verwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de capacidades de instalação e gerenciamento seguras do NixOS.","ru":"Идеально для агентов DevOps, которым необходимы безопасные возможности установки и управления NixOS.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى إمكانيات تثبيت وإدارة NixOS آمنة."},"recommendation":{"en":"Empowers agents to resolve NixOS installation issues using nix-pro and nixos MCP, ensuring secure usage and benefiting from Web Search and Perplexity for research, while leveraging sequential-thinking and context7 for code examples and task breakdowns.","zh":"赋予代理人使用 nix-pro 和 nixos MCP 解决 NixOS 安装问题的能力，确保安全使用，并利用 Web Search 和 Perplexity 进行研究，同时利用 sequential-thinking 和 context7 进行代码示例和任务分解。","ja":"エージェントが nix-pro と nixos MCP を使用して NixOS のインストールの問題を解決する能力を与え、セキュアな使用を確保し、Web Search と Perplexity を使用して研究を行い、さらに sequential-thinking と context7 を使用してコードの例とタスクの分解を行う。","ko":"에이전트가 nix-pro 및 nixos MCP를 사용하여 NixOS 설치 문제를 해결할 수 있도록 하며, 보안 사용을 보장하고, Web Search 및 Perplexity를 사용하여 연구를 수행하며, 순차적思考 및 context7을 사용하여 코드 예시 및 작업 분해를 수행할 수 있습니다.","es":"Habilita a los agentes a resolver problemas de instalación de NixOS utilizando nix-pro y nixos MCP, garantizando un uso seguro y beneficiándose de Web Search y Perplexity para la investigación, mientras aprovecha la secuencialidad y context7 para ejemplos de código y desglose de tareas.","fr":"Permet aux agents de résoudre les problèmes d''installation de NixOS en utilisant nix-pro et nixos MCP, en assurant une utilisation sécurisée et en bénéficiant de Web Search et Perplexity pour la recherche, tout en exploitant la pensée séquentielle et context7 pour les exemples de code et la décomposition des tâches.","de":"Ermächtigt Agenten, NixOS-Installationsprobleme mit nix-pro und nixos MCP zu lösen, sichereren Einsatz sicherzustellen und von Web Search und Perplexity für Recherchen zu profitieren, während sequenzielles Denken und context7 für Codebeispiele und Aufgabenzerlegung genutzt werden.","pt":"Habilita os agentes a resolver problemas de instalação do NixOS usando nix-pro e nixos MCP, garantindo uso seguro e se beneficiando da Pesquisa na Web e Perplexity para pesquisas, ao mesmo tempo em que aproveita a sequencial-thinking e context7 para exemplos de código e divisão de tarefas.","ru":"Наделяет агентов возможностью решать проблемы установки NixOS с помощью nix-pro и nixos MCP, обеспечивая безопасное использование и пользуясь Веб-поиском и Perplexity для исследований, а также используя последовательное мышление и context7 для примеров кода и разбиения задач.","ar":"يمنح الوكلاء القدرة على حل مشاكل تثبيت NixOS باستخدام nix-pro و nixos MCP، وضمان الاستخدام الآمن والاستفادة من البحث على الويب و Perplexity للبحث، وفي الوقت نفسه استخدام التفكير المتسلسل و context7 لأمثلة الشفرة و تقسيم المهام."},"useCases":{"en":["Resolving NixOS installation issues with nix-pro and nixos MCP","Ensuring secure usage by avoiding decryption of SOPS secrets.yaml files","Researching and discovering resources using Web Search and Perplexity"],"zh":["使用 nix-pro 和 nixos MCP 解决 NixOS 安装问题","确保安全使用，避免解密 SOPS secrets.yaml 文件","使用 Web Search 和 Perplexity 进行研究和资源发现"],"ja":["nix-pro と nixos MCP を使用して NixOS のインストールの問題を解決する","セキュアな使用を確保するために SOPS secrets.yaml ファイルの解密を避ける","Web Search と Perplexity を使用して研究とリソースの発見を行う"],"ko":["nix-pro 및 nixos MCP를 사용하여 NixOS 설치 문제를 해결하는 것","보안 사용을 보장하기 위해 SOPS secrets.yaml 파일의 해독을 피하는 것","Web Search 및 Perplexity를 사용하여 연구 및 리소스 발견을 수행하는 것"],"es":["Resolver problemas de instalación de NixOS con nix-pro y nixos MCP","Garantizar un uso seguro evitando la desencriptación de archivos secrets.yaml de SOPS","Investigar y descubrir recursos utilizando Web Search y Perplexity"],"fr":["Résoudre les problèmes d''installation de NixOS avec nix-pro et nixos MCP","Assurer une utilisation sécurisée en évitant la déchiffrement des fichiers secrets.yaml de SOPS","Rechercher et découvrir des ressources en utilisant Web Search et Perplexity"],"de":["NixOS-Installationsprobleme mit nix-pro und nixos MCP lösen","Sicheren Einsatz sicherstellen, indem die Entschlüsselung von SOPS secrets.yaml-Dateien vermieden wird","Ressourcen mithilfe von Web Search und Perplexity recherchieren und entdecken"],"pt":["Resolver problemas de instalação do NixOS com nix-pro e nixos MCP","Garantir uso seguro evitando a decodificação de arquivos secrets.yaml do SOPS","Pesquisar e descobrir recursos usando Pesquisa na Web e Perplexity"],"ru":["Решать проблемы установки NixOS с помощью nix-pro и nixos MCP","Обеспечивать безопасное использование, избегая расшифровки файлов secrets.yaml из SOPS","Изучать и открывать ресурсы с помощью Веб-поиска и Perplexity"],"ar":["حل مشاكل تثبيت NixOS باستخدام nix-pro و nixos MCP","ضمان الاستخدام الآمن من خلال تجنب فك تشفير ملفات secrets.yaml من SOPS","البحث واكتشاف الموارد باستخدام البحث على الويب و Perplexity"]},"limitations":{"en":["Must not decrypt SOPS secrets.yaml files for security reasons","Requires access to nix-pro and nixos MCP","Needs sequential-thinking and context7 for efficient task management and code examples"],"zh":["由于安全原因，必须避免解密 SOPS secrets.yaml 文件","需要访问 nix-pro 和 nixos MCP","需要 sequential-thinking 和 context7 进行高效的任务管理和代码示例"],"ja":["セキュリティの理由により、SOPS secrets.yaml ファイルの解密を避ける必要がある","nix-pro と nixos MCP にアクセスする必要がある","効率的なタスク管理とコードの例のために sequential-thinking と context7 が必要"],"ko":["보안 상의 이유로 SOPS secrets.yaml 파일의 해독을 피해야 함","nix-pro 및 nixos MCP에 접근할 수 있어야 함","효율적인 작업 관리 및 코드 예시를 위해 순차적思考 및 context7이 필요"],"es":["No debe desencriptar archivos secrets.yaml de SOPS por razones de seguridad","Requiere acceso a nix-pro y nixos MCP","Necesita pensamiento secuencial y context7 para una gestión eficiente de tareas y ejemplos de código"],"fr":["Ne doit pas déchiffrer les fichiers secrets.yaml de SOPS pour des raisons de sécurité","Nécessite l''accès à nix-pro et nixos MCP","Nécessite une pensée séquentielle et context7 pour une gestion efficace des tâches et des exemples de code"],"de":["Sollte SOPS secrets.yaml-Dateien aus Sicherheitsgründen nicht entschlüsseln","Benötigt Zugriff auf nix-pro und nixos MCP","Benötigt sequenzielles Denken und context7 für effizientes Aufgabenmanagement und Codebeispiele"],"pt":["Não deve decodificar arquivos secrets.yaml do SOPS por razões de segurança","Requer acesso a nix-pro e nixos MCP","Necessita de sequencial-thinking e context7 para gerenciamento eficiente de 