INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jwiegley/claude-prompts/nixos', 'nixos', 'jwiegley', 'claude-prompts', 'community', 'nixos jwiegley claude-prompts community The nixos skill provides commands and agents for NixOS installation, leveraging nix-pro and nixos MCP to resolve issues and ensure secure usage, benefiting AI agent developers and NixOS users NixOS是基于Nix包管理器的Linux发行版，本文介绍如何使用nix-pro和nixos MCP解决NixOS安装中的常见问题 NixOSはNixパッケージマネージャーをベースとしたLinuxディストリビューションです。本文では、nix-proとnixos MCPを使用してNixOSのインストールにおける一般的な問題を解決する方法について説明します NixOS는 Nix 패키지 관리자를 기반으로 하는 Linux 배포판입니다. 본 문서에서는 NixOS 설치에서 일반적인 문제를 해결하는 방법을介绍합니다 NixOS es una distribución de Linux que se puede configurar con Claude Code y nix-pro para resolver problemas de instalación y seguridad. NixOS est une distribution Linux qui peut être configurée avec Claude Code et nix-pro pour résoudre les problèmes d''installation et de sécurité. NixOS ist eine Linux-Distribution, die mit Claude Code und nix-pro konfiguriert werden kann, um Installations- und Sicherheitsprobleme zu lösen. O NixOS é uma distribuição Linux que oferece uma abordagem única para gerenciamento de pacotes e configuração do sistema. Utilize nix-pro e nixos MCP para resolver problemas comuns. NixOS - это дистрибутив Linux, который предлагает уникальный подход к управлению пакетами и конфигурации системы. Используйте nix-pro и nixos MCP для решения общих проблем с ИИ Агентами. NixOS هو توزيع لينكس يقدم نهجًا فريدًا لإدارة الحزم وتكوين النظام. استخدم nix-pro و nixos MCP لحل المشكلات الشائعة لأدوات الذكاء الاصطناعي. nixos setup guide how to use nixos nixos vs guix nixos install what is nixos nixos alternative nixos MCP tutorial nix-pro commands SOPS secrets.yaml security NixOS安装 nix-pro nixos MCP Linux发行版 Nix包管理器 开发效率 Web Search Perplexity sequential-thinking context7 Utilizes nix-pro for efficient NixOS management Leverages nixos MCP to resolve installation issues Ensures secure handling of SOPS secrets.yaml files Integrates with Web Search and Perplexity for research and resource discovery Employs sequential-thinking for task breakdown and context7 for code examples nixos is a collection of commands, agents, and skills for NixOS, focusing on secure and efficient installation and management');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('airopshq/airops-claude-plugin/refresh-content', 'community', 'airopshq', 'airops-claude-plugin', 'airopshq/airops-claude-plugin', 'refresh-content', 0, 0, 20, '2026-03-08T01:57:15.661Z', '2026-03-08T02:14:06.108Z', 'e7049e7638967ac7ce3af543790c2ace6cb79491603008a4688bdfa4d21c41e1', '{"id":"airopshq/airops-claude-plugin/refresh-content","name":"refresh-content","description":{"en":"The refresh-content skill audits and updates existing content at a specified source, ensuring accuracy and freshness. It benefits developers and content creators looking to maintain up-to-date information.","zh":"refresh-content是一种AI工具，用于更新内容。它可以审计内容，检查时效性元素，并进行深度更新","ja":"refresh-contentは、コンテンツを更新するAIエージェントです。コンテンツの監査、鮮度チェック、深度更新を行います","ko":"refresh-content는 콘텐츠를 업데이트하는 AI 도구입니다. 콘텐츠 감사, 신선도 확인 및 깊은 업데이트를 수행합니다","es":"Refresh-content es una habilidad que actualiza contenido existente con estadísticas y enlaces actualizados, utilizando herramientas de AI para desarrolladores","fr":"Refresh-content est une compétence qui met à jour le contenu existant avec des statistiques et des liens à jour, en utilisant des outils d''IA pour les développeurs","de":"Refresh-content ist eine Fähigkeit, die bestehende Inhalte mit Statistiken und aktuellen Links aktualisiert, mit KI-Tools für Entwickler","pt":"O Refresh-Content é uma ferramenta de IA que ajuda a atualizar o conteúdo, verificando estatísticas e links externos","ru":"Освежение контента - это инструмент ИИ, который помогает обновлять информацию, проверяя статистику и внешние ссылки","ar":"Refresh-Content هو أداة الإي الأبتكارية التي تساعد في تحديث المحتوى، من خلال التحقق من الإحصائيات والروابط الخارجية"},"seo":{"title":{"en":"refresh-content: Content Refresh Setup Guide | AI Agent S...","zh":"refresh-content Setup Guide: 更新内容的AI工具","ja":"refresh-content のベストプラクティス: コンテンツの更新を効率化するAIエージェント","ko":"refresh-content 설정 가이드: 최신 콘텐츠를 위한 AI 도구","es":"Guía de configuración de refresh-content: Actualiza conte...","fr":"Guide de mise en place de refresh-content: Mettre à jour ...","de":"Einrichtungsleitfaden für refresh-content: Aktualisieren ...","pt":"Guia de Configuração do Refresh-Content: Otimização de Co...","ru":"Настройка освежения контента: ИИ Агенты для анализа и обн...","ar":"دليل إعداد Refresh-Content: تحسين المحتوى باستخدام أدوات ..."},"description":{"en":"Discover how to refresh content at scale with our AI agent skill. Learn to audit, update, and verify content accuracy with ease. Get started now!","zh":"了解refresh-content的技术细节，包括内容审计、时效性检查和深度更新。使用此AI工具优化您的内容更新流程","ja":"refresh-contentの機能を詳しく知る。コンテンツの監査、鮮度チェック、深度更新などをAIエージェントで効率化する","ko":"refresh-content의 기술 세부 정보를 확인하고 최신 콘텐츠를 위한 AI 도구를 사용하여 콘텐츠 업데이트 프로세스를 최적화하세요","es":"Aprende a utilizar refresh-content para actualizar contenido con estadísticas y enlaces actualizados, con herramientas de AI para desarrolladores","fr":"Découvrez comment utiliser refresh-content pour mettre à jour le contenu avec des statistiques et des liens à jour, avec des outils d''IA pour les développeurs","de":"Erfahren Sie, wie Sie refresh-content verwenden, um Inhalte mit Statistiken und aktuellen Links zu aktualisieren, mit KI-Tools für Entwickler","pt":"Aprenda a configurar o Refresh-Content para atualizar seu conteúdo de forma eficaz, com análise de estatísticas e links externos","ru":"Узнайте, как настроить освежение контента для эффективного обновления информации, с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Refresh-Content لتحديث محتواك بفعالية، مع تحليل الإحصائيات والروابط الخارجية"},"definition":{"en":"refresh-content is a skill that refreshes content at a specified source, auditing and updating existing information to ensure accuracy and relevance.","zh":"refresh-content是指使用AI工具更新内容的过程，包括审计、时效性检查和深度更新","ja":"refresh-contentとは、AIエージェントを使用してコンテンツを更新するプロセスであり、監査、鮮度チェック、深度更新が含まれます","ko":"refresh-content는 AI 도구를 사용하여 콘텐츠를 업데이트하는 프로세스로 감사, 신선도 확인 및 깊은 업데이트를 포함합니다","es":"Refresh-content es una herramienta de AI que actualiza contenido existente con estadísticas y enlaces actualizados","fr":"Refresh-content est un outil d''IA qui met à jour le contenu existant avec des statistiques et des liens à jour","de":"Refresh-content ist ein KI-Tool, das bestehende Inhalte mit Statistiken und aktuellen Links aktualisiert","pt":"O que é Refresh-Content? É uma ferramenta de IA que atualiza o conteúdo, verificando estatísticas e links","ru":"Что такое освежение контента? Это инструмент ИИ, который обновляет информацию, проверяя статистику и ссылки","ar":"ما هو Refresh-Content؟ هو أداة الإي الأبتكارية التي تحديث المحتوى، من خلال التحقق من الإحصائيات والروابط"},"features":{"en":["Loads and audits content from a specified URL or file path","Performs freshness checks on time-sensitive elements, including statistics and claims","Verifies accuracy of statistics and finds updated data if outdated","Supports depth parameters, including quick, standard, and deep refresh options","Analyzes document structure, including headlines, word count, and external links"],"zh":["内容审计：加载和审计内容","时效性检查：审查所有时间敏感元素","深度更新：更新结构和统计数据","支持URL或文件路径","提供快速、标准和深度更新选项"],"ja":["コンテンツの監査：コンテンツを読み込み監査する","鮮度チェック：すべての時間依存要素を確認する","深度更新：構造と統計データを更新する","URLまたはファイルパスのサポート","クイック、スタンダード、ディープ更新のオプションを提供する"],"ko":["콘텐츠 감사: 콘텐츠를 로드하고 감사","신선도 확인: 모든 시간 의존 요소를 확인","깊은 업데이트: 구조 및 통계 데이터를 업데이트","URL 또는 파일 경로 지원","빠른, 표준 및 깊은 업데이트 옵션을 제공"],"es":["Análisis de contenido existente con estadísticas y enlaces","Actualización de estadísticas y fechas con datos actualizados","Verificación de enlaces externos y fuentes","Detección de menciones de productos o llamadas a la acción","Análisis de la estructura y el título del documento"],"fr":["Analyse de contenu existant avec des statistiques et des liens","Mise à jour des statistiques et des dates avec des données à jour","Vérification des liens externes et des sources","Détection des mentions de produits ou des appels à l''action","Analyse de la structure et du titre du document"],"de":["Analyse von bestehendem Inhalt mit Statistiken und Links","Aktualisierung von Statistiken und Daten mit aktuellen Daten","Überprüfung von externen Links und Quellen","Erkennung von Produktmentions oder Calls-to-Action","Analyse der Dokumentenstruktur und des Titels"],"pt":["Análise de estatísticas e datas","Verificação de links externos e fontes","Atualização de conteúdo com profundidade variável (quick, standard ou deep)","Detecção de mudanças estruturais","Verificação de menções de produtos ou CTAs"],"ru":["Анализ статистики и дат","Проверка внешних ссылок и источников","Обновление контента с переменной глубиной (quick, standard или deep)","Обнаружение структурных изменений","Проверка упоминаний продуктов или призывов к действию"],"ar":["تحليل الإحصائيات والأحكام","التحقق من الروابط الخارجية والمصادر","تحديث المحتوى بعمق متغير (سريع، معياري أو عميق)","اكتشاف التغييرات الهيكلية","التحقق من ذكر المنتجات أو الدعوات إلى العمل"]},"keywords":{"en":["how to use refresh-content","refresh-content setup guide","content refresh best practices","refresh-content alternative","refresh-content vs content update tools","install refresh-content","refresh-content tutorial","what is refresh-content","refresh-content documentation"],"zh":["AI工具","内容更新","内容审计","时效性检查","深度更新","refresh-content","AIエージェント","内容优化"],"ja":["AIエージェント","コンテンツ更新","コンテンツの監査","鮮度チェック","深度更新","refresh-content","コンテンツ最適化","AIツール"],"ko":["AI 도구","콘텐츠 업데이트","콘텐츠 감사","신선도 확인","깊은 업데이트","refresh-content","AI 에이전트","콘텐츠 최적화"],"es":["herramientas de AI para desarrolladores","actualización de contenido","estadísticas y enlaces actualizados","análisis de contenido","refresh-content","desarrollo de software","herramientas de desarrollo"],"fr":["outils d''IA pour les développeurs","mise à jour de contenu","statistiques et liens à jour","analyse de contenu","refresh-content","développement de logiciels","outils de développement"],"de":["KI-Tools für Entwickler","Inhaltsaktualisierung","Statistiken und aktuelle Links","Inhaltsanalyse","refresh-content","Softwareentwicklung","Entwicklungstools"],"pt":["ferramentas de IA para conteúdo","otimização de conteúdo","análise de estatísticas","verificação de links externos","atualização de conteúdo","Refresh-Content","guia de configuração"],"ru":["инструменты ИИ для контента","оптимизация контента","анализ статистики","проверка внешних ссылок","обновление контента","освежение контента","настройка освежения контента"],"ar":["أدوات الإي الأبتكارية للمحتوى","تحسين المحتوى","تحليل الإحصائيات","التحقق من الروابط الخارجية","تحديث المحتوى","Refresh-Content","دليل إعداد Refresh-Content"]}},"owner":"airopshq","repo":"airops-claude-plugin","repoPath":"airopshq/airops-claude-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.661Z","topics":[],"category":"community","skillMd":{"name":"refresh-content","description":"Update existing content with fresh information and improvements.","bodyPreview":"Refresh content at: $ARGUMENTS\n\n**Source:** URL or file path to existing content.\n**Depth:** quick (stats only), standard, or deep (structural changes).\n\n\n## 1. Audit\n\nLoad and audit the content at the source.\n\n- Document: headline and structure, all statistics and dates, external links and sources, product mentions or CTAs, word count\n\n## 2. Freshness Check\n\nReview all time-sensitive elements.\n\n- For each statistic or claim: verify still accurate, find updated data if outdated\n- For each extern","body":"Refresh content at: $ARGUMENTS\n\n**Source:** URL or file path to existing content.\n**Depth:** quick (stats only), standard, or deep (structural changes).\n\n\n## 1. Audit\n\nLoad and audit the content at the source.\n\n- Document: headline and structure, all statistics and dates, external links and sources, product mentions or CTAs, word count\n\n## 2. Freshness Check\n\nReview all time-sensitive elements.\n\n- For each statistic or claim: verify still accurate, find updated data if outdated\n- For each external link: check if live and relevant, find replacement if broken\n- Flag items: still accurate, needs updating, should be removed, new information to add\n\n## 3. Competitive Check\n\nResearch current SERP for this topic.\n\n- New competitors ranking; new angles or information they cover\n- Gaps in our content vs. current top results; new People Also Ask questions\n\n## 4. Refresh Plan\n\nBased on audits, create the plan.\n\n- **Quick:** Focus on updating stats and fixing broken links\n- **Standard:** Update stats, add missing info, improve weak sections\n- **Deep:** Consider structural changes, major additions, potential rewrite\n\nPlan format: Keep as-is, Update, Remove, Add, Structural changes. Checkpoint to review plan before executing if the user wants it.\n\n## 5. Execute\n\nApply the approved refresh plan.\n\n- Delegate to content-writer for prose changes where voice matters\n- Replace outdated statistics; fix or replace broken links; add new sections; remove outdated content\n- Quality checks: old and new content blend naturally, no jarring transitions, brand voice consistent, all new claims verified\n\n## 6. Finalize\n\nCreate final refreshed version.\n\n- Updated title tag and meta description if needed\n- \"Last updated: [date]\" note\n- Changelog summary (what was refreshed)\n- Recommendation for next refresh timing\n"},"lastSynced":"2026-03-08T02:14:06.108Z","agentAnalysis":{"suitability":{"en":"Ideal for Content Management Agents requiring automated content auditing and freshness checks","zh":"适用于需要自动内容审核和新鲜度检查的内容管理代理","ja":"自動コンテンツ監査および新鮮度チェックを必要とするコンテンツ管理エージェントに適しています","ko":"자동화된 콘텐츠 감사 및 신선도 확인이 필요한 콘텐츠 관리 에이전트에 적합합니다","es":"Ideal para Agentes de Gestión de Contenido que requieren auditorías de contenido automatizadas y verificaciones de frescura","fr":"Idéal pour les Agents de Gestion de Contenu nécessitant des audits de contenu automatisés et des vérifications de fraîcheur","de":"Ideal für Content-Management-Agents, die automatisierte Inhaltsaudits und Frischeprüfungen erfordern","pt":"Ideal para Agentes de Gerenciamento de Conteúdo que exigem auditoria de conteúdo automatizada e verificações de frescor","ru":"Идеально для агентов управления контентом, требующих автоматизированной проверки контента и проверок свежести","ar":"مثالي لعمليات وكيل إدارة المحتوى التي تتطلب تدقيق المحتوى التلقائي واختبارات النضج"},"recommendation":{"en":"Empowers agents to verify accuracy and update existing content using HTTP protocols and URL or file path sources, ensuring data freshness and integrity through depth-controlled audits, including quick stats-only checks, standard reviews, and deep structural analyses","zh":"赋予代理人使用HTTP协议和URL或文件路径源验证内容准确性和更新现有内容的能力，通过深度控制的审核确保数据新鲜度和完整性，包括快速统计检查、标准审查和深度结构分析","ja":"HTTPプロトコルとURLまたはファイルパスソースを使用して、コンテンツの正確性を検証し、既存のコンテンツを更新するエージェントを可能にし、データの新鮮度と完全性を、クイック統計チェック、標準レビュー、および深度構造分析を含む、深度制御された監査を通じて確保します","ko":"HTTP 프로토콜과 URL 또는 파일 경로 소스를 사용하여 콘텐츠의 정확성을 검증하고 기존 콘텐츠를 업데이트할 수 있는 에이전트를 강화하여, 데이터의 신선도와 完整性을 깊이 조정된 감사를 통해 보장합니다. 이것은 빠른 통계 확인, 표준 검토 및 깊은 구조 분석을 포함합니다.","es":"Permite a los agentes verificar la exactitud y actualizar el contenido existente utilizando protocolos HTTP y fuentes de URL o ruta de archivo, asegurando la frescura y la integridad de los datos a través de auditorías controladas por profundidad, incluyendo comprobaciones rápidas solo de estadísticas, revisiones estándar y análisis estructurales profundos","fr":"Permet aux agents de vérifier l''exactitude et de mettre à jour le contenu existant en utilisant des protocoles HTTP et des sources d''URL ou de chemin de fichier, assurant la fraîcheur et l''intégrité des données grâce à des audits contrôlés par profondeur, y compris des vérifications rapides de statistiques uniquement, des examens standard et des analyses structurelles approfondies","de":"Ermöglicht es den Agenten, die Genauigkeit zu überprüfen und den bestehenden Inhalt unter Verwendung von HTTP-Protokollen und URL- oder Dateipfadsourcen zu aktualisieren, wodurch die Datenfrische und -integrität durch tiefenkontrollierte Audits sichergestellt werden, einschließlich schneller Statistiküberprüfungen, Standardüberprüfungen und tiefer Strukturanalysen","pt":"Habilita os agentes a verificar a precisão e atualizar o conteúdo existente usando protocolos HTTP e fontes de URL ou caminho de arquivo, garantindo a frescor e integridade dos dados por meio de auditorias controladas por profundidade, incluindo verificações rápidas de estatísticas, revisões padrão e análises estruturais profundas","ru":"Наделяет агентов возможностью проверять точность и обновлять существующий контент, используя протоколы HTTP и источники URL или пути к файлам, обеспечивая свежесть и целостность данных посредством аудитов, контролируемых по глубине, включая быстрые проверки статистики, стандартные обзоры и глубокие структурные анализы","ar":"يمنح الوكلاء القدرة على التحقق من الدقة وتحديث المحتوى الحالي باستخدام بروتوكولات HTTP ومصادر URL أو مسار الملف، مما يضمن نضج البيانات وسلامتها من خلال التدقيق المضبوط بالعمق، بما في ذلك الاختبارات السريعة للإحصائيات والمراجعات القياسية والتحليلات الهيكلية العميقة"},"useCases":{"en":["Auditing website content for outdated statistics","Updating product information across multiple sources","Validating external links and sources for broken references"],"zh":["审计网站内容以便及时更新过时的统计数据","跨多个源更新产品信息","验证外部链接和源以检查断开的引用"],"ja":["ウェブサイトコンテンツの古くなった統計を更新するための監査","複数の情報源をまたいで製品情報を更新する","壊れた参照をチェックするための外部リンクおよびソースの検証"],"ko":["구식 통계를 업데이트하기 위한 웹사이트 콘텐츠 감사","여러 정보源에 걸쳐 제품 정보를 업데이트하는 것","깨어진 참조를 확인하기 위한 외부 링크 및 소스에 대한 검증"],"es":["Auditoría del contenido del sitio web para estadísticas obsoletas","Actualización de la información del producto en varias fuentes","Validación de enlaces y fuentes externas para referencias rotas"],"fr":["Audit du contenu du site Web pour des statistiques obsolètes","Mise à jour des informations de produit à partir de plusieurs sources","Validation des liens et des sources externes pour des références cassées"],"de":["Prüfung des Website-Inhalts auf veraltete Statistiken","Aktualisierung von Produktinformationen in mehreren Quellen","Überprüfung externer Links und Quellen auf fehlerhafte Verweise"],"pt":["Auditoria de conteúdo do site para estatísticas desatualizadas","Atualização de informações de produtos em várias fontes","Validação de links e fontes externas para referências quebradas"],"ru":["Аудит контента веб-сайта для устаревшей статистики","Обновление информации о продуктах из нескольких источников","Проверка внешних ссылок и источников на наличие сломанных ссылок"],"ar":["تدقيق محتوى الموقع للبيانات الإحصائية القديمة","تحديث معلومات المنتج عبر عدة مصادر","التحقق من الروابط والمصادر الخارجية للREFERENCES المكسورة"]},"limitations":{"en":["Requires access to the content source via URL or file path","Depth of audit limited to quick, standard, or deep levels"],"zh":["需要通过URL或文件路径访问内容源","监査深度仅限于快速、标准或深度级别"],"ja":["コンテンツソースへのアクセスがURLまたはファイルパス経由で必要","監査の深度はクイック、標準、またはディープレベルのみ"],"ko":["콘텐츠 소스를 URL 또는 파일 경로를 통해 액세스해야 함","감사 깊이가 빠른, 표준 또는 깊은 수준으로 제한됨"],"es":["Requiere acceso a la fuente de contenido a través de una URL o una ruta de archivo","La profundidad de la auditoría está limitada a niveles rápido, estándar o profundo"],"fr":["Nécessite un accès à la source de contenu via une URL ou un chemin de fichier","La profondeur de l''audit est limitée aux niveaux rapide, standard ou profond"],"de":["Erfordert Zugriff auf die Inhaltsquelle über eine URL oder einen Dateipfad","Die Tiefe der Prüfung ist auf die Ebenen schnell, standard oder tief begrenzt"],"pt":["Requer acesso à fonte de conteúdo via URL ou caminho de arquivo","Profundidade da auditoria limitada a níveis rápidos, padrão ou profundos"],"ru":["Требует доступа к источнику контента через URL или путь к файлу","Глубина аудита ограничена уровнями быстрого, стандартного или глубокого"],"ar":["يتطلب الوصول إلى مصدر المحتوى عبر URL أو مسار الملف","عمق التدقيق محدود بمستويات سريعة أو قياسية أو عميقة"]},"version":4},"contentHash":"e7049e7638967ac7ce3af543790c2ace6cb79491603008a4688bdfa4d21c41e1","qualityScore":20}');
