INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('airopshq/airops-claude-plugin/refresh-content', 'refresh-content', 'airopshq', 'airops-claude-plugin', 'community', 'refresh-content airopshq airops-claude-plugin community The refresh-content skill audits and updates existing content at a specified source, ensuring accuracy and freshness. It benefits developers and content creators looking to maintain up-to-date information. refresh-content是一种AI工具，用于更新内容。它可以审计内容，检查时效性元素，并进行深度更新 refresh-contentは、コンテンツを更新するAIエージェントです。コンテンツの監査、鮮度チェック、深度更新を行います refresh-content는 콘텐츠를 업데이트하는 AI 도구입니다. 콘텐츠 감사, 신선도 확인 및 깊은 업데이트를 수행합니다 Refresh-content es una habilidad que actualiza contenido existente con estadísticas y enlaces actualizados, utilizando herramientas de AI para desarrolladores Refresh-content est une compétence qui met à jour le contenu existant avec des statistiques et des liens à jour, en utilisant des outils d''IA pour les développeurs Refresh-content ist eine Fähigkeit, die bestehende Inhalte mit Statistiken und aktuellen Links aktualisiert, mit KI-Tools für Entwickler O Refresh-Content é uma ferramenta de IA que ajuda a atualizar o conteúdo, verificando estatísticas e links externos Освежение контента - это инструмент ИИ, который помогает обновлять информацию, проверяя статистику и внешние ссылки Refresh-Content هو أداة الإي الأبتكارية التي تساعد في تحديث المحتوى، من خلال التحقق من الإحصائيات والروابط الخارجية how to use refresh-content refresh-content setup guide content refresh best practices refresh-content alternative refresh-content vs content update tools install refresh-content refresh-content tutorial what is refresh-content refresh-content documentation AI工具 内容更新 内容审计 时效性检查 深度更新 refresh-content AIエージェント 内容优化 Loads and audits content from a specified URL or file path Performs freshness checks on time-sensitive elements, including statistics and claims Verifies accuracy of statistics and finds updated data if outdated Supports depth parameters, including quick, standard, and deep refresh options Analyzes document structure, including headlines, word count, and external links refresh-content is a skill that refreshes content at a specified source, auditing and updating existing information to ensure accuracy and relevance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xiaoshenming/aiteacher-monorepo/nx-plugins', 'community', 'xiaoshenming', 'aiteacher-monorepo', 'xiaoshenming/aiteacher-monorepo', 'nx-plugins', 0, 0, 20, '2026-03-07T12:46:33.690Z', '2026-03-07T13:00:41.354Z', '96659fc0ea92b133445cf5d356f4ee710396fc4da22aaa515ad7a6f7ef39a5dd', '{"id":"xiaoshenming/aiteacher-monorepo/nx-plugins","name":"nx-plugins","description":{"en":"nx-plugins is a monorepo management solution for AI Teacher projects, utilizing Nx for efficient application and service management. It benefits developers by streamlining plugin installation and listing.","zh":"nx-plugins 是 AI Teacher 项目的 Monorepo 管理工具，使用 Nx 管理多个应用和服务","ja":"nx-plugins は AIエージェントのプロジェクトの Monorepo 管理ツールで、Nx を使用して複数のアプリケーションとサービスを管理","ko":"nx-plugins는 AI 도구 프로젝트의 Monorepo 관리 도구로, Nx를 사용하여 다중 애플리케이션 및 서비스를 관리","es":"nx-plugins es una herramienta para gestionar aplicaciones y servicios en proyectos de AI. Permite instalar y configurar plugins con facilidad utilizando comandos como `pnpm nx add`","fr":"nx-plugins est un outil pour gérer des applications et des services dans les projets d''IA. Il permet d''installer et de configurer des plugins facilement en utilisant des commandes comme `pnpm nx add`","de":"nx-plugins ist ein Tool zur Verwaltung von Anwendungen und Diensten in AI-Projekten. Es ermöglicht die einfache Installation und Konfiguration von Plugins mithilfe von Befehlen wie `pnpm nx add`","pt":"O nx-plugins é uma ferramenta para gerenciar plugins no monorepo do AI Teacher, permitindo a instalação e listagem de plugins com comandos como `pnpm nx list` e `pnpm nx add`","ru":"nx-plugins - это инструмент для управления плагинами в монорепозитории AI Teacher, позволяющий устанавливать и листать плагины с помощью команд như `pnpm nx list` и `pnpm nx add` для ИИ Агентов","ar":"nx-plugins هو أداة لإدارة البرامج المساعدة في مشروع monorepo الخاص ب AI Teacher، مما يسمح بتثبيت قائمة البرامج المساعدة بأوامر مثل `pnpm nx list` و `pnpm nx add`"},"seo":{"title":{"en":"nx-plugins: Monorepo Management Setup Guide | AI Agent Skill","zh":"nx-plugins Setup Guide - AI Teacher 项目 Monorepo 管理","ja":"nx-plugins セットアップガイド - AIエージェントの Monorepo 管理","ko":"nx-plugins 설정 가이드 - AI 도구 프로젝트 Monorepo 관리","es":"Guía de configuración de nx-plugins para proyectos de AI","fr":"Guide de mise en place de nx-plugins pour les projets d''IA","de":"Einrichtungsleitfaden für nx-plugins in AI-Projekten","pt":"nx-plugins: Guia de Instalação de Plugins","ru":"nx-plugins: Руководство по установке плагинов для ИИ Агентов","ar":"nx-plugins: دليل تثبيت البرامج المساعدة"},"description":{"en":"Discover how to manage multiple apps and services with nx-plugins. Learn to install and list plugins with ease. Get started now!","zh":"了解 nx-plugins 的安装和使用方法，管理多个应用和服务，优化 Monorepo","ja":"nx-plugins のインストールと使用方法を学び、複数のアプリケーションとサービスを管理して Monorepo を最適化","ko":"nx-plugins 설치 및 사용 방법을 알아보고 다중 애플리케이션 및 서비스를 관리하여 Monorepo 최적화","es":"Descubre cómo utilizar nx-plugins para gestionar aplicaciones y servicios en proyectos de AI. Aprende a instalar y configurar plugins con facilidad","fr":"Découvrez comment utiliser nx-plugins pour gérer des applications et des services dans les projets d''IA. Apprenez à installer et à configurer des plugins fac...","de":"Erfahren Sie, wie Sie nx-plugins verwenden, um Anwendungen und Dienste in AI-Projekten zu verwalten. Lernen Sie, Plugins einfach zu installieren und zu konfi...","pt":"Aprenda a instalar e gerenciar plugins com o nx-plugins, incluindo a lista de plugins disponíveis e como adicioná-los ao seu projeto","ru":"Узнайте, как устанавливать и управлять плагинами с помощью nx-plugins, включая список доступных плагинов и как добавить их в ваш проект для ИИ Агентов","ar":"تعرف على كيفية تثبيت وإدارة البرامج المساعدة باستخدام nx-plugins، بما في ذلك قائمة البرامج المساعدة المتاحة وكيفية إضافتها إلى مشروعك"},"definition":{"en":"nx-plugins is a monorepo management system using Nx to oversee multiple applications and services, facilitating plugin installation and management.","zh":"nx-plugins 是一个用于管理 Monorepo 的工具，支持安装和使用多个插件","ja":"nx-plugins は Monorepo を管理するためのツールで、複数のプラグインのインストールと使用をサポート","ko":"nx-plugins는 Monorepo 관리를 위한 도구로, 다중 플러그인의 설치 및 사용을 지원","es":"nx-plugins es un conjunto de herramientas para gestionar aplicaciones y servicios en proyectos de AI, utilizando Nx para la administración","fr":"nx-plugins est un ensemble d''outils pour gérer des applications et des services dans les projets d''IA, en utilisant Nx pour l''administration","de":"nx-plugins ist ein Satz von Tools zur Verwaltung von Anwendungen und Diensten in AI-Projekten, die Nx für die Verwaltung verwenden","pt":"nx-plugins é uma ferramenta de gerenciamento de plugins para monorepo","ru":"nx-plugins - это инструмент для управления плагинами в монорепозитории","ar":"nx-plugins هو أداة لإدارة البرامج المساعدة في مشروع monorepo"},"features":{"en":["Lists available plugins using `pnpm nx list` command","Installs new plugins with `pnpm nx add <plugin>` command","Supports installation of specific plugins like `@nx/react`","Manages multiple applications and services within a monorepo","Utilizes Nx for efficient monorepo management"],"zh":["支持使用 pnpm nx list 列出可用插件","支持使用 pnpm nx add 安装新插件","支持使用 Nx 管理多个应用和服务","优化 Monorepo 管理","支持安装 @nx/react 等插件"],"ja":["pnpm nx list を使用して利用可能なプラグインをリスト","pnpm nx add を使用して新しいプラグインをインストール","Nx を使用して複数のアプリケーションとサービスを管理","Monorepo 管理の最適化","@nx/react などのプラグインのインストールをサポート"],"ko":["pnpm nx list를 사용하여 사용 가능한 플러그인을 목록","pnpm nx add를 사용하여 새로운 플러그인을 설치","Nx를 사용하여 다중 애플리케이션 및 서비스를 관리","Monorepo 관리 최적화","@nx/react 등의 플러그인의 설치를 지원"],"es":["Instalación de plugins con `pnpm nx add`","Listado de plugins disponibles con `pnpm nx list`","Gestión de aplicaciones y servicios con Nx","Integración con proyectos de AI","Uso de comandos de CLI para la configuración"],"fr":["Installation de plugins avec `pnpm nx add`","Liste des plugins disponibles avec `pnpm nx list`","Gestion d''applications et de services avec Nx","Intégration avec les projets d''IA","Utilisation de commandes de CLI pour la configuration"],"de":["Installation von Plugins mit `pnpm nx add`","Auflistung der verfügbaren Plugins mit `pnpm nx list`","Verwaltung von Anwendungen und Diensten mit Nx","Integration mit AI-Projekten","Verwendung von CLI-Befehlen für die Konfiguration"],"pt":["Listagem de plugins com `pnpm nx list`","Instalação de plugins com `pnpm nx add`","Gerenciamento de plugins no monorepo do AI Teacher","Compatibilidade com comandos pnpm","Integração com o ecossistema Nx"],"ru":["Список плагинов с помощью `pnpm nx list`","Установка плагинов с помощью `pnpm nx add`","Управление плагинами в монорепозитории AI Teacher для ИИ Агентов","Совместимость с командами pnpm","Интеграция с экосистемой Nx"],"ar":["قائمة البرامج المساعدة باستخدام `pnpm nx list`","تثبيت البرامج المساعدة باستخدام `pnpm nx add`","إدارة البرامج المساعدة في مشروع monorepo الخاص ب AI Teacher","التوافق مع أوامر pnpm","التكامل مع نظام Nx"]},"keywords":{"en":["how to use nx-plugins","nx-plugins setup guide","nx-plugins alternative","nx-plugins vs monorepo","installing nx-plugins","nx-plugins monorepo management"],"zh":["nx-plugins","Monorepo 管理","AI Teacher 项目","pnpm nx list","pnpm nx add","Nx 管理","插件安装","Monorepo 优化"],"ja":["nx-plugins","Monorepo 管理","AIエージェント","pnpm nx list","pnpm nx add","Nx 管理","プラグインのインストール","Monorepo 最適化"],"ko":["nx-plugins","Monorepo 관리","AI 도구","pnpm nx list","pnpm nx add","Nx 관리","플러그인 설치","Monorepo 최적화"],"es":["nx-plugins","herramientas de AI","gestión de aplicaciones","gestión de servicios","Nx","pnpm nx add","pnpm nx list","proyectos de AI","configuración de plugins"],"fr":["nx-plugins","outils d''IA","gestion d''applications","gestion de services","Nx","pnpm nx add","pnpm nx list","projets d''IA","configuration de plugins"],"de":["nx-plugins","AI-Tools","Anwendungsverwaltung","Dienstverwaltung","Nx","pnpm nx add","pnpm nx list","AI-Projekte","Plugin-Konfiguration"],"pt":["nx-plugins","gerenciamento de plugins","monorepo","AI Teacher","pnpm nx list","pnpm nx add","plugins nx","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["nx-plugins","управление плагинами","монорепозиторий","AI Teacher","ИИ Агенты","pnpm nx list","pnpm nx add","плагины nx","инструменты разработки","разработка программного обеспечения"],"ar":["nx-plugins","إدارة البرامج المساعدة","مشروع monorepo","AI Teacher","برامج مساعدة nx","pnpm nx list","pnpm nx add","أدوات تطوير","تطوير البرمجيات"]}},"owner":"xiaoshenming","repo":"aiteacher-monorepo","repoPath":"xiaoshenming/aiteacher-monorepo","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.690Z","topics":[],"category":"community","skillMd":{"name":"nx-plugins","description":"Find and add Nx plugins. USE WHEN user wants to discover available plugins, install a new plugin, or add support for a specific framework or technology to the workspace.","bodyPreview":"## Finding and Installing new plugins\n\n- List plugins: `pnpm nx list`\n- Install plugins `pnpm nx add <plugin>`. Example: `pnpm nx add @nx/react`.","body":"## Finding and Installing new plugins\n\n- List plugins: `pnpm nx list`\n- Install plugins `pnpm nx add <plugin>`. Example: `pnpm nx add @nx/react`.\n"},"lastSynced":"2026-03-07T13:00:41.354Z","agentAnalysis":{"suitability":{"en":"Ideal for Monorepo Management Agents seeking efficient plugin installation and management using Nx","zh":"适用于寻求使用 Nx 实现高效插件安装和管理的 Monorepo Management Agents","ja":"Nx を使用した効率的なプラグインのインストールと管理を求める Monorepo Management Agents に適しています","ko":"Nx를 사용하여 효율적인 플러그인 설치 및 관리를 원하는 Monorepo Management Agents 에 적합합니다","es":"Ideal para Agentes de Gestión de Monorepo que buscan una instalación y administración de plugins eficientes utilizando Nx","fr":"Idéal pour les Agents de Gestion de Monorepo recherchant une installation et une gestion de plugins efficaces à l''aide de Nx","de":"Ideal für Monorepo-Management-Agents, die eine effiziente Plugin-Installation und -Verwaltung mit Nx suchen","pt":"Ideal para Agentes de Gerenciamento de Monorepo que buscam instalação e gerenciamento de plugins eficientes usando Nx","ru":"Идеально для агентов управления монорепозиторием, ищущих эффективную установку и управление плагинами с помощью Nx","ar":"مثالي لعميل إدارة مونوربو الذي يبحث عن تثبيت وإدارة الإضافات بكفاءة باستخدام Nx"},"recommendation":{"en":"Empowers agents to streamline plugin installation and listing using pnpm and Nx, facilitating efficient application and service management with commands like `pnpm nx list` and `pnpm nx add <plugin>`","zh":"赋予代理简化使用 pnpm 和 Nx 的插件安装和列出，方便使用诸如 `pnpm nx list` 和 `pnpm nx add <plugin>` 命令的应用程序和服务管理","ja":"pnpm と Nx を使用したプラグインのインストールとリストの簡素化を代理に与え、`pnpm nx list` や `pnpm nx add <plugin>` などのコマンドを使用したアプリケーションとサービス管理を容易にします","ko":"pnpm과 Nx를 사용하여 플러그인 설치 및 목록을 단순화하여 `pnpm nx list` 및 `pnpm nx add <plugin>`과 같은 명령을 사용한 애플리케이션 및 서비스 관리를 쉽게 합니다","es":"Habilita a los agentes a simplificar la instalación y la lista de plugins utilizando pnpm y Nx, facilitando una gestión eficiente de aplicaciones y servicios con comandos como `pnpm nx list` y `pnpm nx add <plugin>`","fr":"Permet aux agents de rationaliser l''installation et la liste des plugins en utilisant pnpm et Nx, facilitant une gestion efficace des applications et des services avec des commandes comme `pnpm nx list` et `pnpm nx add <plugin>`","de":"Ermächtigt die Agenten, die Installation und Auflistung von Plugins mit pnpm und Nx zu rationalisieren, wodurch eine effiziente Anwendungs- und Dienstverwaltung mit Befehlen wie `pnpm nx list` und `pnpm nx add <plugin>` ermöglicht wird","pt":"Habilita os agentes a simplificar a instalação e listagem de plugins usando pnpm e Nx, facilitando o gerenciamento eficiente de aplicações e serviços com comandos como `pnpm nx list` e `pnpm nx add <plugin>`","ru":"Наделяет агентов возможностью упростить установку и перечисление плагинов с помощью pnpm и Nx, обеспечивая эффективное управление приложениями и сервисами с помощью команд như `pnpm nx list` и `pnpm nx add <plugin>`","ar":"يمنح العميل القدرة على تبسيط تثبيت الإضافات وقائمة باستخدام pnpm و Nx ، وتسهيل إدارة التطبيقات والخدمات بكفاءة باستخدام أوامر مثل `pnpm nx list` و `pnpm nx add <plugin>`"},"useCases":{"en":["Installing new plugins with `pnpm nx add <plugin>`","Listing available plugins using `pnpm nx list`","Streamlining monorepo management with Nx"],"zh":["使用 `pnpm nx add <plugin>` 安装新插件","使用 `pnpm nx list` 列出可用插件","使用 Nx 简化单体仓库管理"],"ja":["`pnpm nx add <plugin>` を使用して新しいプラグインをインストールする","`pnpm nx list` を使用して利用可能なプラグインをリストする","Nx を使用してモノレポ管理を簡素化する"],"ko":["`pnpm nx add <plugin>`를 사용하여 새로운 플러그인을 설치합니다","`pnpm nx list`를 사용하여 사용 가능한 플러그인을 나열합니다","Nx를 사용하여 모노레포 관리를 단순화합니다"],"es":["Instalar nuevos plugins con `pnpm nx add <plugin>`","Listar plugins disponibles utilizando `pnpm nx list`","Racionalizar la gestión de monorepo con Nx"],"fr":["Installer de nouveaux plugins avec `pnpm nx add <plugin>`","Lister les plugins disponibles en utilisant `pnpm nx list`","Rationaliser la gestion de monorepo avec Nx"],"de":["Neue Plugins mit `pnpm nx add <plugin>` installieren","Verfügbare Plugins mit `pnpm nx list` auflisten","Monorepo-Verwaltung mit Nx rationalisieren"],"pt":["Instalar novos plugins com `pnpm nx add <plugin>`","Listar plugins disponíveis usando `pnpm nx list`","Otimizar o gerenciamento de monorepo com Nx"],"ru":["Установить новые плагины с помощью `pnpm nx add <plugin>`","Перечислить доступные плагины с помощью `pnpm nx list`","Оптимизировать управление монорепозиторием с помощью Nx"],"ar":["تثبيت إضافات جديدة مع `pnpm nx add <plugin>`","قائمة الإضافات المتاحة باستخدام `pnpm nx list`","تحسين إدارة مونوربو باستخدام Nx"]},"limitations":{"en":["Requires pnpm and Nx setup","Limited to Nx-based monorepo management"],"zh":["需要 pnpm 和 Nx 设置","仅限 Nx 基础的单体仓库管理"],"ja":["pnpm と Nx の設定が必要","Nx ベースのモノレポ管理のみ"],"ko":["pnpm 및 Nx 설정이 필요합니다","Nx 기반의 모노레포 관리에만 제한됩니다"],"es":["Requiere configuración de pnpm y Nx","Limitado a la gestión de monorepo basada en Nx"],"fr":["Nécessite une configuration de pnpm et Nx","Limité à la gestion de monorepo basée sur Nx"],"de":["Benötigt pnpm- und Nx-Setup","Begrenzt auf Nx-basiertes Monorepo-Management"],"pt":["Requer configuração do pnpm e Nx","Limitado ao gerenciamento de monorepo baseado em Nx"],"ru":["Требуется настройка pnpm и Nx","Ограничен управлением монорепозиторием на основе Nx"],"ar":["يتطلب إعداد pnpm و Nx","محدود إدارة مونوربو المستندة إلى Nx"]},"version":4},"contentHash":"96659fc0ea92b133445cf5d356f4ee710396fc4da22aaa515ad7a6f7ef39a5dd","qualityScore":20}');
