INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TSGCFO/logibill-frontend/project-context', 'project-context', 'TSGCFO', 'logibill-frontend', 'community', 'project-context TSGCFO logibill-frontend community The project-context skill helps developers summarize project goals, core constraints, and relevant dependencies. It benefits developers by providing a concise summary for future tasks. 项目上下文是指项目的目标、核心约束和相关依赖。使用项目上下文可以提高开发效率 プロジェクトコンテキストとは、プロジェクトの目標、コア制約、関連する依存関係を指します。プロジェクトコンテキストを使用することで開発効率を向上 프로젝트 컨텍스트는 프로젝트의 목표, 핵심 제약 및 관련 의존성을 말합니다. 프로젝트 컨텍스트를 사용하면 개발 효율성을 높일 수 있습니다 El contexto de proyecto resume metas, restricciones y dependencias clave para mejorar la eficiencia del desarrollo con herramientas de inteligencia artificial Le contexte de projet résume les objectifs, les contraintes et les dépendances clés pour améliorer l''efficacité du développement avec des outils d''intelligence artificielle Der Projekt-Kontext fasst Ziele, Einschränkungen und Schlüsselabhängigkeiten zusammen, um die Entwicklungseffizienz mit KI-Tools zu verbessern O contexto de projeto resume metas, restrições e dependências. Aprenda a configurar com ferramentas de inteligência artificial. Контекст проекта суммирует цели, ограничения и зависимости. Узнайте, как настроить с помощью ИИ Агентов. سياق المشروع يلخص الأهداف والقيود والاعتماديات. تعرف على كيفية إعدادها باستخدام أدوات الذكاء الاصطناعي. how to use project-context project-context setup guide what is project-context project-context alternative project-context vs other skills project-context install project-context for AI agents project management with project-context project-context tutorial 项目上下文 AIエージェント 项目管理 开发效率 项目目标 核心约束 相关依赖 架构决策 验证步骤 Summarizes project goals and core constraints Identifies relevant dependencies and architecture decisions Calls out shared conventions and validation steps Provides a concise summary for reuse in future tasks Highlights key project information for efficient management project-context is a skill that summarizes project goals, core constraints, and relevant dependencies, highlighting architecture decisions and validation steps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ZsZs/processpuzzle/nx-plugins', 'community', 'ZsZs', 'processpuzzle', 'ZsZs/processpuzzle', 'nx-plugins', 0, 0, 20, '2026-03-07T01:49:01.730Z', '2026-03-07T02:50:09.122Z', '96659fc0ea92b133445cf5d356f4ee710396fc4da22aaa515ad7a6f7ef39a5dd', '{"id":"ZsZs/processpuzzle/nx-plugins","name":"nx-plugins","description":{"en":"The nx-plugins skill allows developers to manage plugins using commands like `pnpm nx list` and `pnpm nx add`. It benefits developers working with Nx projects.","zh":"nx-plugins 提供了方便的插件安装和管理功能，通过 `pnpm nx` 命令即可轻松安装和管理插件","ja":"nx-plugins は便利なプラグインのインストールと管理機能を提供し、`pnpm nx` コマンドで簡単にプラグインをインストールと管理できます","ko":"nx-plugins 는 편리한 플러그인 설치 및 관리 기능을 제공하며 `pnpm nx` 명령어로 쉽게 플러그인을 설치하고 관리할 수 있습니다","es":"nx-plugins es una herramienta para encontrar e instalar plugins de nx. Utiliza pnpm nx para listar e instalar plugins como @nx/react","fr":"nx-plugins est un outil pour trouver et installer des plugins nx. Utilisez pnpm nx pour lister et installer des plugins tels que @nx/react","de":"nx-plugins ist ein Tool zum Finden und Installieren von nx-Plugins. Verwenden Sie pnpm nx, um Plugins wie @nx/react zu listen und zu installieren","pt":"O nx-plugins é uma ferramenta para gerenciar plugins no CLI. Ele permite que os desenvolvedores instalem e gerenciem plugins facilmente","ru":"nx-plugins - это инструмент для управления плагинами в CLI. Он позволяет разработчикам устанавливать и управлять плагинами легко","ar":"nx-plugins هو أداة لإدارة البرامج المساعدة في واجهة سطر الأوامر. يسمح للمطورين بتثبيت وإدارة البرامج المساعدة بسهولة"},"seo":{"title":{"en":"nx-plugins: Plugin Management Setup Guide | AI Agent Skill","zh":"nx-plugins 安装指南 - 优化开发工作流","ja":"nx-plugins セットアップガイド - 開発ワークフローを最適化","ko":"nx-plugins 설정 가이드 - 개발 워크플로우 최적화","es":"Guía de configuración de nx-plugins para desarrolladores","fr":"Guide de configuration de nx-plugins pour les développeurs","de":"Einrichtungsleitfaden für nx-plugins-Entwickler","pt":"Guia de Configuração de nx-plugins para Desenvolvedores","ru":"Руководство по настройке nx-plugins для разработчиков","ar":"دليل إعداد nx-plugins للمطورين"},"description":{"en":"Discover how to find and install new plugins with nx-plugins. Learn the commands to list and add plugins, and get started with your project today!","zh":"了解 nx-plugins 的安装和使用方法，优化您的开发工作流，并提高生产力","ja":"nx-plugins のインストールと使用方法を学び、開発ワークフローを最適化して生産性を向上させます","ko":"nx-plugins 설치 및 사용 방법을 알아보고 개발 워크플로우를 최적화하여 생산성을 향상시키세요","es":"Descubre cómo encontrar e instalar nuevos plugins de nx con pnpm nx. Mejora tu productividad con nuestras mejores prácticas","fr":"Découvrez comment trouver et installer de nouveaux plugins nx avec pnpm nx. Améliorez votre productivité avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie neue nx-Plugins mit pnpm nx finden und installieren. Steigern Sie Ihre Produktivität mit unseren Best Practices","pt":"Aprenda a instalar e gerenciar plugins nx com facilidade. Descubra como usar o CLI para adicionar funcionalidades ao seu projeto","ru":"Узнайте, как установить и управлять плагинами nx с легкостью. Откройте для себя, как использовать CLI для добавления функций к вашему проекту","ar":"تعلم كيفية تثبيت وإدارة البرامج المساعدة nx بسهولة. اكتشف كيفية استخدام واجهة سطر الأوامر لتعزيز مشروعك"},"definition":{"en":"nx-plugins is a skill for managing plugins in Nx projects, enabling developers to easily find and install new plugins.","zh":"nx-plugins 是一个用于管理和安装 nx 项目插件的工具","ja":"nx-plugins は、nx プロジェクトのプラグインを管理およびインストールするためのツールです","ko":"nx-plugins 는 nx 프로젝트의 플러그인을 관리 및 설치하기 위한 도구입니다","es":"nx-plugins es un conjunto de herramientas para gestionar plugins de nx, permitiendo a los desarrolladores encontrar e instalar nuevos plugins","fr":"nx-plugins est un ensemble d''outils pour gérer des plugins nx, permettant aux développeurs de trouver et d''installer de nouveaux plugins","de":"nx-plugins ist eine Sammlung von Tools zur Verwaltung von nx-Plugins, mit denen Entwickler neue Plugins finden und installieren können","pt":"nx-plugins é um conjunto de ferramentas para gerenciar plugins no CLI","ru":"nx-plugins - это набор инструментов для управления плагинами в CLI","ar":"nx-plugins هو مجموعة من الأدوات لإدارة البرامج المساعدة في واجهة سطر الأوامر"},"features":{"en":["Lists available plugins using `pnpm nx list` command","Installs plugins using `pnpm nx add` command","Supports installation of specific plugins, such as `@nx/react`","Enables easy management of plugins in Nx projects","Utilizes pnpm for package management"],"zh":["支持通过 `pnpm nx list` 命令列出可用插件","支持通过 `pnpm nx add` 命令安装插件","例如，安装 React 插件：`pnpm nx add @nx/react`","方便的插件管理功能","提高开发工作流的效率"],"ja":["利用可能なプラグインを `pnpm nx list` コマンドで列挙する機能","プラグインを `pnpm nx add` コマンドでインストールする機能","例：React プラグインのインストール：`pnpm nx add @nx/react`","便利なプラグイン管理機能","開発ワークフローの効率化"],"ko":["사용 가능한 플러그인을 `pnpm nx list` 명령어로列挙하는 기능","플러그인을 `pnpm nx add` 명령어로 설치하는 기능","예：React 플러그인 설치：`pnpm nx add @nx/react`","편리한 플러그인 관리 기능","개발 워크플로우의 효율화"],"es":["Lista de plugins disponibles con pnpm nx list","Instalación de plugins con pnpm nx add","Compatibilidad con plugins como @nx/react","Gestión de dependencias con pnpm","Integración con la línea de comandos de nx"],"fr":["Liste de plugins disponibles avec pnpm nx list","Installation de plugins avec pnpm nx add","Compatibilité avec des plugins tels que @nx/react","Gestion des dépendances avec pnpm","Intégration avec la ligne de commande de nx"],"de":["Liste verfügbarer Plugins mit pnpm nx list","Installation von Plugins mit pnpm nx add","Kompatibilität mit Plugins wie @nx/react","Verwaltung von Abhängigkeiten mit pnpm","Integration mit der Befehlszeile von nx"],"pt":["Listar plugins disponíveis com `pnpm nx list`","Instalar plugins com `pnpm nx add <plugin>`","Suporte a plugins como @nx/react","Gerenciamento de plugins via CLI","Integração com projetos existentes"],"ru":["Список доступных плагинов с помощью `pnpm nx list`","Установка плагинов с помощью `pnpm nx add <plugin>`","Поддержка плагинов как @nx/react","Управление плагинами через CLI","Интеграция с существующими проектами"],"ar":["قائمة البرامج المساعدة المتاحة باستخدام `pnpm nx list`","تثبيت البرامج المساعدة باستخدام `pnpm nx add <plugin>`","دعم البرامج المساعدة مثل @nx/react","إدارة البرامج المساعدة عبر واجهة سطر الأوامر","التكامل مع المشاريع الحالية"]},"keywords":{"en":["how to use nx-plugins","nx-plugins setup guide","nx-plugins install","what is nx-plugins","nx-plugins alternative","nx-plugins vs npm"],"zh":["nx-plugins","nx 项目","插件安装","插件管理","开发工作流","pnpm nx","React 插件","开发工具","开发效率"],"ja":["nx-plugins","nx プロジェクト","プラグインのインストール","プラグインの管理","開発ワークフロー","pnpm nx","React プラグイン","開発ツール","開発効率"],"ko":["nx-plugins","nx 프로젝트","플러그인 설치","플러그인 관리","개발 워크플로우","pnpm nx","React 플러그인","개발 도구","개발 효율"],"es":["nx-plugins","pnpm nx","instalación de plugins","gestión de dependencias","desarrollo de software","herramientas de desarrollo","plugins de nx","nx react"],"fr":["nx-plugins","pnpm nx","installation de plugins","gestion des dépendances","développement de logiciels","outils de développement","plugins nx","nx react"],"de":["nx-plugins","pnpm nx","Installation von Plugins","Verwaltung von Abhängigkeiten","Software-Entwicklung","Entwicklungstools","nx-Plugins","nx react"],"pt":["nx-plugins","gerenciamento de plugins","CLI","pnpm nx list","pnpm nx add","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["nx-plugins","управление плагинами","CLI","pnpm nx list","pnpm nx add","разработка программного обеспечения","инструменты разработки"],"ar":["nx-plugins","إدارة البرامج المساعدة","واجهة سطر الأوامر","pnpm nx list","pnpm nx add","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ZsZs","repo":"processpuzzle","repoPath":"ZsZs/processpuzzle","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.730Z","topics":[],"category":"community","skillMd":{"name":"nx-plugins","description":"Find and add Nx plugins. USE WHEN user wants to discover available plugins, install a new plugin, or add support for a specific framework or technology to the workspace.","bodyPreview":"## Finding and Installing new plugins\n\n- List plugins: `pnpm nx list`\n- Install plugins `pnpm nx add <plugin>`. Example: `pnpm nx add @nx/react`.","body":"## Finding and Installing new plugins\n\n- List plugins: `pnpm nx list`\n- Install plugins `pnpm nx add <plugin>`. Example: `pnpm nx add @nx/react`.\n"},"lastSynced":"2026-03-07T02:50:09.122Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents working with Nx projects, needing streamlined plugin management capabilities.","zh":"适合与 Nx 项目合作的开发代理，需要简化的插件管理能力。","ja":"Nx プロジェクトで作業する開発エージェントに適しています。ストリームライン化されたプラグイン管理機能が必要です。","ko":"Nx 프로젝트에서 작업하는 개발 에이전트에게 적합하며, 간소화된 플러그인 관리 기능이 필요합니다.","es":"Ideal para Agentes de Desarrollo que trabajan con proyectos Nx, necesitando capacidades de administración de plugins optimizadas.","fr":"Idéal pour les agents de développement travaillant sur des projets Nx, ayant besoin de capacités de gestion de plugins rationalisées.","de":"Ideal für Entwicklungsbots, die mit Nx-Projekten arbeiten und optimierte Plugin-Verwaltungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Desenvolvimento que trabalham com projetos Nx, necessitando de capacidades de gerenciamento de plugins simplificadas.","ru":"Идеально для агентов разработки, работающих с проектами Nx, которым необходимы упрощенные возможности управления плагинами.","ar":"مثالية للوكلاء النمطية الذين يعملون مع مشاريع Nx ، الذين يحتاجون إلى إمكانيات إدارة الإضافات المبسطة."},"recommendation":{"en":"Empowers agents to efficiently manage plugins using commands like `pnpm nx list` and `pnpm nx add`, enabling seamless integration of libraries like `@nx/react` and facilitating project setup with protocols like pnpm.","zh":"赋予代理高效管理插件的能力，使用诸如 `pnpm nx list` 和 `pnpm nx add` 的命令，实现诸如 `@nx/react` 之类的库的无缝集成，并通过诸如 pnpm 之类的协议促进项目设置。","ja":"エージェントが `pnpm nx list` や `pnpm nx add` などのコマンドを使用してプラグインを効率的に管理できるようにし、`@nx/react` などのライブラリのシームレスな統合を可能にし、pnpm などのプロトコルを使用したプロジェクトの設定を促進します。","ko":"에이전트가 `pnpm nx list` 및 `pnpm nx add`와 같은 명령을 사용하여 플러그인을 효율적으로 관리할 수 있도록 하여, `@nx/react`와 같은 라이브러리의 무결점 통합을 가능하게 하고, pnpm과 같은 프로토콜을 사용한 프로젝트 설정을 촉진합니다.","es":"Habilita a los agentes a gestionar plugins de manera eficiente utilizando comandos como `pnpm nx list` y `pnpm nx add`, permitiendo una integración sin problemas de bibliotecas como `@nx/react` y facilitando la configuración del proyecto con protocolos como pnpm.","fr":"Permet aux agents de gérer efficacement les plugins en utilisant des commandes comme `pnpm nx list` et `pnpm nx add`, permettant une intégration transparente de bibliothèques comme `@nx/react` et facilitant la configuration du projet avec des protocoles comme pnpm.","de":"Ermöglicht es Agenten, Plugins effizient zu verwalten, indem sie Befehle wie `pnpm nx list` und `pnpm nx add` verwenden, wodurch eine nahtlose Integration von Bibliotheken wie `@nx/react` ermöglicht wird und die Projektsetup mit Protokollen wie pnpm erleichtert wird.","pt":"Habilita os agentes a gerenciar plugins de forma eficiente usando comandos como `pnpm nx list` e `pnpm nx add`, permitindo integração transparente de bibliotecas como `@nx/react` e facilitando a configuração do projeto com protocolos como pnpm.","ru":"Наделяет агентов возможностью эффективно управлять плагинами, используя команды типа `pnpm nx list` и `pnpm nx add`, что позволяет обеспечить бесшовную интеграцию библиотек типа `@nx/react` и облегчает настройку проекта с протоколами типа pnpm.","ar":"تمكين الوكلاء من إدارة الإضافات بفعالية باستخدام أوامر مثل `pnpm nx list` و `pnpm nx add` ، مما يتيح دمج متوافق لbibliotecas مثل `@nx/react` وتسهيل إعداد المشروع بروتوكولات مثل pnpm."},"useCases":{"en":["Listing available plugins with `pnpm nx list`","Installing specific plugins using `pnpm nx add <plugin>`","Managing project dependencies with Nx"],"zh":["使用 `pnpm nx list` 列出可用的插件","使用 `pnpm nx add <plugin>` 安装特定的插件","使用 Nx 管理项目依赖"],"ja":["`pnpm nx list` を使用して利用可能なプラグインをリストする","`pnpm nx add <plugin>` を使用して特定のプラグインをインストールする","Nx を使用してプロジェクトの依存関係を管理する"],"ko":["`pnpm nx list`를 사용하여 사용 가능한 플러그인을 나열하는 것","`pnpm nx add <plugin>`를 사용하여 특정 플러그인을 설치하는 것","Nx를 사용하여 프로젝트 종속성을 관리하는 것"],"es":["Listar plugins disponibles con `pnpm nx list`","Instalar plugins específicos utilizando `pnpm nx add <plugin>`","Administrar dependencias del proyecto con Nx"],"fr":["Lister les plugins disponibles avec `pnpm nx list`","Installer des plugins spécifiques en utilisant `pnpm nx add <plugin>`","Gérer les dépendances du projet avec Nx"],"de":["Verfügbare Plugins mit `pnpm nx list` auflisten","Spezifische Plugins mit `pnpm nx add <plugin>` installieren","Projekt-Abhängigkeiten mit Nx verwalten"],"pt":["Listar plugins disponíveis com `pnpm nx list`","Instalar plugins específicos usando `pnpm nx add <plugin>`","Gerenciar dependências do projeto com Nx"],"ru":["Перечисление доступных плагинов с помощью `pnpm nx list`","Установка определенных плагинов, используя `pnpm nx add <plugin>`","Управление зависимостями проекта с помощью Nx"],"ar":["قائمة الإضافات المتاحة باستخدام `pnpm nx list`","تثبيت الإضافات المحددة باستخدام `pnpm nx add <plugin>`","إدارة التبعيات للمشروع مع Nx"]},"limitations":{"en":["Requires Nx project setup","Dependent on pnpm package manager"],"zh":["需要 Nx 项目设置","依赖于 pnpm 包管理器"],"ja":["Nx プロジェクトの設定が必要","pnpm パッケージマネージャーに依存"],"ko":["Nx 프로젝트 설정이 필요","pnpm 패키지 관리에 의존"],"es":["Requiere configuración del proyecto Nx","Dependiente del administrador de paquetes pnpm"],"fr":["Nécessite une configuration de projet Nx","Dépendant du gestionnaire de paquets pnpm"],"de":["Benötigt Nx-Projektsetup","Abhängig vom Paket-Manager pnpm"],"pt":["Exige configuração do projeto Nx","Dependente do gerenciador de pacotes pnpm"],"ru":["Требует настройки проекта Nx","Зависит от менеджера пакетов pnpm"],"ar":["يتطلب إعداد مشروع Nx","يعتمد على مدير الحزم pnpm"]},"version":4},"contentHash":"96659fc0ea92b133445cf5d356f4ee710396fc4da22aaa515ad7a6f7ef39a5dd","qualityScore":20}');
