INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ZsZs/processpuzzle/nx-plugins', 'nx-plugins', 'ZsZs', 'processpuzzle', 'community', 'nx-plugins ZsZs processpuzzle community The nx-plugins skill allows developers to manage plugins using commands like `pnpm nx list` and `pnpm nx add`. It benefits developers working with Nx projects. nx-plugins 提供了方便的插件安装和管理功能，通过 `pnpm nx` 命令即可轻松安装和管理插件 nx-plugins は便利なプラグインのインストールと管理機能を提供し、`pnpm nx` コマンドで簡単にプラグインをインストールと管理できます nx-plugins 는 편리한 플러그인 설치 및 관리 기능을 제공하며 `pnpm nx` 명령어로 쉽게 플러그인을 설치하고 관리할 수 있습니다 nx-plugins es una herramienta para encontrar e instalar plugins de nx. Utiliza pnpm nx para listar e instalar plugins como @nx/react nx-plugins est un outil pour trouver et installer des plugins nx. Utilisez pnpm nx pour lister et installer des plugins tels que @nx/react nx-plugins ist ein Tool zum Finden und Installieren von nx-Plugins. Verwenden Sie pnpm nx, um Plugins wie @nx/react zu listen und zu installieren O nx-plugins é uma ferramenta para gerenciar plugins no CLI. Ele permite que os desenvolvedores instalem e gerenciem plugins facilmente nx-plugins - это инструмент для управления плагинами в CLI. Он позволяет разработчикам устанавливать и управлять плагинами легко nx-plugins هو أداة لإدارة البرامج المساعدة في واجهة سطر الأوامر. يسمح للمطورين بتثبيت وإدارة البرامج المساعدة بسهولة how to use nx-plugins nx-plugins setup guide nx-plugins install what is nx-plugins nx-plugins alternative nx-plugins vs npm nx-plugins nx 项目 插件安装 插件管理 开发工作流 pnpm nx React 插件 开发工具 开发效率 Lists available plugins using `pnpm nx list` command Installs plugins using `pnpm nx add` command Supports installation of specific plugins, such as `@nx/react` Enables easy management of plugins in Nx projects Utilizes pnpm for package management nx-plugins is a skill for managing plugins in Nx projects, enabling developers to easily find and install new plugins.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mae616/ai-template/react', 'community', 'mae616', 'ai-template', 'mae616/ai-template', 'react', 0, 0, 18, '2026-03-03T13:05:36.983Z', '2026-03-03T13:23:46.896Z', '47811813e3043fa4017f0939cfbeab8f2ee06ed5e6ccd3c138b604bbdf3f98a2', '{"id":"mae616/ai-template/react","name":"react","description":{"zh":"React是一个用于AI驱动的敏捷开发的模板，帮助开发者提高开发效率","ja":"Reactは、AIエージェントのコンテキスト駆動開発用テンプレートです","ko":"React는 AI 에이전트의 애자일 개발 템플릿으로 개발 효율성을 높입니다","es":"React es una herramienta de desarrollo ágil que utiliza plantillas de código y promtps de especificación de AI para mejorar la eficiencia","fr":"React est un outil de développement agile qui utilise des modèles de code et des promtps de spécification d''IA pour améliorer l''efficacité","de":"React ist ein Tool für agiles Entwicklung, das Code-Vorlagen und AI-Spezifikationsprompts verwendet, um die Effizienz zu verbessern","pt":"O React é uma biblioteca JavaScript para construir interfaces de usuário, agora integrada à inteligência artificial para desenvolvedores.","ru":"React - это библиотека JavaScript для построения интерфейсов пользователя, теперь интегрированная с ИИ для разработчиков.","ar":"رياكت هو مكتبة جافاسكريبت لإنشاء واجهات المستخدم، الآن متوفرة مع الذكاء الاصطناعي لمطوري البرمجيات.","en":"Feedback only OSS。コンテキスト駆動開発(アジャイル仕様開発)用テンプレート。AIの思考仕様のプロンプト。"},"seo":{"title":{"zh":"AI智能工具React：敏捷开发模板","ja":"AIエージェントのReact：コンテキスト駆動開発用テンプレート","ko":"AI 에이전트 React: 애자일 개발 템플릿","es":"Herramientas de AI: React para desarrollo ágil","fr":"Outils d''IA: React pour le développement agile","de":"KI-Tools: React für agiles Entwicklung","pt":"Ferramentas de Inteligência Artificial: React para Desenv...","ru":"ИИ Агенты: React для Разработчиков","ar":"أدوات الذكاء الاصطناعي: رياكت لمطوري البرمجيات","en":"react"},"description":{"zh":"React是一个用于AI驱动的敏捷开发的模板，帮助开发者提高开发效率","ja":"Reactは、AIエージェントのコンテキスト駆動開発用テンプレートです","ko":"React는 AI 에이전트의 애자일 개발 템플릿으로 개발 효율성을 높입니다","es":"React es una herramienta de desarrollo ágil que utiliza plantillas de código y promtps de especificación de AI para mejorar la eficiencia","fr":"React est un outil de développement agile qui utilise des modèles de code et des promtps de spécification d''IA pour améliorer l''efficacité","de":"React ist ein Tool für agiles Entwicklung, das Code-Vorlagen und AI-Spezifikationsprompts verwendet, um die Effizienz zu verbessern","pt":"O React é uma biblioteca JavaScript para construir interfaces de usuário, agora integrada à inteligência artificial para desenvolvedores.","ru":"React - это библиотека JavaScript для построения интерфейсов пользователя, теперь интегрированная с ИИ для разработчиков.","ar":"رياكت هو مكتبة جافاسكريبت لإنشاء واجهات المستخدم، الآن متوفرة مع الذكاء الاصطناعي لمطوري البرمجيات.","en":"Feedback only OSS。コンテキスト駆動開発(アジャイル仕様開発)用テンプレート。AIの思考仕様のプロンプト。"},"definition":{"en":"Feedback only OSS。コンテキスト駆動開発(アジャイル仕様開発)用テンプレート。AIの思考仕様のプロンプト。"},"features":{"zh":["支持AI驱动的敏捷开发","提高开发效率","提供模板化的开发体验","集成AI思考仕様的プロンプト","支持コンテキスト駆動開発"],"ja":["AIエージェントのコンテキスト駆動開発をサポート","開発効率の向上","テンプレート化された開発体験を提供","AIの思考仕様のプロンプトを統合","コンテキスト駆動開発をサポート"],"ko":["AI 에이전트의 애자일 개발을 지원","개발 효율성을 높임","템플릿화된 개발 경험을 제공","AI의思考仕様의 프로ンプ트를 통합","애자일 개발을 지원"],"es":["Plantillas de código para desarrollo ágil","Promtps de especificación de AI para mejorar la eficiencia","Integración con herramientas de desarrollo existentes","Flexibilidad y personalización","Soporte para desarrollo de aplicaciones web y móviles"],"fr":["Modèles de code pour le développement agile","Promtps de spécification d''IA pour améliorer l''efficacité","Intégration avec les outils de développement existants","Flexibilité et personnalisation","Prise en charge du développement d''applications web et mobiles"],"de":["Code-Vorlagen für agiles Entwicklung","AI-Spezifikationsprompts für verbesserte Effizienz","Integration mit bestehenden Entwicklungstools","Flexibilität und Anpassungsfähigkeit","Unterstützung für die Entwicklung von Web- und Mobilanwendungen"],"pt":["Desenvolvimento de interfaces de usuário com React","Integração com inteligência artificial para melhorias de desempenho","Suporte a desenvolvimento ágil com ferramentas de AI","Criação de templates personalizados para projetos de desenvolvimento","Suporte a múltiplos ambientes de desenvolvimento"],"ru":["Разработка интерфейсов пользователя с помощью React","Интеграция с ИИ для улучшения производительности","Поддержка гибкой разработки с помощью инструментов ИИ","Создание пользовательских шаблонов для проектов разработки","Поддержка нескольких сред разработки"],"ar":["إنشاء واجهات المستخدم مع رياكت","التكامل مع الذكاء الاصطناعي لتحسين الأداء","دعم التطوير المتكيف مع أدوات الذكاء الاصطناعي","إنشاء قوالب مخصصة لمشاريع التطوير","دعم بيئات متعددة للتطوير"]},"keywords":{"zh":["如何使用React进行AI驱动的敏捷开发","React的优点","React vs 其他AI开发工具","React安装指南","React开发教程","AI驱动的敏捷开发的优势"],"ja":["AIエージェントのReactを使用する方法","Reactの利点","React vs その他のAI開発ツール","Reactのインストールガイド","Reactの開発チュートリアル","AIエージェントのコンテキスト駆動開発の利点"],"ko":["AI 에이전트의 React를 사용하는 방법","React의 장점","React vs 다른 AI 개발 도구","React 설치 가이드","React 개발 튜토리얼","AI 에이전트의 애자일 개발의 장점"],"es":["herramientas de AI","desarrollo ágil","React","plantillas de código","promtps de especificación de AI","cómo usar React","qué es React","React vs Angular","instalación de React","guía de configuración de React"],"fr":["outils d''IA","développement agile","React","modèles de code","promtps de spécification d''IA","comment utiliser React","qu''est-ce que React","React vs Angular","installation de React","guide de configuration de React"],"de":["KI-Tools","agiles Entwicklung","React","Code-Vorlagen","AI-Spezifikationsprompts","wie man React verwendet","was ist React","React vs Angular","Installation von React","Konfigurationsanleitung für React"],"pt":["react para desenvolvedores","ferramentas de inteligência artificial para desenvolvimento","como usar react com ai","react vs angular","instalar react","guias de configuração do react"],"ru":["React для разработчиков","инструменты ИИ для разработки","как использовать React с ИИ","React vs Angular","установить React","руководства по настройке React"],"ar":["رياكت لمطوري البرمجيات","أدوات الذكاء الاصطناعي لتطوير البرمجيات","كيفية استخدام رياكت مع الذكاء الاصطناعي","رياكت مقابل أنجولار","تثبيت رياكت","دليل إعداد رياكت"]}},"owner":"mae616","repo":"ai-template","repoPath":"mae616/ai-template","stars":0,"forks":0,"updatedAt":"2026-03-03T13:05:36.983Z","topics":[],"category":"community","skillMd":{"name":"react","description":"React/Next.jsのプロジェクトで、UI=計算モデル（コンポーネント/状態/レンダリング）を軸に、設計・実装・レビュー・性能改善の判断を整理する。doc/input/rdd.md に「技術スタック React」または「技術スタック Next.js」があるリポジトリ、あるいはReactの状態管理/レンダリング/Server Components/SSR/Streaming/バンドル/パフォーマンス相談で使う。","bodyPreview":"# React UI Computation Skill\n\n## 公式情報\n- [React](https://react.dev)\n- [React Docs](https://react.dev/learn)\n- [Next.js](https://nextjs.org)\n- [Next.js Docs](https://nextjs.org/docs)\n\n## 発火条件（リポジトリ判定）\n- まず `doc/input/rdd.md` を確認し、`技術スタック React` または `技術スタック Next.js` があれば、このSkillの方針をデフォルト採用する。\n- 記載がなくても、依頼がReact/Next/コンポーネント設計/状態管理/レンダリング/SSR/パフォーマンス最適化なら適用する。\n\n## このSkillの基本方針（まえちゃん向けの“整理軸”）\n- 基本方針: UIは「状態→描画」の計算。コンポーネントは計算単位として設計する。\n- レンダリング: SSR/CSR/SSG/Streamingは“いつUIを完成させるか”の設計。要件（SEO/速度/更新頻度）から","body":"# React UI Computation Skill\n\n## 公式情報\n- [React](https://react.dev)\n- [React Docs](https://react.dev/learn)\n- [Next.js](https://nextjs.org)\n- [Next.js Docs](https://nextjs.org/docs)\n\n## 発火条件（リポジトリ判定）\n- まず `doc/input/rdd.md` を確認し、`技術スタック React` または `技術スタック Next.js` があれば、このSkillの方針をデフォルト採用する。\n- 記載がなくても、依頼がReact/Next/コンポーネント設計/状態管理/レンダリング/SSR/パフォーマンス最適化なら適用する。\n\n## このSkillの基本方針（まえちゃん向けの“整理軸”）\n- 基本方針: UIは「状態→描画」の計算。コンポーネントは計算単位として設計する。\n- レンダリング: SSR/CSR/SSG/Streamingは“いつUIを完成させるか”の設計。要件（SEO/速度/更新頻度）から選ぶ。\n- 境界: 「クライアントに送るJS」と「サーバーに置く処理」の境界を意識する。送らない最適化は強い。\n- パフォーマンス: 体感（LCP/INP/CLS）に効く順に当てる。JS送信量・画像・フォント・3rd partyを疑う。\n- 参考: [React](https://react.dev) / [Next.js](https://nextjs.org)\n\n## 思想（判断ルール）\n1. コンポーネントは「UI部品」ではなく「UI計算の単位」。責務と境界を小さく保つ。\n2. stateは最小に。stateの置き場所は“依存する範囲の最小の上”に置く（持ち上げすぎない/分散しすぎない）。\n3. 再レンダリングは悪ではないが、無意味な再計算は避ける。計算コスト/DOMコスト/ネットワークコストを分けて見る。\n4. “どこまでクライアントに送るか”は設計。初期表示と操作体験の優先順位で決める。\n5. Next.js（App Router）文脈では、Server/Clientの境界（RSC/Client Component）を「責務分離」として扱う。魔法ではなく制約の設計。\n\n## 進め方（質問テンプレ）\n最初に必ず以下を確認してから提案する：\n- これは「サイト」寄り？「アプリ」寄り？（状態・操作が多いか）\n- 重要なのは初期表示？操作体験？SEO？（優先順位）\n- データはどこから？更新頻度は？（キャッシュ可能性）\n- 速度の課題は何？（LCP/INP/CLS/TTFB のどれ）\n- ルーティング/フォーム/認証はある？（責務分離の必要性）\n\n## 出力フォーマット（必ずこの順）\n1. 推奨方針（1〜3行）\n2. 理由（Web制約 / DX / 保守性 / 性能）\n3. 設計案（コンポーネント境界 / state配置 / データ取得 / レンダリング戦略 / バンドル・資産 / キャッシュ）\n4. チェックリスト（実装前に確認）\n5. 落とし穴（避けるべき）\n6. 次アクション（小さく試す順）\n\n## チェックリスト（設計/実装レビュー用）\n### コンポーネント境界\n- [ ] コンポーネントの責務が大きすぎないか（表示・状態・副作用・データ取得が混ざりすぎてないか）\n- [ ] propsの受け渡しが深すぎないか（必要ならContextや分割を検討）\n- [ ] 再利用のための抽象化が早すぎないか（読みにくさが勝ってないか）\n\n### state・副作用\n- [ ] stateが最小か（derived stateを持ってないか）\n- [ ] effectは「同期の穴埋め」になっていないか（まずデータフローを疑う）\n- [ ] 非同期処理の責務（ロード/エラー/リトライ）がUIと分離できているか\n\n### レンダリング・配信\n- [ ] SSR/CSR/SSG/Streamingの選択理由が説明できるか\n- [ ] クライアントに送るJS量を説明できるか（“送らない”選択肢を検討したか）\n- [ ] 画像/フォント/3rd partyが体感を壊していないか\n\n### Next.js（該当時）\n- [ ] Server/Client境界が妥当か（Clientに寄せすぎてないか）\n- [ ] データ取得をUIの近くに置きつつ、秘密情報がクライアントに漏れないか\n- [ ] キャッシュ方針（更新頻度/再生成/無効化）が言語化できるか\n\n## よくある落とし穴\n- 「とりあえず全部Client」にして送信量が膨らみ、初期表示とINPが悪化する\n- stateが持ち上がりすぎて、少しの変更で全体が再レンダリングされる設計になる\n- derived stateを増やして、同期ズレ・バグ・複雑性が増える\n- useEffectで辻褄合わせを始めて、原因（データフロー/責務）が見えなくなる\n- パフォーマンス改善が“メモ化の儀式”になり、真因（画像/3rd party/通信）が放置される\n"},"lastSynced":"2026-03-03T13:23:46.896Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient UI component design and state management with React","zh":"非常适合需要高效UI组件设计和状态管理的前端代理，使用React","ja":"Reactを使用して効率的なUIコンポーネント設計と状態管理が必要なフロントエンドエージェントに最適","ko":"리액트를 사용하여 효율적인 UI 컴포넌트 설계 및 상태 관리가 필요한 프론트엔드 에이전트에게 최적","es":"Perfecto para Agentes de Frontend que necesitan un diseño de componentes de interfaz de usuario eficiente y gestión de estado con React","fr":"Parfait pour les agents Frontend qui ont besoin d''une conception de composants d''interface utilisateur efficace et d''une gestion d''état avec React","de":"Perfekt für Frontend-Agents, die eine effiziente Benutzeroberflächen-Komponenten-Design und Zustandsverwaltung mit React benötigen","pt":"Perfeito para Agentes Frontend que necessitam de design de componentes de UI eficientes e gerenciamento de estado com React","ru":"Идеально подходит для фронтенд-агентов, которым требуется эффективный дизайн компонентов UI и управление состоянием с помощью React","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تصميم عناصر واجهة المستخدم الفعال ومديرية الحالة مع React"},"recommendation":{"en":"Empowers agents to design and optimize UI components using React, leveraging Next.js for server-side rendering and static site generation, and streamlining state management for enhanced performance","zh":"赋予代理设计和优化UI组件的能力，使用React，并利用Next.js进行服务器端渲染和静态站点生成，并简化状态管理以提高性能","ja":"エージェントがReactを使用してUIコンポーネントを設計および最適化できるようにし、Next.jsを使用してサーバーサイドレンダリングと静的サイト生成を実行し、状態管理を簡素化してパフォーマンスを向上させる","ko":"에이전트가 리액트를 사용하여 UI 컴포넌트를 설계 및 최적화할 수 있도록 하며, Next.js를 사용하여 서버측 렌더링 및 정적 사이트 생성을 수행하며, 상태 관리를 간소화하여 성능을 향상시킴","es":"Permite a los agentes diseñar y optimizar componentes de interfaz de usuario utilizando React, aprovechando Next.js para renderizado del lado del servidor y generación de sitios web estáticos, y optimizando la gestión de estado para un mejor rendimiento","fr":"Permet aux agents de concevoir et d''optimiser des composants d''interface utilisateur en utilisant React, en exploitant Next.js pour le rendu du côté serveur et la génération de sites web statiques, et en optimisant la gestion d''état pour améliorer les performances","de":"Ermöglicht es Agenten, Benutzeroberflächen-Komponenten mit React zu entwerfen und zu optimieren, Next.js für Server-Seitige Rendering und statische Site-Generation nutzt und die Zustandsverwaltung für eine verbesserte Leistung optimiert","pt":"Habilita os agentes a projetarem e otimizarem componentes de UI usando React, aproveitando o Next.js para renderização do lado do servidor e geração de sites estáticos, e simplificando o gerenciamento de estado para um desempenho melhorado","ru":"Наделяет агентов возможностью проектировать и оптимизировать компоненты UI с помощью React, используя Next.js для серверной визуализации и генерации статических сайтов, а также оптимизируя управление состоянием для повышения производительности","ar":"يمكن الوكلاء من تصميم وتحسين مكونات واجهة المستخدم باستخدام React، واستخدام Next.js للترndering بالجانب الخلفي وتوليد المواقع الثابتة، وباستخدام إدارة الحالة لتعزيز الأداء"},"useCases":{"en":["Designing reusable UI components for web applications","Implementing server-side rendering with Next.js for improved SEO","Optimizing state management for complex React applications"],"zh":["为Web应用程序设计可重用的UI组件","使用Next.js实现服务器端渲染以提高SEO","优化复杂React应用程序的状态管理"],"ja":["Webアプリケーションの再利用可能なUIコンポーネントを設計する","Next.jsを使用してサーバーサイドレンダリングを実装してSEOを改善する","複雑なReactアプリケーションの状態管理を最適化する"],"ko":["웹 애플리케이션을 위한 재사용 가능한 UI 컴포넌트 설계","Next.js를 사용하여 서버측 렌더링을 구현하여 SEO를 개선","복잡한 리액트 애플리케이션의 상태 관리를 최적화"],"es":["Diseñar componentes de interfaz de usuario reutilizables para aplicaciones web","Implementar renderizado del lado del servidor con Next.js para mejorar el SEO","Optimizar la gestión de estado para aplicaciones React complejas"],"fr":["Concevoir des composants d''interface utilisateur réutilisables pour les applications web","Mettre en œuvre le rendu du côté serveur avec Next.js pour améliorer le SEO","Optimiser la gestion d''état pour des applications React complexes"],"de":["Wiederverwendbare Benutzeroberflächen-Komponenten für Webanwendungen entwerfen","Server-Seitige Rendering mit Next.js für verbessertes SEO implementieren","Zustandsverwaltung für komplexe React-Anwendungen optimieren"],"pt":["Projetar componentes de UI reutilizáveis para aplicações web","Implementar renderização do lado do servidor com Next.js para melhor SEO","Otimizar gerenciamento de estado para aplicações React complexas"],"ru":["Проектировать многократно используемые компоненты UI для веб-приложений","Реализовывать серверную визуализацию с помощью Next.js для улучшения SEO","Оптимизировать управление состоянием для сложных приложений React"],"ar":["تصميم مكونات واجهة المستخدم المعاد استخدامها لتطبيقات الويب","تنفيذ العرض بالجانب الخلفي مع Next.js لتحسين ترتيب البحث","تحسين إدارة الحالة لتطبيقات React المعقدة"]},"limitations":{"en":["Requires knowledge of JavaScript and React ecosystem","Dependent on specific project requirements for SSR, CSR, or SSG"],"zh":["需要JavaScript和React生态系统的知识","依赖于特定项目的SSR、CSR或SSG要求"],"ja":["JavaScriptとReactエコシステムの知識が必要","特定のプロジェクトの要件に依存してSSR、CSR、またはSSG"],"ko":["자바스크립트 및 리액트 생태계에 대한 지식이 필요","특정 프로젝트의 SSR, CSR 또는 SSG 요구 사항에 의존"],"es":["Requiere conocimiento de JavaScript y el ecosistema de React","Dependiente de los requisitos específicos del proyecto para SSR, CSR o SSG"],"fr":["Nécessite des connaissances en JavaScript et dans l''écosystème React","Dépend des exigences spécifiques du projet pour SSR, CSR ou SSG"],"de":["Benötigt Kenntnisse in JavaScript und dem React-Ökosystem","Abhängig von den spezifischen Projektanforderungen für SSR, CSR oder SSG"],"pt":["Exige conhecimento de JavaScript e ecossistema React","Depende de requisitos específicos do projeto para SSR, CSR ou SSG"],"ru":["Требует знания JavaScript и экосистемы React","Зависит от конкретных требований проекта для SSR, CSR или SSG"],"ar":["يتطلب معرفة جافا سكريبت وبيئة React","يعتمد على متطلبات مشروع محددة لSSR، CSR أو SSG"]},"version":3},"contentHash":"47811813e3043fa4017f0939cfbeab8f2ee06ed5e6ccd3c138b604bbdf3f98a2","qualityScore":18}');
