INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mae616/ai-template/react', 'react', 'mae616', 'ai-template', 'community', 'react mae616 ai-template community React是一个用于AI驱动的敏捷开发的模板，帮助开发者提高开发效率 Reactは、AIエージェントのコンテキスト駆動開発用テンプレートです React는 AI 에이전트의 애자일 개발 템플릿으로 개발 효율성을 높입니다 React es una herramienta de desarrollo ágil que utiliza plantillas de código y promtps de especificación de AI para mejorar la eficiencia React est un outil de développement agile qui utilise des modèles de code et des promtps de spécification d''IA pour améliorer l''efficacité React ist ein Tool für agiles Entwicklung, das Code-Vorlagen und AI-Spezifikationsprompts verwendet, um die Effizienz zu verbessern O React é uma biblioteca JavaScript para construir interfaces de usuário, agora integrada à inteligência artificial para desenvolvedores. React - это библиотека JavaScript для построения интерфейсов пользователя, теперь интегрированная с ИИ для разработчиков. رياكت هو مكتبة جافاسكريبت لإنشاء واجهات المستخدم، الآن متوفرة مع الذكاء الاصطناعي لمطوري البرمجيات. Feedback only OSS。コンテキスト駆動開発(アジャイル仕様開発)用テンプレート。AIの思考仕様のプロンプト。 如何使用React进行AI驱动的敏捷开发 React的优点 React vs 其他AI开发工具 React安装指南 React开发教程 AI驱动的敏捷开发的优势 Feedback only OSS。コンテキスト駆動開発(アジャイル仕様開発)用テンプレート。AIの思考仕様のプロンプト。');
