INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgreenly/ikigai/patterns/adapter', 'patterns/adapter', 'mgreenly', 'ikigai', 'community', 'patterns/adapter mgreenly ikigai community AI编码代理的Patterns/Adapter技能可以帮助开发者提高编码效率 AIエージェントのPatterns/Adapterスキルは、開発者のコーディング効率を向上させる AI 코딩 에이전트의 Patterns/Adapter 기능은 개발자의 코딩 효율성을 향상시킵니다 El agente de codificación AI para patrones de adaptador es una herramienta de desarrollo que utiliza inteligencia artificial para mejorar la codificación L''agent de codage IA pour modèles d''adaptateur est un outil de développement qui utilise l''intelligence artificielle pour améliorer la codification Der AI-Coding-Agent für Adapter-Muster ist ein Entwicklungstool, das künstliche Intelligenz zur Verbesserung der Codierung verwendet O patterns/adapter é um agente de codificação AI que auxilia nos projetos de desenvolvimento ИИ Агент patterns/adapter - это инструмент, помогающий в разработке проектов patterns/adapter هو أداة الذكاء الاصطناعي التي تساعد في مشاريع التطوير An AI Coding Agent AI编码代理 Patterns/Adapter 如何使用AI编码代理 AI编码代理安装 AI编码代理设置指南 AI编码代理替代品 AI编码代理与其他工具的比较 An AI Coding Agent');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MykolaPinchuk/QAMAS/onboard', 'community', 'MykolaPinchuk', 'QAMAS', 'MykolaPinchuk/QAMAS', 'onboard', 0, 0, 18, '2026-03-01T02:12:36.557Z', '2026-03-01T03:21:46.727Z', '9f091fbaf4a6d38bb6547e54b0d2d78cb2ce7cdc2ea07a6239e622e53d078008', '{"id":"MykolaPinchuk/QAMAS/onboard","name":"onboard","description":{"zh":"onboard是VSC Codex中的Q/A MAS工具仓库，用于AI智能代理开发。它提供了开发者所需的工具和资源","ja":"onboardはVSC CodexのQ/A MASツールリポジトリで、AIエージェント開発に特化しています。開発者に必要なツールとリソースを提供","ko":"onboard는 VSC Codex의 Q/A MAS 도구 저장소로, AI 에이전트 개발을 위한 최적의 도구입니다. 개발자에게 필요한 도구와 리소스를 제공","es":"Onboard es una herramienta de inteligencia artificial para Q/A MAS en VSC Codex, que facilita la integración y el análisis de datos","fr":"Onboard est un outil d''intelligence artificielle pour Q/A MAS dans VSC Codex, qui facilite l''intégration et l''analyse des données","de":"Onboard ist ein KI-Tool für Q/A-MAS in VSC Codex, das die Integration und Analyse von Daten erleichtert","pt":"O Onboard é uma ferramenta de Q/A MAS em VSC Codex para desenvolvedores","ru":"Onboard - это инструмент Q/A MAS в VSC Codex для разработчиков","ar":"اللوحة Onboard هي أداة Q/A MAS في VSC Codex لمطوري البرامج","en":"Repo for Q/A MAS tool in VSC Codex"},"seo":{"title":{"zh":"AI智能代理工具onboard","ja":"AIエージェントonboard","ko":"AI 에이전트 온보딩","es":"Herramientas de Inteligencia Artificial: Onboard para Q/A...","fr":"Outils d''Intelligence Artificielle: Onboard pour Q/A MAS","de":"KI-Tools: Onboard für Q/A MAS","pt":"Ferramentas de IA: Onboard para Q/A MAS","ru":"ИИ Агенты: Onboard для Q/A MAS","ar":"أدوات الذكاء الاصطناعي: Onboard للقسم Q/A MAS","en":"onboard"},"description":{"zh":"onboard是VSC Codex中的Q/A MAS工具仓库，用于AI智能代理开发。它提供了开发者所需的工具和资源","ja":"onboardはVSC CodexのQ/A MASツールリポジトリで、AIエージェント開発に特化しています。開発者に必要なツールとリソースを提供","ko":"onboard는 VSC Codex의 Q/A MAS 도구 저장소로, AI 에이전트 개발을 위한 최적의 도구입니다. 개발자에게 필요한 도구와 리소스를 제공","es":"Onboard es una herramienta de inteligencia artificial para Q/A MAS en VSC Codex, que facilita la integración y el análisis de datos","fr":"Onboard est un outil d''intelligence artificielle pour Q/A MAS dans VSC Codex, qui facilite l''intégration et l''analyse des données","de":"Onboard ist ein KI-Tool für Q/A-MAS in VSC Codex, das die Integration und Analyse von Daten erleichtert","pt":"O Onboard é uma ferramenta de Q/A MAS em VSC Codex para desenvolvedores","ru":"Onboard - это инструмент Q/A MAS в VSC Codex для разработчиков","ar":"اللوحة Onboard هي أداة Q/A MAS في VSC Codex لمطوري البرامج","en":"Repo for Q/A MAS tool in VSC Codex"},"definition":{"en":"Repo for Q/A MAS tool in VSC Codex"},"features":{"zh":["支持VSC Codex","Q/A MAS工具集成","AI智能代理开发","开发者资源提供","简单易用的界面"],"ja":["VSC Codex対応","Q/A MASツールの統合","AIエージェント開発","開発者リソースの提供","シンプルで使いやすいインターフェース"],"ko":["VSC Codex 지원","Q/A MAS 도구 통합","AI 에이전트 개발","개발자 리소스 제공","간단하고 사용하기 쉬운 인터페이스"],"es":["Integración con VSC Codex","Análisis de datos avanzado","Herramientas de inteligencia artificial para Q/A MAS","Facilidad de uso y configuración","Compatibilidad con múltiples formatos de datos"],"fr":["Intégration avec VSC Codex","Analyse de données avancée","Outils d''intelligence artificielle pour Q/A MAS","Facilité d''utilisation et de configuration","Compatibilité avec plusieurs formats de données"],"de":["Integration mit VSC Codex","Erweiterte Datenanalyse","KI-Tools für Q/A-MAS","Einfache Bedienung und Konfiguration","Unterstützung für multiple Datenformate"],"pt":["Desenvolvimento de ferramentas de Q/A MAS","Integração com VSC Codex","Suporte a desenvolvedores","Ferramentas de teste e depuração","Documentação e suporte técnico"],"ru":["Разработка инструментов Q/A MAS","Интеграция с VSC Codex","Поддержка разработчиков","Инструменты тестирования и отладки","Документация и техническая поддержка"],"ar":["تطوير أدوات Q/A MAS","التكامل مع VSC Codex","دعم المطورين","أدوات الاختبار والتصحيح","التوثيق والدعم الفني"]},"keywords":{"zh":["AI智能代理","onboard工具","VSC Codex","Q/A MAS","AI开发","AI模型管理","onboard安装","onboard设置指南"],"ja":["AIエージェント","onboardツール","VSC Codex","Q/A MAS","AI開発","AIモデル管理","onboardのインストール","onboardの設定ガイド"],"ko":["AI 에이전트","onboard 도구","VSC Codex","Q/A MAS","AI 개발","AI 모델 관리","onboard 설치","onboard 설정 가이드"],"es":["herramientas de inteligencia artificial","onboard para Q/A MAS","VSC Codex","cómo usar Onboard","alternativas a Onboard","Onboard vs otras herramientas","instalación de Onboard","guía de configuración de Onboard"],"fr":["outils d''intelligence artificielle","Onboard pour Q/A MAS","VSC Codex","comment utiliser Onboard","alternatives à Onboard","Onboard vs autres outils","installation d''Onboard","guide de configuration d''Onboard"],"de":["KI-Tools","Onboard für Q/A-MAS","VSC Codex","wie man Onboard verwendet","Alternativen zu Onboard","Onboard vs andere Tools","Onboard-Installation","Onboard-Konfigurationsanleitung"],"pt":["ferramentas de IA","desenvolvimento de ferramentas de Q/A MAS","VSC Codex","Onboard","Q/A MAS","desenvolvedores","ferramentas de teste e depuração"],"ru":["ИИ Агенты","разработка инструментов Q/A MAS","VSC Codex","Onboard","Q/A MAS","разработчики","инструменты тестирования и отладки"],"ar":["أدوات الذكاء الاصطناعي","تطوير أدوات Q/A MAS","VSC Codex","اللوحة Onboard","Q/A MAS","مطوري البرامج","أدوات الاختبار والتصحيح"]}},"owner":"MykolaPinchuk","repo":"QAMAS","repoPath":"MykolaPinchuk/QAMAS","stars":0,"forks":0,"updatedAt":"2026-03-01T02:12:36.557Z","topics":[],"category":"community","skillMd":{"name":"onboard","description":"Deterministic onboarding for this repo (read minimal index files first, then bounded discovery).","bodyPreview":"When invoked (or when the user says `Onboard`), do this exactly:\n\n1) Read (in order, if present):\n- `agents.md` (if not already in context)\n- `repo_workflow.md`\n- `onboarding.md`\n- `HANDOFF.md`\n- `REPO_MAP.md`\n- `a2a_notes.md`\n- `README.md` (focus on \"For agents\")\n- `QAMAS_PRD.md`\n- `QAMAS_IMPLEMENTATION.md`\n\n2) Bounded discovery:\n- Identify up to 10 additional files needed for the current slice.\n- Print the list (file path + 1-line reason each).\n- Open only those files after listing them.\n- Do","body":"When invoked (or when the user says `Onboard`), do this exactly:\n\n1) Read (in order, if present):\n- `agents.md` (if not already in context)\n- `repo_workflow.md`\n- `onboarding.md`\n- `HANDOFF.md`\n- `REPO_MAP.md`\n- `a2a_notes.md`\n- `README.md` (focus on \"For agents\")\n- `QAMAS_PRD.md`\n- `QAMAS_IMPLEMENTATION.md`\n\n2) Bounded discovery:\n- Identify up to 10 additional files needed for the current slice.\n- Print the list (file path + 1-line reason each).\n- Open only those files after listing them.\n- Do not perform broad repo scans.\n\n3) Output contract:\n- 5 bullets: current state summary\n- 3 options: next slice choices (each 1-2 bullets)\n- files read (including the bounded discovery list)\n- unknowns/risks (<= 5 bullets)\n\n4) Log:\n- Append an entry to `agent_logs/current.md` with intent and next steps.\n"},"lastSynced":"2026-03-01T03:21:46.727Z","agentAnalysis":{"suitability":{"en":"Ideal for Knowledge Retrieval Agents requiring comprehensive onboarding processes through markdown files like agents.md, onboarding.md, and README.md.","zh":"适用于需要通过markdown文件（如agents.md、onboarding.md和README.md）进行全面入职流程的知识检索代理。","ja":"マークダウンファイル（例：agents.md、onboarding.md、README.md）を介した包括的なオンボーディングプロセスを必要とするナレッジリトリーバルエージェントに最適です。","ko":"마크다운 파일(예: agents.md, onboarding.md, README.md)을 통해 포괄적인 온보딩 프로세스가 필요한 지식 검색 에이전트에 적합합니다.","es":"Ideal para Agentes de Recuperación de Conocimiento que requieren procesos de incorporación exhaustivos a través de archivos markdown como agents.md, onboarding.md y README.md.","fr":"Idéal pour les Agents de Recherche de Connaissances nécessitant des processus d''intégration complets via des fichiers markdown tels que agents.md, onboarding.md et README.md.","de":"Ideal für Wissensabruf-Agenten, die umfassende Onboarding-Prozesse durch Markdown-Dateien wie agents.md, onboarding.md und README.md erfordern.","pt":"Ideal para Agentes de Recuperação de Conhecimento que exigem processos de integração abrangentes por meio de arquivos markdown, como agents.md, onboarding.md e README.md.","ru":"Идеально для агентов поиска знаний, требующих комплексных процессов адаптации через файлы markdown, такие как agents.md, onboarding.md и README.md.","ar":"مثالي لعمليات وكيل استرجاع المعرفة التي تتطلب عمليات إعداد شاملة من خلال ملفات markdown مثل agents.md و onboarding.md و README.md."},"recommendation":{"en":"Enables agents to perform bounded discovery of up to 10 additional files, such as repo_workflow.md and QAMAS_PRD.md, facilitating efficient knowledge acquisition through markdown file analysis and VSC Codex integration.","zh":"使代理能够执行最多10个额外文件（如repo_workflow.md和QAMAS_PRD.md）的有界发现，通过对markdown文件的分析和VSC Codex集成，实现高效的知识获取。","ja":"エージェントが最大10個の追加ファイル（例：repo_workflow.md、QAMAS_PRD.md）に対する境界付きの発見を実行できるようにし、マークダウンファイルの分析とVSC Codexの統合を通じて効率的なナレッジの取得を促進します。","ko":"에이전트가 최대 10개의 추가 파일(예: repo_workflow.md, QAMAS_PRD.md)에 대한 경계있는 발견을 수행할 수 있도록 하여 마크다운 파일 분석 및 VSC Codex 통합을 통해 효율적인 지식 습득을促進합니다.","es":"Permite a los agentes realizar un descubrimiento limitado de hasta 10 archivos adicionales, como repo_workflow.md y QAMAS_PRD.md, lo que facilita la adquisición eficiente de conocimientos a través del análisis de archivos markdown y la integración de VSC Codex.","fr":"Permet aux agents d''effectuer une découverte limitée d''un maximum de 10 fichiers supplémentaires, tels que repo_workflow.md et QAMAS_PRD.md, ce qui facilite l''acquisition efficace de connaissances via l''analyse de fichiers markdown et l''intégration de VSC Codex.","de":"Ermöglicht es Agenten, eine begrenzte Entdeckung von bis zu 10 zusätzlichen Dateien wie repo_workflow.md und QAMAS_PRD.md durchzuführen, was eine effiziente Wissensakquise durch Markdown-Dateianalyse und VSC-Codex-Integration ermöglicht.","pt":"Permite que os agentes realizem descoberta limitada de até 10 arquivos adicionais, como repo_workflow.md e QAMAS_PRD.md, facilitando a aquisição eficiente de conhecimento por meio da análise de arquivos markdown e integração com o VSC Codex.","ru":"Позволяет агентам выполнять ограниченное открытие до 10 дополнительных файлов, таких как repo_workflow.md и QAMAS_PRD.md, облегчая эффективное приобретение знаний посредством анализа файлов markdown и интеграции с VSC Codex.","ar":"يمكن للوكيلاء أداء اكتشاف محدود لما يصل إلى 10 ملفات إضافية، مثل repo_workflow.md و QAMAS_PRD.md، وتسهيل اكتساب المعرفة بفعالية من خلال تحليل ملفات markdown ودمج VSC Codex."},"useCases":{"en":["Onboarding new agents through automated markdown file reading","Identifying essential files for knowledge acquisition using bounded discovery","Streamlining agent workflow by focusing on critical files like HANDOFF.md and REPO_MAP.md"],"zh":["通过自动化的markdown文件阅读来入职新代理","使用有界发现来识别知识获取所需的必备文件","通过关注关键文件（如HANDOFF.md和REPO_MAP.md）来优化代理工作流程"],"ja":["自動化されたマークダウンファイルの読み取りを通じて新しいエージェントをオンボードする","境界付きの発見を使用してナレッジ取得に必要な必須ファイルを識別する","重要なファイル（例：HANDOFF.md、REPO_MAP.md）に焦点を当てることでエージェントのワークフローを最適化する"],"ko":["자동화된 마크다운 파일 읽기를 통해 새로운 에이전트를 온보딩하는 것","경계있는 발견을 사용하여 지식 습득에 필요한 필수 파일을 식별하는 것","중요한 파일(예: HANDOFF.md, REPO_MAP.md)에 초점을 맞추어 에이전트의 워크플ロー 최적화"],"es":["Incorporación de nuevos agentes a través de la lectura automática de archivos markdown","Identificación de archivos esenciales para la adquisición de conocimientos utilizando la exploración limitada","Optimización del flujo de trabajo del agente centrándose en archivos críticos como HANDOFF.md y REPO_MAP.md"],"fr":["Intégration de nouveaux agents via la lecture automatisée de fichiers markdown","Identification de fichiers essentiels pour l''acquisition de connaissances en utilisant la découverte limitée","Optimisation du flux de travail de l''agent en se concentrant sur des fichiers critiques comme HANDOFF.md et REPO_MAP.md"],"de":["Onboarding neuer Agenten durch automatisierte Markdown-Dateilesung","Identifizierung wesentlicher Dateien für die Wissensakquise unter Verwendung der begrenzten Entdeckung","Optimierung des Agenten-Workflows durch Fokussierung auf kritische Dateien wie HANDOFF.md und REPO_MAP.md"],"pt":["Integração de novos agentes por meio da leitura automatizada de arquivos markdown","Identificação de arquivos essenciais para aquisição de conhecimento usando descoberta limitada","Otimização do fluxo de trabalho do agente, focando em arquivos críticos como HANDOFF.md e REPO_MAP.md"],"ru":["Интеграция новых агентов посредством автоматического чтения файлов markdown","Определение необходимых файлов для приобретения знаний с помощью ограниченного открытия","Оптимизация рабочего процесса агента, сосредоточив внимание на критических файлах, таких как HANDOFF.md и REPO_MAP.md"],"ar":["دمج وكيلاء جدد من خلال قراءة الملفات التلقائية markdown","تحديد الملفات الأساسية لاكتساب المعرفة باستخدام الاكتشاف المحدود","تحسين تدفق عمل الوكيل من خلال التركيز على الملفات الحيوية مثل HANDOFF.md و REPO_MAP.md"]},"limitations":{"en":["Requires access to specific markdown files","Limited to reading up to 10 additional files during bounded discovery","Dependent on VSC Codex for repository workflow"],"zh":["需要访问特定的markdown文件","有界发现过程中最多只能读取10个额外文件","依赖VSC Codex进行仓库工作流程"],"ja":["特定マークダウンファイルへのアクセスが必要","境界付きの発見の際に最大10個の追加ファイルしか読み取れない","リポジトリのワークフローにVSC Codexに依存している"],"ko":["특정 마크다운 파일에 대한 액세스가 필요합니다","경계있는 발견 중 최대 10개의 추가 파일만 읽을 수 있습니다","仓库 워크플로에 VSC Codex에 의존"],"es":["Requiere acceso a archivos markdown específicos","Limitado a la lectura de hasta 10 archivos adicionales durante la exploración limitada","Dependiente de VSC Codex para el flujo de trabajo del repositorio"],"fr":["Nécessite l''accès à des fichiers markdown spécifiques","Limité à la lecture d''un maximum de 10 fichiers supplémentaires lors de la découverte limitée","Dépendant de VSC Codex pour le flux de travail du référentiel"],"de":["Erfordert Zugriff auf bestimmte Markdown-Dateien","Begrenzt auf das Lesen von bis zu 10 zusätzlichen Dateien während der begrenzten Entdeckung","Abhängig von VSC Codex für den Repository-Workflow"],"pt":["Exige acesso a arquivos markdown específicos","Limitado à leitura de até 10 arquivos adicionais durante a descoberta limitada","Dependente do VSC Codex para fluxo de trabalho do repositório"],"ru":["Требует доступа к конкретным файлам markdown","Ограничен чтением до 10 дополнительных файлов во время ограниченного открытия","Зависит от VSC Codex для рабочего процесса репозитория"],"ar":["يتطلب الوصول إلى ملفات markdown محددة","محدود بقراءة ما يصل إلى 10 ملفات إضافية خلال الاكتشاف المحدود","يعتمد على VSC Codex لتدفق عمل المستودع"]},"version":3},"contentHash":"9f091fbaf4a6d38bb6547e54b0d2d78cb2ce7cdc2ea07a6239e622e53d078008","qualityScore":18}');
