INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fermaf/cgr/cgr-docs-governance', 'cgr-docs-governance', 'fermaf', 'cgr', 'community', 'cgr-docs-governance fermaf cgr community cgr-docs-governance是一种Jurisprudencia Administrativa的AI智能工具，帮助开发者提高效率 cgr-docs-governanceはJurisprudencia AdministrativaのAIエージェントであり、開発者の効率を向上させるために設計されたものです cgr-docs-governance는 Jurisprudencia Administrativa의 AI 에이전트로 개발자에게 효율성을 높여줍니다 cgr-docs-governance es una herramienta de inteligencia artificial que ayuda a mejorar la toma de decisiones en Jurisprudencia Administrativa. cgr-docs-governance est un outil d''intelligence artificielle qui aide à améliorer la prise de décision en matière de jurisprudence administrative. cgr-docs-governance ist ein künstliches Intelligenz-Tool, das die Entscheidungsfindung im Verwaltungsrecht verbessert. O cgr-docs-governance é uma ferramenta de IA que ajuda na Jurisprudencia Administrativa, fornecendo recursos para desenvolvedores. cgr-docs-governance - это инструмент ИИ, помогающий в Административной Юриспруденции, предоставляющий ресурсы для разработчиков. cgr-docs-governance هو أداة ذكاء اصطناعي تساعد في Jurisprudencia Administrativa، وتوفر موارد للمطورين. Jurisprudencia Administrativa 如何使用cgr-docs-governance 什么是Jurisprudencia Administrativa cgr-docs-governance替代品 cgr-docs-governance vs 其他工具 cgr-docs-governance安装 cgr-docs-governance设置指南 AI智能工具 开发效率提高 Jurisprudencia Administrativa');
